insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-002', null, 'Tablas', 'En una tabla de Access, ¿cómo se denomina cada fila?', array['Campo', 'Registro', 'Índice', 'Clave']::text[], 1, 'La página indica: «Cada fila de una tabla se denomina registro». Además, «Los campos equivalen a las columnas de la tabla».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
