insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-011', null, 'Tipos de datos', '¿Qué tipo de datos contiene un valor único generado por Access para cada registro nuevo?', array['Número grande', 'Calculado', 'Autonumeración', 'Asistente para búsquedas']::text[], 2, 'La página describe Autonumeración como «Valor único generado por Access para cada registro nuevo».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
