insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-012', null, 'Tipos de datos', 'En la columna de tipo de datos de la vista Diseño, ¿qué entrada no es realmente un tipo de datos?', array['Fecha y hora extendida', 'Número grande', 'Datos adjuntos', 'Asistente para búsquedas']::text[], 3, 'La página aclara: «La entrada del Asistente para búsquedas en la columna de tipo de datos en la vista Diseño no es realmente un tipo de datos». Inicia un asistente para definir un campo de búsqueda.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
