insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-013', null, 'Tipos de relaciones de tablas', 'Un cliente puede hacer cualquier número de pedidos. ¿Qué relación hay entre las tablas Clientes y Pedidos?', array['Uno a varios', 'Uno a uno', 'Varios a varios', 'No hay relación entre ellas']::text[], 0, 'La página lo explica con ese ejemplo: «la relación entre la tabla Clientes y la tabla Pedidos es una relación de uno a varios».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
