insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-014', null, 'Tipos de relaciones de tablas', '¿Cómo se representa en Access una relación varios a varios?', array['Con la clave principal de cada tabla en la otra', 'Con una tercera tabla, la tabla de unión', 'Uniendo las dos tablas en una sola', 'Exigiendo la integridad referencial en ambas']::text[], 1, 'Para representarla «debe crear una tercera tabla, a menudo denominada tabla de unión, que divide la relación de varios a varios en dos relaciones uno a varios».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
