insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-015', null, 'Descripción de la integridad referencial', '¿Cuál es el propósito de la integridad referencial?', array['Impedir valores repetidos en un campo', 'Acelerar la ejecución de las consultas', 'Evitar los registros huérfanos', 'Ocultar tablas en la ventana Relaciones']::text[], 2, 'La página indica: «El propósito de la integridad referencial es evitar los registros huérfanos y mantener las referencias sincronizadas».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
