insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-016', null, 'Descripción de la integridad referencial', 'Con la integridad referencial exigida, ¿qué opción hace que, al eliminar un registro del lado de la clave principal, se eliminen sus registros relacionados?', array['Actualizar en cascada los campos relacionados', 'Borrar diseño', 'Ocultar tabla', 'Eliminar en cascada los registros relacionados']::text[], 3, 'Con la opción Eliminar en cascada los registros relacionados, al eliminar un registro en el lado de la clave principal, «Access elimina automáticamente todos los registros que hacen referencia a la clave principal».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
