insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-017', null, 'Ver relaciones de tablas', '¿En qué pestaña de la cinta está el comando Relaciones, que abre la ventana Relaciones?', array['Herramientas de base de datos', 'Datos externos', 'Diseño de presentación de formulario', 'Crear']::text[], 0, 'La página indica: «Para ver las relaciones de tablas, haga clic en Relaciones en la pestaña Herramientas de base de datos».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
