insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-018', null, 'Ver relaciones de tablas', 'En la ventana Relaciones, ¿qué hace el comando Borrar diseño?', array['Elimina todas las relaciones de la base de datos', 'Oculta las tablas y relaciones, sin eliminarlas', 'Elimina las tablas que no tienen relaciones', 'Quita la integridad referencial de las relaciones']::text[], 1, 'Borrar diseño «Quita todas las tablas y relaciones para que no se muestren en la ventana Relaciones». La página precisa que «este comando solo oculta las relaciones y tablas, no las elimina».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
