insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-019', null, 'Crear una consulta de parámetros', 'En una consulta de parámetros, ¿qué se escribe en la fila Criterios para que la consulta pida la ciudad al ejecutarse?', array['(¿Qué ciudad?)', '{¿Qué ciudad?}', '[¿Qué ciudad?]', '<¿Qué ciudad?>']::text[], 2, 'La cadena entre corchetes es la petición de parámetros: «Los corchetes indican que quiere que la consulta pida información».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
