insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-020', null, 'Crear una consulta de totales', 'En la pestaña Diseño de consulta, ¿en qué grupo está el botón Totales, que muestra la fila Totales en la cuadrícula de diseño?', array['Resultados', 'Tipo de consulta', 'Configuración de consulta', 'Mostrar u ocultar']::text[], 3, 'Se hace clic en Totales del grupo Mostrar u ocultar y «Aparece la fila Totales en la cuadrícula de diseño de la consulta».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
