insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-021', null, 'Crear una consulta de tabla de referencias cruzadas', '¿Qué tipo de consulta permite ver los subtotales de cada producto en filas y los de cada mes en columnas?', array['Tabla de referencias cruzadas', 'Consulta de totales', 'Consulta de creación de tabla', 'Consulta de datos anexados']::text[], 0, 'La página indica: «Para mostrar los subtotales de un producto y los subtotales de productos de un mes, usa una consulta de tabla de referencias cruzadas».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
