insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-022', null, 'Crear una consulta de actualización', '¿Qué advierte Microsoft sobre las consultas de acciones, como las de actualización?', array['Que no admiten criterios', 'Que no se pueden deshacer', 'Que solo afectan a una fila', 'Que no modifican las tablas']::text[], 1, 'La página advierte: «Las consultas de acciones no se pueden deshacer». Recomienda hacer una copia de seguridad de las tablas que se van a actualizar.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
