insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-024', null, 'Crear un formulario dividido en Access', '¿Qué tipo de formulario muestra a la vez una vista Formulario y una vista Hoja de datos?', array['Formulario de navegación', 'Formulario en blanco', 'Formulario de varios elementos', 'Formulario dividido']::text[], 3, 'La página indica: «Un formulario dividido proporciona dos vistas de los datos al mismo tiempo: una vista Formulario y una vista Hoja de datos».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
