insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-025', null, 'Crear un formulario a partir de una tabla o consulta existente en Access', 'Si selecciona una tabla en el panel de navegación y hace clic en Crear > Formulario, ¿en qué vista abre Access el formulario?', array['Vista Presentación', 'Vista Diseño', 'Vista Hoja de datos', 'Vista Formulario']::text[], 0, 'Tras hacer clic en Formulario en la pestaña Crear, «Access crea un formulario y lo abre en la vista Presentación».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
