insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-026', null, 'Crear un formulario que muestre varios registros en Access', '¿Con qué otro nombre se conoce el formulario de varios elementos?', array['Formulario dividido', 'Formulario continuo', 'Subformulario', 'Formulario de navegación']::text[], 1, 'La página indica: «Un formulario de varios elementos, también conocido como formulario continuo, resulta útil cuando se necesita disponer de un formulario que muestre varios registros».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
