insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-027', null, 'Comprender la importación y vinculación a datos desde otra base de datos de Access', 'Al importar datos desde otra base de datos de Access, ¿qué hace Access?', array['Mueve los datos y los borra del origen', 'Crea un vínculo que refleja los cambios del origen', 'Crea una copia de los datos sin cambiar el origen', 'Sustituye las tablas de destino con el mismo nombre']::text[], 2, 'La página indica: «Al realizar una importación desde otra base de datos, Access crea una copia de los datos en la base de datos de destino sin cambiar el origen».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
