insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-028', null, 'Vincular a datos en otra base de datos de Access', '¿Qué no se puede hacer con una tabla vinculada en la base de datos de destino?', array['Ver sus registros', 'Modificar sus datos', 'Usarla en una consulta', 'Cambiar su estructura']::text[], 3, 'Los cambios en los datos se reflejan en ambas bases de datos, pero «no se puede cambiar la estructura de una tabla vinculada en la base de datos de destino».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
