insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-029', null, 'Vincular a datos en otra base de datos de Access', '¿Qué objetos de otra base de datos de Access se pueden vincular?', array['Solo las tablas', 'Tablas y consultas', 'Tablas, consultas y formularios', 'Todos sus objetos, incluidos los módulos']::text[], 0, 'La página indica: «Solo puede crear vínculos a tablas de otra base de datos de Access. No puede crear vínculos a consultas, formularios, informes, macros o módulos».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
