insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-030', null, 'Comprender la importación y vinculación a datos desde otra base de datos de Access', 'Quiere añadir los registros de otra base de datos a una tabla que ya existe. ¿Qué indica Microsoft?', array['Importarlos eligiendo la opción Sólo definición', 'Importarlos a una tabla nueva y usar una consulta de datos anexados', 'Vincular la tabla de origen sobre la tabla existente', 'Importarlos con la casilla Relaciones activada']::text[], 1, 'Se pueden importar los registros a una tabla nueva «y, después, crear una consulta de datos anexados». La página aclara: «No puede anexar registros a una tabla existente durante una operación de importación».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
