insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-026', (select id from leyes where slug = 'ley-40-2015'), '42.b', 'Además del sello electrónico, en la actuación administrativa automatizada puede usarse como sistema de firma:', array['La firma manuscrita digitalizada', 'La clave concertada del interesado', 'El certificado de sitio web', 'El código seguro de verificación']::text[], 3, 'El artículo 42 admite el sello electrónico y el «Código seguro de verificación vinculado a la Administración Pública, órgano, organismo público o entidad de Derecho Público».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ae-026', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 20 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-027', (select id from leyes where slug = 'ley-40-2015'), '43.2', 'Por razones de seguridad pública, los sistemas de firma del personal pueden referirse solo a:', array['Su número de registro de personal', 'Su número de identificación profesional', 'La denominación del puesto que ocupa', 'El NIF de la Administración en que sirve']::text[], 1, 'El artículo 43.2 dispone: «Por razones de seguridad pública los sistemas de firma electrónica podrán referirse sólo el número de identificación profesional del empleado público».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
