insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-028', (select id from leyes where slug = 'ley-40-2015'), '44.3', 'En el intercambio de datos en entornos cerrados entre distintas Administraciones, las condiciones y garantías se fijan mediante:', array['Real decreto del Gobierno', 'Acuerdo de la Conferencia Sectorial', 'Convenio suscrito entre ellas', 'Orden del departamento competente']::text[], 2, 'El artículo 44.3 indica que, si los participantes son de distintas Administraciones, las condiciones «se establecerán mediante convenio suscrito entre aquellas».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
