insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-029', (select id from leyes where slug = 'ley-40-2015'), '46.1', 'Los documentos utilizados en las actuaciones administrativas se almacenarán:', array['En papel, con copia electrónica auténtica', 'Por medios electrónicos solo si afectan a derechos', 'En el archivo central, en el soporte original', 'Por medios electrónicos, salvo cuando no sea posible']::text[], 3, 'El artículo 46.1 dispone: «Todos los documentos utilizados en las actuaciones administrativas se almacenarán por medios electrónicos, salvo cuando no sea posible».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ae-029', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 20 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-030', (select id from leyes where slug = 'ley-40-2015'), '46.3', 'Las medidas de seguridad de los soportes de documentos electrónicos se ajustarán a lo previsto en:', array['El Esquema Nacional de Seguridad', 'El Esquema Nacional de Interoperabilidad', 'La Ley de Patrimonio Histórico', 'El Reglamento de registros']::text[], 0, 'El artículo 46.3 exige medidas de seguridad «de acuerdo con lo previsto en el Esquema Nacional de Seguridad».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
