insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-001', (select id from leyes where slug = 'ley-40-2015'), '55.4', 'Los Subdelegados del Gobierno en las provincias tienen nivel de:', array['Subdirector general', 'Director general', 'Subsecretario', 'Secretario general técnico']::text[], 0, 'El artículo 55.4 dispone que los Subdelegados del Gobierno en las provincias «tendrán nivel de Subdirector general».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
