insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-002', (select id from leyes where slug = 'ley-40-2015'), '55 bis', 'En cada departamento ministerial, los nombramientos de Secretarías de Estado y órganos directivos respetarán que las personas de cada sexo:', array['No superen el setenta por ciento ni sean menos del treinta por ciento', 'No superen el sesenta por ciento ni sean menos del cuarenta por ciento', 'No superen el cincuenta y cinco por ciento ni sean menos del cuarenta y cinco', 'Representen exactamente el cincuenta por ciento']::text[], 1, 'El artículo 55 bis exige que «las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento en el ámbito de cada departamento ministerial».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'age-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-003', (select id from leyes where slug = 'ley-40-2015'), '55.9', 'Corresponde a los órganos superiores establecer los planes de actuación. ¿Qué corresponde a los órganos directivos?', array['Su aprobación definitiva', 'Su evaluación y control de eficacia', 'Su desarrollo y ejecución', 'Su financiación presupuestaria']::text[], 2, 'Según el artículo 55.9, «corresponde a los órganos superiores establecer los planes de actuación de la organización situada bajo su responsabilidad y a los órganos directivos su desarrollo y ejecución».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'age-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-004', (select id from leyes where slug = 'ley-40-2015'), '58.2', 'Según la Ley 40/2015, los Ministerios contarán en todo caso con:', array['Una Secretaría de Estado y, dependiendo de ella, una Secretaría General', 'Una Subsecretaría y, dependiendo de ella, una Secretaría General', 'Una Secretaría General y, dependiendo de ella, una Dirección General', 'Una Subsecretaría y, dependiendo de ella, una Secretaría General Técnica']::text[], 3, 'El artículo 58.2 establece que «los Ministerios contarán, en todo caso, con una Subsecretaría, y dependiendo de ella una Secretaría General Técnica, para la gestión de los servicios comunes».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'age-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-005', (select id from leyes where slug = 'ley-40-2015'), '59.2', 'Los órganos de nivel inferior a Subdirección General se crean, modifican y suprimen:', array['Por Real Decreto del Consejo de Ministros', 'Por orden del Ministro respectivo', 'Por resolución del Subsecretario', 'Mediante las relaciones de puestos de trabajo']::text[], 1, 'El artículo 59.2 dispone que «los órganos de nivel inferior a Subdirección General se crean, modifican y suprimen por orden del Ministro respectivo, previa autorización del Ministro de Hacienda y Administraciones Públicas».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
