insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-006', (select id from leyes where slug = 'ley-40-2015'), '59.1', 'Las Direcciones Generales y las Subdirecciones Generales se crean, modifican y suprimen por:', array['Real Decreto del Presidente del Gobierno', 'Orden del Ministro interesado', 'Ley de las Cortes Generales', 'Real Decreto del Consejo de Ministros']::text[], 3, 'Según el artículo 59.1, estos órganos «se crean, modifican y suprimen por Real Decreto del Consejo de Ministros, a iniciativa del Ministro interesado».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
