insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-010', (select id from leyes where slug = 'ley-40-2015'), '63.3', 'Los Subsecretarios se nombran entre funcionarios de carrera del Estado, de las Comunidades Autónomas o de las Entidades locales del:', array['Subgrupo A1', 'Subgrupo A2', 'Grupo A, en cualquiera de sus subgrupos', 'Grupo B']::text[], 0, 'Según el artículo 63.3, los nombramientos de Subsecretarios se hacen entre funcionarios de carrera «pertenecientes al Subgrupo A1», o entre quienes hubieran perdido esa condición por jubilación.', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
