insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-011', (select id from leyes where slug = 'ley-40-2015'), '64.3', 'Los Secretarios generales de los Ministerios se nombran entre:', array['Funcionarios de carrera del Subgrupo A1 del Estado, de las Comunidades Autónomas o de las Entidades locales', 'Funcionarios de carrera del Estado con al menos diez años de servicio en el Subgrupo A1', 'Funcionarios de carrera de los Subgrupos A1 o A2 de cualquier Administración', 'Personas con cualificación y experiencia en puestos de responsabilidad en la gestión pública o privada']::text[], 3, 'El artículo 64.3 dispone que «los nombramientos habrán de efectuarse entre personas con cualificación y experiencia en el desempeño de puestos de responsabilidad en la gestión pública o privada».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
