insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-013', (select id from leyes where slug = 'ley-40-2015'), '63.1.m', '¿Qué órgano del Ministerio convoca y resuelve las pruebas selectivas de personal funcionario y laboral?', array['El Subsecretario', 'El Ministro', 'El Secretario general técnico', 'El Director general competente']::text[], 0, 'Entre las competencias de los Subsecretarios, el artículo 63.1.m) recoge «convocar y resolver pruebas selectivas de personal funcionario y laboral».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
