insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-018', (select id from leyes where slug = 'ley-40-2015'), '70', 'Los Directores Insulares de la Administración General del Estado ejercen en su ámbito territorial las competencias atribuidas por la Ley 40/2015 a:', array['Los Delegados del Gobierno en las Comunidades Autónomas', 'Los Secretarios Generales de las Delegaciones', 'Los servicios territoriales no integrados', 'Los Subdelegados del Gobierno en las provincias']::text[], 3, 'Según el artículo 70, los Directores Insulares «ejercen, en su ámbito territorial, las competencias atribuidas por esta Ley a los Subdelegados del Gobierno en las provincias».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
