insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-019', (select id from leyes where slug = 'ley-40-2015'), '72.5', 'En una Comunidad Autónoma uniprovincial sin Subdelegado, la suplencia del Delegado del Gobierno por ausencia, vacante o enfermedad corresponde:', array['Al Director Insular de mayor antigüedad', 'Al Secretario General', 'Al titular del servicio integrado de mayor rango', 'A quien designe el Consejo de Ministros']::text[], 1, 'El artículo 72.5 dispone que «en las Comunidades Autónomas uniprovinciales en las que no exista Subdelegado la suplencia corresponderá al Secretario General».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
