insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-017', (select id from leyes where slug = 'ley-39-2015'), '53.1.e', 'Los interesados pueden formular alegaciones y aportar documentos:', array['Solo en los diez primeros días del procedimiento', 'Únicamente durante el trámite de audiencia', 'Hasta el momento en que se dicte la resolución', 'En cualquier fase anterior al trámite de audiencia']::text[], 3, 'El artículo 53.1.e) reconoce el derecho a formular alegaciones y «a aportar documentos en cualquier fase del procedimiento anterior al trámite de audiencia».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
