insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-018', (select id from leyes where slug = 'ley-39-2015'), '53.2.b', 'En un procedimiento sancionador, el presunto responsable tiene derecho:', array['A elegir al instructor del procedimiento', 'A que la sanción la confirme antes un juez', 'A la presunción de no existencia de responsabilidad', 'A que se archive si no se resuelve en un mes']::text[], 2, 'El artículo 53.2.b) reconoce el derecho «A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'at-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-019', (select id from leyes where slug = 'ley-39-2015'), '53.1.d', 'Los interesados tienen derecho a no presentar los documentos:', array['Que ya estén en poder de las Administraciones o los hayan elaborado ellas', 'Cuyo coste de obtención supere el importe de la tasa del procedimiento', 'Que tengan una antigüedad superior a cinco años desde su expedición', 'Que no estén redactados en castellano ni en otra lengua cooficial']::text[], 0, 'El artículo 53.1.d) reconoce el derecho a no presentar datos y documentos «que ya se encuentren en poder de las Administraciones Públicas o que hayan sido elaborados por éstas».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
