insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-021', (select id from leyes where slug = 'constitucion'), '87.3', '¿Cuántas firmas acreditadas exige como mínimo la iniciativa legislativa popular?', array['100.000', '500.000', '250.000', '1.000.000']::text[], 1, 'El artículo 87.3 exige para la iniciativa popular «no menos de 500.000 firmas acreditadas».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
