insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-002', (select id from leyes where slug = 'constitucion'), '11.2', 'Según la Constitución, ¿quién no podrá ser privado de su nacionalidad?', array['Ningún español residente en España', 'Ningún español mayor de edad', 'Ningún español de origen', 'Ningún español con doble nacionalidad']::text[], 2, 'El artículo 11.2 establece: «Ningún español de origen podrá ser privado de su nacionalidad.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
