insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-004', (select id from leyes where slug = 'constitucion'), '13.2', 'Por tratado o ley, atendiendo a la reciprocidad, puede reconocerse a los extranjeros el derecho de sufragio activo y pasivo en las elecciones:', array['Autonómicas', 'Generales', 'Al Parlamento Europeo', 'Municipales']::text[], 3, 'El artículo 13.2 reserva a los españoles los derechos del artículo 23, «salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
