insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-005', (select id from leyes where slug = 'constitucion'), '13.3', 'Según la Constitución, ¿qué delitos quedan excluidos de la extradición?', array['Los delitos de terrorismo', 'Los delitos castigados con pena de muerte', 'Los delitos políticos, sin considerar como tales los actos de terrorismo', 'Los delitos cometidos por españoles de origen']::text[], 2, 'El artículo 13.3 dispone: «Quedan excluidos de la extradición los delitos políticos, no considerándose como tales los actos de terrorismo.»', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
