insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-007', (select id from leyes where slug = 'constitucion'), '17.3', 'La Constitución garantiza la asistencia de abogado al detenido:', array['Solo en las diligencias judiciales', 'Solo si lo solicita en las primeras veinticuatro horas', 'Solo cuando la detención supere las setenta y dos horas', 'En las diligencias policiales y judiciales, en los términos que la ley establezca']::text[], 3, 'El artículo 17.3 dispone: «Se garantiza la asistencia de abogado al detenido en las diligencias policiales y judiciales, en los términos que la ley establezca.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
