insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-011', (select id from leyes where slug = 'constitucion'), '20.5', 'El secuestro de publicaciones, grabaciones y otros medios de información solo podrá acordarse:', array['Por la autoridad gubernativa', 'En virtud de resolución judicial', 'Por el Ministerio Fiscal', 'Con autorización de las Cortes Generales']::text[], 1, 'El artículo 20.5 dispone: «Sólo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información en virtud de resolución judicial.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
