insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-012', (select id from leyes where slug = 'constitucion'), '21.1', 'Según la Constitución, el ejercicio del derecho de reunión pacífica y sin armas:', array['Necesita autorización previa de la autoridad', 'Necesita comunicación previa en todo caso', 'Solo puede ejercerse en locales cerrados', 'No necesitará autorización previa']::text[], 3, 'El artículo 21.1 reconoce «el derecho de reunión pacífica y sin armas. El ejercicio de este derecho no necesitará autorización previa.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
