insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-013', (select id from leyes where slug = 'constitucion'), '22.3', 'Las asociaciones constituidas al amparo del artículo 22 deberán inscribirse en un registro:', array['A efectos constitutivos', 'Como requisito para adquirir personalidad jurídica', 'Para poder recibir ayudas públicas', 'A los solos efectos de publicidad']::text[], 3, 'El artículo 22.3 establece que esas asociaciones «deberán inscribirse en un registro a los solos efectos de publicidad».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
