insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-014', (select id from leyes where slug = 'constitucion'), '22.5', '¿Qué asociaciones prohíbe expresamente el artículo 22.5 de la Constitución?', array['Las secretas y las de carácter paramilitar', 'Las de carácter religioso o ideológico', 'Las que no estén inscritas en un registro', 'Las formadas por miembros de las Fuerzas Armadas']::text[], 0, 'El artículo 22.5 dispone: «Se prohíben las asociaciones secretas y las de carácter paramilitar.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
