insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-015', (select id from leyes where slug = 'constitucion'), '25.3', 'Según la Constitución, la Administración civil:', array['Solo puede imponer multas de cuantía fijada por ley orgánica', 'No podrá imponer sanciones que impliquen privación de libertad', 'Puede imponer arresto domiciliario como sanción subsidiaria', 'No podrá imponer sanciones sin informe del Ministerio Fiscal']::text[], 1, 'El artículo 25.3 establece: «La Administración civil no podrá imponer sanciones que, directa o subsidiariamente, impliquen privación de libertad.»', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
