insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-016', (select id from leyes where slug = 'constitucion'), '25.2', 'Las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia:', array['La retribución y la prevención general', 'La reparación del daño causado a la víctima', 'La reeducación y reinserción social', 'El trabajo obligatorio del condenado']::text[], 2, 'El artículo 25.2 dispone que «estarán orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
