insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-017', (select id from leyes where slug = 'constitucion'), '26', 'La Constitución prohíbe los Tribunales de Honor en el ámbito de:', array['La Administración civil y las organizaciones profesionales', 'Las Fuerzas Armadas y la Guardia Civil', 'La Administración militar y los partidos políticos', 'Los sindicatos y las asociaciones empresariales']::text[], 0, 'El artículo 26 dispone: «Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.»', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
