insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-018', (select id from leyes where slug = 'constitucion'), '27.4', 'Según la Constitución, la enseñanza básica es:', array['Gratuita, pero no obligatoria', 'Obligatoria y gratuita', 'Obligatoria hasta los dieciocho años', 'Obligatoria y gratuita solo en centros públicos']::text[], 1, 'El artículo 27.4 establece: «La enseñanza básica es obligatoria y gratuita.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
