insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-019', (select id from leyes where slug = 'constitucion'), '28.1', 'Respecto al derecho de sindicación, la ley podrá limitarlo o exceptuarlo para:', array['Los funcionarios públicos y el personal laboral de las Administraciones', 'Los jueces, magistrados y fiscales mientras se hallen en activo', 'El personal directivo y de alta dirección de las empresas públicas', 'Las Fuerzas o Institutos armados y los Cuerpos sometidos a disciplina militar']::text[], 3, 'El artículo 28.1 dispone: «La ley podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos.»', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
