insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-020', (select id from leyes where slug = 'constitucion'), '29.2', 'Los miembros de las Fuerzas o Institutos armados pueden ejercer el derecho de petición:', array['Solo de forma colectiva', 'Solo individualmente y con arreglo a su legislación específica', 'De forma individual y colectiva, sin limitación', 'Solo a través de sus mandos']::text[], 1, 'El artículo 29.2 establece que «podrán ejercer este derecho sólo individualmente y con arreglo a lo dispuesto en su legislación específica».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
