insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-021', (select id from leyes where slug = 'constitucion'), '31.1', 'Según la Constitución, el sistema tributario justo, inspirado en la igualdad y la progresividad:', array['Tendrá un tipo máximo fijado por ley orgánica', 'Solo gravará la renta y el patrimonio', 'En ningún caso tendrá alcance confiscatorio', 'Se aplicará solo a quienes tengan capacidad contributiva suficiente']::text[], 2, 'El artículo 31.1 habla de «un sistema tributario justo inspirado en los principios de igualdad y progresividad que, en ningún caso, tendrá alcance confiscatorio».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
