insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-022', (select id from leyes where slug = 'constitucion'), '31.2', 'La programación y ejecución del gasto público responderán, según la Constitución, a los criterios de:', array['Eficacia y transparencia', 'Estabilidad presupuestaria y sostenibilidad', 'Legalidad y equidad', 'Eficiencia y economía']::text[], 3, 'El artículo 31.2 dispone que el gasto público realizará una asignación equitativa de los recursos públicos, «y su programación y ejecución responderán a los criterios de eficiencia y economía».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
