insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-025', (select id from leyes where slug = 'constitucion'), '41', 'Respecto al régimen público de Seguridad Social, la Constitución establece que la asistencia y prestaciones complementarias:', array['Serán obligatorias para todos los trabajadores', 'Serán libres', 'Las financiará el Estado', 'Solo podrán gestionarlas entidades públicas']::text[], 1, 'El artículo 41 termina así: «La asistencia y prestaciones complementarias serán libres.»', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
