insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-026', (select id from leyes where slug = 'constitucion'), '47', 'Según el artículo 47 de la Constitución, la comunidad participará en:', array['Las plusvalías que genere la acción urbanística de los entes públicos', 'La planificación del suelo de uso residencial', 'Los beneficios de la promoción de vivienda privada', 'La gestión de las viviendas de protección oficial']::text[], 0, 'El artículo 47 dispone: «La comunidad participará en las plusvalías que genere la acción urbanística de los entes públicos.»', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
