insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-001', (select id from leyes where slug = 'constitucion'), '134.1', 'Según la Constitución, ¿a quién corresponde la elaboración de los Presupuestos Generales del Estado?', array['Al Gobierno', 'Al Congreso de los Diputados', 'A las Cortes Generales', 'Al Tribunal de Cuentas']::text[], 0, 'El artículo 134.1 dice: «Corresponde al Gobierno la elaboración de los Presupuestos Generales del Estado y a las Cortes Generales, su examen, enmienda y aprobación».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
