insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-002', (select id from leyes where slug = 'constitucion'), '134.1', 'Respecto de los Presupuestos Generales del Estado, a las Cortes Generales les corresponde:', array['Su elaboración y aprobación', 'Su examen, enmienda y aprobación', 'Su elaboración, examen y enmienda', 'Su fiscalización y ejecución']::text[], 1, 'Según el artículo 134.1, corresponde al Gobierno la elaboración de los Presupuestos «y a las Cortes Generales, su examen, enmienda y aprobación».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
