insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-005', (select id from leyes where slug = 'constitucion'), '134.3', 'El Gobierno debe presentar los Presupuestos Generales del Estado antes de la expiración de los del año anterior con una antelación mínima de:', array['Dos meses', 'Tres meses', 'Seis meses', 'Un mes']::text[], 1, 'El artículo 134.3 obliga a presentarlos «al menos tres meses antes de la expiración de los del año anterior».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
