insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-006', (select id from leyes where slug = 'constitucion'), '134.3', '¿Ante qué órgano debe presentar el Gobierno los Presupuestos Generales del Estado?', array['Ante el Senado', 'Ante las Cortes Generales en sesión conjunta', 'Ante el Tribunal de Cuentas', 'Ante el Congreso de los Diputados']::text[], 3, 'El artículo 134.3 dice: «El Gobierno deberá presentar ante el Congreso de los Diputados los Presupuestos Generales del Estado […]».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
