insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-007', (select id from leyes where slug = 'constitucion'), '134.4', 'Si la Ley de Presupuestos no se aprueba antes del primer día del ejercicio económico correspondiente:', array['Se prorrogan automáticamente los del ejercicio anterior hasta aprobar los nuevos', 'El Gobierno aprueba unos presupuestos provisionales por decreto-ley', 'Se prorrogan los del ejercicio anterior durante un máximo de tres meses', 'Se disuelven las Cortes y se convocan elecciones generales']::text[], 0, 'El artículo 134.4 dispone que, en ese caso, «se considerarán automáticamente prorrogados los Presupuestos del ejercicio anterior hasta la aprobación de los nuevos».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
