insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-008', (select id from leyes where slug = 'constitucion'), '134.5', 'Aprobados los Presupuestos Generales del Estado, los proyectos de ley que impliquen aumento del gasto público del mismo ejercicio:', array['Solo pueden presentarse en el ejercicio siguiente', 'Requieren autorización previa del Congreso por mayoría absoluta', 'Puede presentarlos el Gobierno', 'Requieren informe previo del Tribunal de Cuentas']::text[], 2, 'El artículo 134.5 dice: «Aprobados los Presupuestos Generales del Estado, el Gobierno podrá presentar proyectos de ley que impliquen aumento del gasto público o disminución de los ingresos correspondientes al mismo ejercicio presupuestario».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
