insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-010', (select id from leyes where slug = 'constitucion'), '134.7', 'Respecto de los tributos, la Ley de Presupuestos:', array['No puede crearlos, pero sí modificarlos si una ley tributaria sustantiva lo prevé', 'Puede crearlos y modificarlos libremente cada ejercicio', 'Puede crearlos solo si así lo prevé una ley orgánica', 'No puede crearlos ni modificarlos en ningún caso']::text[], 0, 'El artículo 134.7 dice: «La Ley de Presupuestos no puede crear tributos. Podrá modificarlos cuando una ley tributaria sustantiva así lo prevea».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
