insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-015', (select id from leyes where slug = 'constitucion'), '135.3', 'El pago de los intereses y el capital de la deuda pública de las Administraciones:', array['Se atiende tras los gastos de personal', 'Requiere autorización anual del Congreso', 'Puede ser objeto de enmienda presupuestaria', 'Goza de prioridad absoluta']::text[], 3, 'El artículo 135.3 dice que esos créditos se entenderán siempre incluidos en el estado de gastos «y su pago gozará de prioridad absoluta».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
