insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-016', (select id from leyes where slug = 'constitucion'), '135.4', 'Los límites de déficit estructural y de deuda pública pueden superarse en los casos previstos, apreciados por:', array['La mayoría simple del Congreso de los Diputados', 'La mayoría absoluta de los miembros del Congreso', 'La mayoría absoluta del Senado', 'El Consejo de Ministros, a propuesta del Ministro competente']::text[], 1, 'El artículo 135.4 exige que esas situaciones sean «apreciadas por la mayoría absoluta de los miembros del Congreso de los Diputados».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
