insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-003', null, 'Teclas de función', '¿Qué hace la tecla F11 si se pulsa sola con datos en la hoja?', array['Crea un gráfico incrustado en la hoja activa', 'Crea un gráfico en una hoja de gráfico distinta', 'Inserta una hoja de cálculo nueva en el libro', 'Abre el editor de Visual Basic para Aplicaciones']::text[], 1, 'Según la página: «Solo F11: crea un gráfico a partir de los datos del rango actual en una hoja de gráfico distinta». El gráfico incrustado se crea con Alt+F1, que «crea un gráfico incrustado a partir de los datos del rango actual».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
