insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-008', null, 'Cambiar entre referencias relativas, absolutas y mixtas', 'De forma predeterminada, una referencia de celda en Excel es:', array['Una referencia absoluta', 'Una referencia mixta', 'Una referencia relativa', 'Una referencia externa']::text[], 2, 'La página señala: «De forma predeterminada, una referencia de celda es una referencia relativa, lo que significa que la referencia es relativa a la ubicación de la celda».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
