insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-009', null, 'Para una fórmula que se está copiando', 'Una fórmula con la referencia A$1 se copia dos celdas hacia abajo y dos hacia la derecha. ¿En qué se convierte la referencia?', array['A$1', 'C$1', 'C$3', 'A$3']::text[], 1, 'La tabla de la página indica que «A$1 (columna relativa y fila absoluta)» cambia a «C$1 (la referencia es mixta)»: se fija la fila y la columna se ajusta.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
