insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-010', null, 'Cambiar entre referencias relativas, absolutas y mixtas', '¿Cuál de las siguientes es una referencia de celda mixta?', array['$B$4', 'B4', 'B4:C4', '$B4']::text[], 3, 'Una referencia mixta se obtiene al «mezclar referencias de celda absolutas y relativas precediendo el valor de la columna o la fila con un signo de dólar ($)». $B$4 es absoluta y B4 es relativa.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
