insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-011', null, 'Sintaxis', 'En la función SI, ¿qué argumento es opcional?', array['prueba_lógica', 'valor_si_verdadero', 'valor_si_falso', 'criterios']::text[], 2, 'La sintaxis es «SI(prueba_lógica; valor_si_verdadero; [valor_si_falso])» y la tabla de argumentos indica «valor_si_falso (opcional)».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
