insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-012', null, 'Ejemplos sencillos de SI', 'Si se usa texto dentro de una fórmula con la función SI, ese texto debe escribirse:', array['Entre comillas', 'Entre paréntesis', 'Precedido de un apóstrofo', 'Entre corchetes']::text[], 0, 'La nota de la página dice: «Si va a usar texto en fórmulas, tendrá que escribir el texto entre comillas». La única excepción son VERDADERO o FALSO.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
