insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-013', null, 'Sintaxis', 'En BUSCARX, si no hay coincidencia válida y no se ha indicado el argumento si_no_se_encuentra, la función devuelve:', array['#¡VALOR!', '#¿NOMBRE?', '#¡REF!', '#N/A']::text[], 3, 'La página indica: «Si no se encuentra una coincidencia válida y no hay [if_not_found], se devuelve #N/A».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
