insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-015', null, 'Ejemplos', 'Según Microsoft, ¿qué diferencia hay entre BUSCARV y BUSCARX?', array['BUSCARV solo puede buscar de izquierda a derecha', 'BUSCARV no permite la coincidencia exacta', 'BUSCARX usa una tabla única y un índice de columna', 'BUSCARX solo está disponible en Excel 2016']::text[], 0, 'La página señala que «BUSCARV solo puede buscar de izquierda a derecha» y que «BUSCARV usa una matriz de tabla única seguida de un número de índice de columna».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
