insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-016', null, 'Sintaxis', 'Para contar celdas que cumplen varios criterios a la vez, Microsoft indica que se use:', array['SUMAR.SI.CONJUNTO', 'PROMEDIO.SI.CONJUNTO', 'CONTAR.SI.CONJUNTO', 'SI.CONJUNTO']::text[], 2, 'Sobre el argumento criterios, la página dice: «CONTAR.SI usa solo un criterio. Use CONTAR.SI.CONJUNTO si desea usar varios criterios».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
