insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-019', null, 'Inmovilizar paneles para bloquear filas y columnas', '¿En qué pestaña de la cinta se encuentra Inmovilizar paneles?', array['Diseño de página', 'Vista', 'Datos', 'Inicio']::text[], 1, 'Para mantener visible un área de la hoja, la página indica: «vaya a la pestaña Vista», donde puede inmovilizar paneles o dividir paneles.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
