insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-021', null, 'Crear un gráfico', 'Tras seleccionar los datos, ¿qué ruta permite elegir entre los gráficos que Excel recomienda?', array['Datos > Gráficos recomendados', 'Inicio > Gráficos recomendados', 'Insertar > Gráficos recomendados', 'Vista > Gráficos recomendados']::text[], 2, 'Los pasos de la página son: «Seleccione datos para el gráfico» y «Seleccione Insertar > gráficos recomendados».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
