insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-022', null, 'Gráficos circulares', 'Según Microsoft, conviene usar un gráfico circular cuando:', array['Solo haya una serie de datos', 'Haya varias series de datos', 'Las etiquetas de eje sean largas', 'Los valores mostrados sean duraciones']::text[], 0, 'La página recomienda el gráfico circular cuando «Solo haya una serie de datos». Las etiquetas largas y las duraciones son casos para el gráfico de barras: «Las etiquetas de eje son largas».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
