insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-023', null, 'Gráficos de anillos', '¿Qué tipo de gráfico muestra la relación de las partes con un todo y puede contener más de una serie de datos?', array['Gráfico circular', 'Gráfico de dispersión', 'Gráfico de cotizaciones', 'Gráfico de anillos']::text[], 3, 'La página indica: «Al igual que un gráfico circular, un gráfico de anillos muestra la relación de las partes con un todo, pero puede contener más de una serie de datos».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
