insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-024', null, 'Ordenar texto', '¿Dónde están los botones Ordenar de la A a la Z y Ordenar de la Z a la A?', array['Ficha Inicio, grupo Estilos', 'Ficha Datos, grupo Ordenar y filtrar', 'Ficha Insertar, grupo Tablas', 'Ficha Vista, grupo Ventana']::text[], 1, 'Para ordenar texto, la página indica: «En la ficha Datos», «en el grupo Ordenar y filtrar», seleccione Ordenar de la A a la Z o de la Z a la A.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
