insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-025', null, 'Ordenar por una lista personalizada', 'Una lista personalizada para ordenar NO puede crearse a partir de:', array['Valores de texto', 'Valores numéricos', 'Un formato, como el color de celda', 'Valores de fecha u hora']::text[], 2, 'La página indica: «Una lista personalizada solo puede crearse basada en un valor (texto, número y fecha u hora). No puede crear una lista personalizada basada en un formato (color de celda, color de fuente o icono)».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
