insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-026', null, 'Ordenar de izquierda a derecha', 'Para ordenar de izquierda a derecha los datos de una tabla de Excel, primero hay que:', array['Convertir la tabla en un rango', 'Quitar los encabezados de columna', 'Activar Distinguir mayúsculas', 'Crear una lista personalizada']::text[], 0, 'La página advierte: «Las tablas no admiten la ordenación de izquierda a derecha. Para ello, primero debe convertir la tabla en un rango».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
