insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-027', null, 'Más información sobre el filtrado', 'Si se filtran datos por más de una columna, los filtros:', array['Se sustituyen y solo queda el último', 'Solo afectan a la primera columna', 'Obligan a convertir el rango en tabla', 'Son aditivos y reducen aún más los datos']::text[], 3, 'Según la página: «Los filtros son aditivos, lo que significa que cada filtro adicional se basa en el filtro actual y reduce aún más el subconjunto de datos».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
