insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-028', null, 'Formato avanzado', '¿Dónde se encuentra el comando Formato condicional?', array['Pestaña Datos, grupo Ordenar y filtrar', 'Pestaña Inicio, grupo Estilos', 'Pestaña Insertar, grupo Gráficos', 'Pestaña Vista, grupo Ventana']::text[], 1, 'La página indica: «En la pestaña Inicio», «en el grupo Estilos», «haga clic en la flecha situada junto a Formato condicional».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
