insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-029', null, 'Editar el orden en el que se evalúan las reglas de formato condicional', 'Si dos reglas de formato condicional entran en conflicto, ¿cuál se aplica?', array['La que está en la parte inferior de la lista', 'La que se creó más recientemente', 'La que afecta a más celdas del rango', 'La que está en la parte superior de la lista']::text[], 3, 'La página explica que, cuando hay conflictos entre dos reglas, «la regla que está en la parte superior de la lista se aplica y la regla que está por debajo de la lista no».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
