insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-030', null, 'Aplicar formato a las celdas usando barras de datos', 'En el formato condicional con barras de datos, una barra más larga representa:', array['Un valor más alto', 'Un valor más bajo', 'Un valor duplicado', 'Un valor con error']::text[], 0, 'La página indica: «La longitud de la barra de datos representa el valor de la celda. Una barra más larga representa un valor más alto».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
