insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-002', null, 'Métodos abreviados de teclado del Explorador de archivos', 'En el Explorador de archivos, ¿qué tecla permite cambiar el nombre del elemento seleccionado?', array['F2', 'F3', 'F4', 'F5']::text[], 0, 'F2 sirve para «Cambiar el nombre del elemento seleccionado.» F3 sirve para «Buscar un archivo o carpeta.» y F5 para actualizar la ventana.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
