insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-003', null, 'Métodos abreviados de teclado del Explorador de archivos', 'En el Explorador de archivos, ¿qué combinación crea una carpeta nueva?', array['Ctrl+U', 'Ctrl+T', 'Ctrl+Mayús+N', 'Ctrl+Mayús+E']::text[], 2, 'Ctrl+Mayús+N: «Cree una carpeta nueva.» Ctrl+U sirve para «Abrir una nueva ventana.» y Ctrl+T para «Abrir una pestaña nueva y cambiar a ella.»', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
