insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-004', null, 'Métodos abreviados de teclado del Explorador de archivos', 'En el Explorador de archivos, ¿qué hace la combinación Alt+Flecha arriba?', array['Vuelve a la carpeta anterior', 'Muestra la carpeta siguiente', 'Selecciona la barra de direcciones', 'Sube un nivel en la ruta de la carpeta']::text[], 3, 'Alt+Flecha arriba permite «Subir un nivel en la ruta de acceso de la carpeta.» Volver a la carpeta anterior corresponde a Alt+Flecha izquierda y seleccionar la barra de direcciones, a Alt+D.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
