insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-005', null, 'Métodos abreviados de teclado del Explorador de archivos', '¿Qué combinación elimina el elemento seleccionado sin moverlo a la Papelera de reciclaje?', array['Suprimir', 'Ctrl+D', 'Mayús+Supr', 'Ctrl+W']::text[], 2, 'Mayús+Supr sirve para «Eliminar permanentemente el elemento seleccionado sin moverlo a la papelera de reciclaje.» En cambio, Ctrl+D o Suprimir lo mueven a la papelera.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
