insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-006', null, 'Cómo usar el Explorador de archivos', '¿Cómo se ancla una carpeta a Acceso rápido en el Explorador de archivos?', array['Clic derecho en la carpeta y Anclar a acceso rápido', 'Seleccionar la carpeta y Compartir en la cinta', 'Ver > Mostrar > Panel de navegación', 'Clic derecho y Mostrar más opciones > Enviar a']::text[], 0, 'La página indica: «Para anclar una carpeta a Acceso rápido , haga clic con el botón derecho (o manténgalo presionado) en la carpeta y seleccione Anclar a acceso rápido».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
