insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-007', null, 'Cómo usar el Explorador de archivos', 'Para mover un archivo a otra ubicación usando la cinta de opciones, ¿qué comandos se usan?', array['Copiar y, en la nueva ubicación, Pegar', 'Cortar y, en la nueva ubicación, Pegar', 'Compartir y, en la nueva ubicación, Pegar', 'Cambiar nombre y escribir la nueva ruta']::text[], 1, 'Para mover un archivo o carpeta, «selecciónelo y, a continuación, seleccione Cortar en la cinta de opciones. Ve a la nueva ubicación y selecciona Pegar».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
