insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-009', null, 'Acceso rápido', 'A partir de Windows 11, versión 22H2, ¿dónde dejan de mostrarse las carpetas conocidas como Escritorio o Documentos?', array['En Acceso rápido', 'En el panel de navegación', 'En Este equipo', 'En Inicio del Explorador']::text[], 2, 'Esas carpetas se anclan en Acceso rápido y en el panel de navegación, y «Estas carpetas predeterminadas ya no se muestran en Este equipo para mantener la vista centrada en las unidades y las ubicaciones de red del equipo».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
