insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-010', null, 'Configure el Explorador de archivos para abrirlo en Este equipo', 'En Windows 11, versión 22H2, ¿qué nombre recibe Acceso rápido como página en la que se abre el Explorador?', array['Inicio', 'Este equipo', 'Galería', 'Bibliotecas']::text[], 0, 'La página indica que el Explorador «se abre en Acceso rápido, cuyo nombre se ha cambiado a Inicio del Explorador de archivos en Windows 11, versión 22H2».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
