insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-011', null, 'Menú contextual', 'En el menú contextual simplificado de Windows 11, ¿dónde aparecen Cortar, Copiar, Pegar, Cambiar nombre, Compartir y Eliminar?', array['Solo dentro de Mostrar más opciones', 'En la barra de estado de la ventana', 'En el panel de detalles del archivo', 'En la parte superior del menú contextual']::text[], 3, 'La página indica: «Puede encontrar Cortar , Copiar , Pegar, Cambiar nombre , Compartir y Eliminar en la parte superior del menú contextual».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
