insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-012', null, 'Buscar comandos en el menú contextual anterior de Windows 10', 'En Windows 11, ¿qué opción del menú contextual muestra los comandos del menú anterior de Windows 10?', array['Propiedades', 'Mostrar más opciones', 'Abrir con', 'Anclar a acceso rápido']::text[], 1, 'Tras hacer clic con el botón derecho en el archivo o carpeta: «Seleccione Mostrar más opciones». Las extensiones de Windows 10 «siempre estarán disponibles al seleccionar Mostrar más opciones».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
