insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-015', null, 'Encontrar tus archivos', 'Para hacer una búsqueda lenta pero exhaustiva desde el Explorador de archivos, ¿dónde conviene buscar?', array['En Inicio', 'En Este equipo', 'En la carpeta Descargas', 'En Acceso rápido']::text[], 1, 'La página indica: «Para realizar una búsqueda lenta pero exhaustiva, busque en Este equipo en lugar de en Inicio».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
