insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-016', null, 'Encontrar tus archivos', 'Al buscar un documento desde Buscar en la barra de tareas, ¿de dónde salen los resultados de archivos?', array['Solo de la carpeta Documentos', 'Solo de Acceso rápido', 'Solo de las unidades locales', 'Del PC y de OneDrive']::text[], 3, 'La página indica: «Los resultados de documentos y archivos se muestran desde tu PC y OneDrive».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
