insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-017', null, 'Para comprimir (comprimir)', 'En Windows 11, ¿qué ruta del menú contextual crea una carpeta comprimida (zip)?', array['Mostrar más opciones > Enviar a > Carpeta comprimida', 'Mostrar más opciones > Extraer todo...', 'Propiedades > General > Comprimir', 'Abrir con > Elegir otra aplicación']::text[], 0, 'Hay que hacer clic con el botón derecho en el archivo o carpeta y seleccionar «Mostrar más opciones > Enviar a > carpeta comprimida (en zip)».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
