insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-018', null, 'Para descomprimir (extraer)', 'Para descomprimir todo el contenido de una carpeta comprimida, ¿qué opción se elige en su menú contextual?', array['Enviar a', 'Cambiar nombre', 'Extraer todo...', 'Abrir con']::text[], 2, 'Para descomprimir todo el contenido, «haz clic con el botón derecho en la carpeta (o mantenla presionada), selecciona Extraer todo... y sigue las instrucciones».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
