insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-019', null, 'Para descomprimir (extraer)', '¿Qué ocurre si agregas archivos cifrados a una carpeta comprimida?', array['Seguirán cifrados al descomprimirlos', 'Estarán sin cifrar al descomprimirlos', 'Windows impide agregarlos a la carpeta', 'Se comprimen más que los no cifrados']::text[], 1, 'La página advierte: «Si agregas archivos cifrados a una carpeta comprimida, estarán sin cifrar cuando se descompriman». Por eso recomienda no comprimir archivos cifrados.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
