insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-020', null, 'Para descomprimir (extraer)', 'Si comprimes varias imágenes JPEG en una carpeta, ¿qué tamaño tendrá la carpeta comprimida?', array['Aproximadamente la mitad que las originales', 'Una décima parte de las imágenes originales', 'Mayor que la suma de las imágenes originales', 'Más o menos el mismo que las imágenes originales']::text[], 3, 'Las JPEG ya están comprimidas: «el tamaño total de la carpeta será aproximadamente el mismo que la colección original de imágenes».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
