insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-021', null, 'Preguntas frecuentes', '¿Qué formatos de archivo comprimido admite Windows 11, versión 24H2?', array['ZIP, RAR, 7z y TAR', 'Solo ZIP', 'ZIP y CAB, nada más', 'ZIP, RAR, 7z y TAR también cifrados']::text[], 0, 'La página indica: «Windows 11, versión 24H2 admite ZIP, RAR. Formatos de archivo 7z y TAR.» Pero «no admite operaciones en archivos de archivo cifrados».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
