insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-022', null, 'Extensiones de nombre de archivo comunes en Windows', '¿Qué ocurre si cambias la extensión del nombre de un archivo, por ejemplo de .docx a .pdf?', array['El archivo se convierte al nuevo formato', 'El archivo pasa a la Papelera de reciclaje', 'Solo cambia el nombre, no el formato', 'Windows comprime el archivo en un zip']::text[], 2, 'La página indica: «Puedes cambiar una extensión de nombre de archivo, pero eso no convertirá el archivo a otro formato ni cambiará nada más, excepto el nombre de archivo».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
