insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-023', null, 'El escritorio muestra iconos, pero falta la Papelera de reciclaje', 'Si el escritorio muestra iconos pero falta la Papelera de reciclaje, ¿dónde se vuelve a activar?', array['Clic derecho en el escritorio > Ver > Mostrar iconos', 'Explorador > Ver > Mostrar > Elementos ocultos', 'Explorador > Ver > Mostrar > Panel de navegación', 'Personalización > Temas > Configuración del icono de escritorio']::text[], 3, 'En Configuración hay que ir a Personalización > Temas, elegir «la configuración del icono de escritorio» y comprobar que «la casilla de la papelera de reciclaje está activada».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
