insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-024', null, 'Explorar el Explorador de archivos', '¿En qué vista del panel de contenido aparecen botones para ordenar por Nombre o por Fecha de modificación?', array['Iconos grandes', 'Detalles', 'Contenido', 'Iconos pequeños']::text[], 1, 'La página indica: «Si el panel Contenido está en el modo de vista Detalles , los botones de ordenación permiten ordenar por criterios como Nombre o Fecha de modificación».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
