insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('exp-025', null, 'Explorar el Explorador de archivos', '¿Qué zona del Explorador de archivos, abajo a la derecha, tiene botones para cambiar la vista y el diseño?', array['La barra de estado', 'El panel de detalles', 'El panel de navegación', 'La barra de direcciones']::text[], 0, 'La página indica: «Barra de estado : esta área se encuentra en la parte inferior derecha de la ventana y contiene botones para cambiar la vista y el diseño del Explorador de archivos».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
