insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-002', null, 'Declaración, párr. 1', 'Los Jefes de Estado y de Gobierno acordaron los Objetivos de Desarrollo Sostenible reunidos en:', array['Ginebra, del 25 al 27 de septiembre de 2015', 'Nueva York, del 25 al 27 de septiembre de 2015', 'Nueva York, del 1 al 3 de diciembre de 2015', 'París, del 25 al 27 de noviembre de 2015']::text[], 1, 'El párrafo 1 de la Declaración indica que se reunieron «en la Sede de las Naciones Unidas en Nueva York del 25 al 27 de septiembre de 2015».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
