insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-003', null, 'Declaración, párr. 4', '¿Qué promesa recoge la Agenda 2030 al emprender «este gran viaje»?', array['Que ningún país pagará deuda', 'Que todos crecerán por igual', 'Que nadie se quedará atrás', 'Que nadie perderá su empleo']::text[], 2, 'El párrafo 4 de la Declaración dice: «Al emprender juntos este gran viaje, prometemos que nadie se quedará atrás».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
