insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-004', null, 'Preámbulo', '¿Cuál de estas NO es una de las esferas de importancia crítica que señala el preámbulo de la Agenda 2030?', array['Las personas', 'La prosperidad', 'Las alianzas', 'La productividad']::text[], 3, 'El preámbulo presenta la Agenda como «un plan de acción en favor de las personas, el planeta y la prosperidad», que busca «fortalecer la paz universal», y dedica un apartado a «Las alianzas». La productividad no figura entre esas esferas.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
