insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-005', null, 'Preámbulo', 'Según la Agenda 2030, ¿cuáles son las tres dimensiones del desarrollo sostenible?', array['Económica, social y ambiental', 'Económica, política y social', 'Social, cultural y ambiental', 'Política, económica y territorial']::text[], 0, 'El preámbulo dice que los Objetivos y las metas «conjugan las tres dimensiones del desarrollo sostenible: económica, social y ambiental».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
