insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-006', null, 'Declaración, párr. 21', '¿Cuándo entraron en vigor los nuevos Objetivos y metas de la Agenda 2030?', array['El 25 de septiembre de 2015', 'El 1 de enero de 2016', 'El 1 de enero de 2015', 'El 21 de octubre de 2015']::text[], 1, 'El párrafo 21 dice: «Los nuevos Objetivos y metas entrarán en vigor el 1 de enero de 2016 y guiarán las decisiones que adoptemos durante los próximos 15 años».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
