insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-007', null, 'Preámbulo', 'Según la Agenda 2030, ¿cuál es el mayor desafío a que se enfrenta el mundo?', array['La lucha contra el cambio climático', 'La igualdad entre los géneros', 'La erradicación de la pobreza en todas sus formas', 'La paz universal y la seguridad']::text[], 2, 'El preámbulo afirma: «Reconocemos que la erradicación de la pobreza en todas sus formas y dimensiones, incluida la pobreza extrema, es el mayor desafío a que se enfrenta el mundo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
