insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-008', null, 'Objetivo 16', '¿Qué Objetivo de Desarrollo Sostenible incluye construir a todos los niveles instituciones eficaces e inclusivas que rindan cuentas?', array['El Objetivo 10', 'El Objetivo 17', 'El Objetivo 11', 'El Objetivo 16']::text[], 3, 'El Objetivo 16 es «Promover sociedades pacíficas e inclusivas para el desarrollo sostenible, facilitar el acceso a la justicia para todos y construir a todos los niveles instituciones eficaces e inclusivas que rindan cuentas».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
