insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-009', null, 'Objetivo 17', '¿Qué ODS consiste en fortalecer los medios de implementación y revitalizar la Alianza Mundial para el Desarrollo Sostenible?', array['El Objetivo 17', 'El Objetivo 1', 'El Objetivo 16', 'El Objetivo 12']::text[], 0, 'El último de la lista es el «Objetivo 17. Fortalecer los medios de implementación y revitalizar la Alianza Mundial para el Desarrollo Sostenible».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
