insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-010', null, 'Objetivo 5', '¿Qué persigue el Objetivo de Desarrollo Sostenible 5?', array['Una educación inclusiva y de calidad para todos', 'La igualdad de género y empoderar a mujeres y niñas', 'Reducir la desigualdad entre los países', 'Una vida sana y el bienestar de todos']::text[], 1, 'El Objetivo 5 es «Lograr la igualdad de género y empoderar a todas las mujeres y las niñas».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
