insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-012', (select id from leyes where slug = 'ley-19-2013'), 'Preámbulo I', 'Según el preámbulo de la Ley 19/2013, ¿qué deben ser los ejes fundamentales de toda acción política?', array['La eficacia, la eficiencia y la economía del gasto', 'La participación, la colaboración y la integridad', 'La transparencia, el acceso a la información y el buen gobierno', 'La legalidad, la publicidad y la responsabilidad']::text[], 2, 'El preámbulo empieza así: «La transparencia, el acceso a la información pública y las normas de buen gobierno deben ser los ejes fundamentales de toda acción política».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
