insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-013', null, 'Declaración, párr. 87', 'El foro político de alto nivel bajo los auspicios de la Asamblea General se reunirá:', array['Cada año', 'Cada dos años', 'Cada cinco años', 'Cada cuatro años']::text[], 3, 'El párrafo 87 dice: «El foro político de alto nivel, que se reunirá cada cuatro años bajo los auspicios de la Asamblea General, proporcionará orientación política de alto nivel sobre la Agenda».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
