insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-014', null, 'Declaración, párr. 84', 'Los exámenes periódicos que realiza el foro político de alto nivel bajo los auspicios del Consejo Económico y Social serán:', array['Voluntarios, aunque se alentará presentar informes', 'Obligatorios para todos los Estados Miembros', 'Obligatorios solo para países desarrollados', 'Voluntarios y sin presentación de informes']::text[], 0, 'El párrafo 84 dice: «Los exámenes serán voluntarios, aunque se alentará la presentación de informes, e incluirán a los países desarrollados y en desarrollo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
