insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-015', null, 'Declaración, párr. 83', '¿Quién prepara el informe anual sobre los progresos de los ODS en que se basa el foro político de alto nivel?', array['La Comisión de Estadística', 'El Secretario General', 'El Consejo Económico y Social', 'El Presidente de la Asamblea General']::text[], 1, 'El párrafo 83 se refiere a «un informe anual sobre los progresos de los Objetivos de Desarrollo Sostenible que preparará el Secretario General en cooperación con el sistema de las Naciones Unidas».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
