insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-016', null, 'Preámbulo', 'Según su preámbulo, con los ODS se pretende retomar y conseguir lo que no lograron:', array['La Agenda de Acción de Addis Abeba', 'Los acuerdos de la Cumbre de Río', 'Los Objetivos de Desarrollo del Milenio', 'La Convención Marco sobre el Cambio Climático']::text[], 2, 'El preámbulo dice: «Con ellos se pretende retomar los Objetivos de Desarrollo del Milenio y conseguir lo que estos no lograron».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
