insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-019', null, 'Alianza para el Gobierno Abierto (OGP)', '¿Desde qué año forma parte España de la Alianza para el Gobierno Abierto (OGP)?', array['Desde 2013', 'Desde 2011', 'Desde 2015', 'Desde 2012']::text[], 1, 'La OGP fue «fundada en septiembre de 2011» y «España se unió a la OGP en el mismo año de su fundación».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
