insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-020', null, 'Alianza para el Gobierno Abierto (OGP)', '¿Quién evalúa el cumplimiento de los compromisos de los planes de acción de la Alianza para el Gobierno Abierto?', array['El Comité Directivo de la Alianza', 'El Foro de Gobierno Abierto', 'El Mecanismo de Revisión Independiente', 'El Comité de Gobernanza Pública']::text[], 2, 'Según la página, «La evaluación del cumplimento de estos compromisos la realiza el Mecanismo de Revisión Independiente (MRI) de la Alianza».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
