insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-024', null, '¿Qué es?', '¿Cómo se reparte la representación en el Foro de Gobierno Abierto?', array['Con mayoría de las Administraciones públicas', 'Con mayoría de la sociedad civil', 'A partes iguales entre Administraciones y sociedad civil', 'Solo con la Administración General del Estado']::text[], 2, 'En el Foro «participan, con igual número de representantes, las Administraciones públicas y la sociedad civil».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
