insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-025', null, 'Aprobación del V Plan por el pleno del Foro de Gobierno Abierto', '¿Qué período abarca el V Plan de Gobierno Abierto de España?', array['2024-2028', '2025-2028', '2026-2030', '2025-2029']::text[], 3, 'Según la página, «El V Plan de Gobierno Abierto 2025-2029 fue aprobado en la reunión del pleno del Foro de 6 de octubre de 2025».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
