insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-017', (select id from leyes where slug = 'ley-50-1997'), '5.3', 'Según la Ley del Gobierno, las deliberaciones del Consejo de Ministros:', array['Son públicas', 'Se publican en el BOE', 'Son secretas', 'Son públicas salvo que el Presidente acuerde lo contrario']::text[], 2, 'El artículo 5.3 de la Ley 50/1997 dice: «Las deliberaciones del Consejo de Ministros serán secretas».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-018', (select id from leyes where slug = 'ley-50-1997'), '6.2', 'La creación, modificación y supresión de las Comisiones Delegadas del Gobierno se acuerda:', array['Por Real Decreto del Presidente del Gobierno, sin intervención del Consejo de Ministros', 'Por el Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno', 'Por ley de las Cortes Generales', 'Por orden del Ministro de la Presidencia']::text[], 1, 'El artículo 6.2 de la Ley 50/1997 dice que la creación, modificación y supresión de las Comisiones Delegadas «será acordada por el Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-019', (select id from leyes where slug = 'ley-50-1997'), '11', 'Para ser miembro del Gobierno, la Ley 50/1997 exige:', array['Ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo y no estar inhabilitado', 'Ser español de origen, mayor de veinticinco años y tener la condición de diputado', 'Ser español, mayor de edad y funcionario de carrera de cualquier Administración', 'Ser mayor de edad, residir en España y tener reconocida experiencia profesional']::text[], 0, 'El artículo 11 de la Ley 50/1997 exige «ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo», así como no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme.', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-020', (select id from leyes where slug = 'ley-50-1997'), '13.1', 'En caso de vacante, ausencia o enfermedad, las funciones del Presidente del Gobierno las asumen:', array['El Ministro de la Presidencia, en todo caso y sin orden de prelación', 'El Presidente del Congreso de los Diputados, hasta que se nombre nuevo Presidente', 'El Ministro de mayor edad y, en su defecto, el de mayor antigüedad en el cargo', 'Los Vicepresidentes por su orden y, en su defecto, los Ministros según el orden de precedencia de los Departamentos']::text[], 3, 'El artículo 13.1 de la Ley 50/1997 dice que las funciones del Presidente «serán asumidas por los Vicepresidentes, de acuerdo con el correspondiente orden de prelación, y, en defecto de ellos, por los Ministros, según el orden de precedencia de los Departamentos».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-021', (select id from leyes where slug = 'ley-50-1997'), '21.3', 'El Gobierno en funciones:', array['Puede ejercer todas sus competencias sin limitación', 'Solo puede adoptar medidas en estado de alarma', 'Limita su gestión al despacho ordinario de los asuntos públicos', 'Pierde todas sus competencias hasta la toma de posesión del nuevo Gobierno']::text[], 2, 'El artículo 21.3 de la Ley 50/1997 dice: que el Gobierno en funciones «limitará su gestión al despacho ordinario de los asuntos públicos», salvo casos de urgencia o interés general acreditados.', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-022', (select id from leyes where slug = 'ley-50-1997'), '21.4', '¿Cuál de las siguientes facultades NO puede ejercer el Presidente del Gobierno en funciones?', array['Despachar los asuntos ordinarios que correspondan a la Presidencia del Gobierno', 'Proponer al Rey la disolución de alguna de las Cámaras o de las Cortes Generales', 'Adoptar medidas urgentes debidamente acreditadas por razones de interés general', 'Asistir a reuniones internacionales en representación del Gobierno de España']::text[], 1, 'El artículo 21.4 de la Ley 50/1997 prohíbe al Presidente en funciones, entre otras cosas, «Proponer al Rey la disolución de alguna de las Cámaras, o de las Cortes Generales».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-022', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-023', (select id from leyes where slug = 'ley-50-1997'), '24.1', 'Las decisiones que aprueben normas reglamentarias de la competencia del Consejo de Ministros adoptan la forma de:', array['Reales Decretos acordados en Consejo de Ministros', 'Reales Decretos del Presidente del Gobierno', 'Órdenes ministeriales', 'Acuerdos del Consejo de Ministros']::text[], 0, 'El artículo 24.1 de la Ley 50/1997 dice que adoptarán la forma de «Reales Decretos acordados en Consejo de Ministros» las decisiones que aprueben normas reglamentarias de su competencia.', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
