insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-001', (select id from leyes where slug = 'ley-50-1997'), '7.1', 'Según la Ley del Gobierno, los Secretarios de Estado son:', array['Miembros del Gobierno sin cartera', 'Órganos superiores de la Administración General del Estado', 'Órganos directivos de los Departamentos ministeriales', 'Órganos de apoyo político y técnico de los Ministros']::text[], 1, 'El artículo 7.1 dice que «Los Secretarios de Estado son órganos superiores de la Administración General del Estado, directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
