insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-002', (select id from leyes where slug = 'ley-50-1997'), '7.2', 'Los Secretarios de Estado adscritos a la Presidencia del Gobierno actúan bajo la dirección:', array['Del Vicepresidente primero del Gobierno', 'Del Consejo de Ministros', 'De la Comisión General de Secretarios de Estado y Subsecretarios', 'Del Presidente del Gobierno']::text[], 3, 'Según el artículo 7.2, «Cuando estén adscritos a la Presidencia del Gobierno, actúan bajo la dirección del Presidente».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
