insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-004', (select id from leyes where slug = 'ley-50-1997'), '6.4.c', 'Corresponde a las Comisiones Delegadas resolver los asuntos que, afectando a más de un Ministerio:', array['Hayan sido avocados por el Presidente del Gobierno', 'Requieran una propuesta conjunta previa', 'No requieran ser elevados al Consejo de Ministros', 'Hayan sido examinados por el Secretariado del Gobierno']::text[], 2, 'El artículo 6.4.c) atribuye a las Comisiones Delegadas «Resolver los asuntos que, afectando a más de un Ministerio, no requieran ser elevados al Consejo de Ministros».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-005', (select id from leyes where slug = 'ley-50-1997'), '8.4', 'Según la Ley del Gobierno, las deliberaciones de la Comisión General de Secretarios de Estado y Subsecretarios son:', array['Secretas', 'Públicas', 'Reservadas', 'Confidenciales salvo acuerdo en contrario']::text[], 2, 'El artículo 8.4 dispone que «Las deliberaciones de la Comisión General de Secretarios de Estado y Subsecretarios serán reservadas». Son las del Consejo de Ministros y las Comisiones Delegadas las que la ley califica de secretas.', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
