insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-010', (select id from leyes where slug = 'ley-50-1997'), '9.1.f', 'Velar por la correcta y fiel publicación en el «Boletín Oficial del Estado» de las disposiciones del Gobierno corresponde:', array['A la Comisión General de Secretarios de Estado y Subsecretarios', 'A las Comisiones Delegadas del Gobierno', 'Al Secretariado del Gobierno', 'Al Gabinete de la Presidencia del Gobierno']::text[], 2, 'Entre las funciones del Secretariado del Gobierno, el artículo 9.1.f) incluye «Velar por la correcta y fiel publicación de las disposiciones y normas emanadas del Gobierno que deban insertarse en el "Boletín Oficial del Estado"».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-011', (select id from leyes where slug = 'ley-50-1997'), '10.1', 'Según la Ley del Gobierno, los miembros de los Gabinetes:', array['Pueden dictar resoluciones por delegación del Ministro', 'Son órganos superiores de la Administración', 'Sustituyen al Ministro en caso de ausencia', 'Realizan tareas de confianza y asesoramiento especial']::text[], 3, 'El artículo 10.1 dice que «Los miembros de los Gabinetes realizan tareas de confianza y asesoramiento especial sin que en ningún caso puedan adoptar actos o resoluciones que correspondan legalmente a los órganos de la Administración General del Estado».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-012', (select id from leyes where slug = 'ley-50-1997'), '16.2', 'Los Directores de Gabinete de los Secretarios de Estado son nombrados:', array['Por Real Decreto aprobado en Consejo de Ministros', 'Por Orden Ministerial, previo conocimiento del Consejo de Ministros', 'Por Real Decreto del Presidente del Gobierno', 'Por resolución del propio Secretario de Estado']::text[], 1, 'El artículo 16.2 establece que «Los Directores de Gabinete de los Secretarios de Estado serán nombrados por Orden Ministerial, previo conocimiento del Consejo de Ministros».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-013', (select id from leyes where slug = 'ley-50-1997'), '16.3', 'Cuando cesa el titular del cargo del que dependen, los Directores de los Gabinetes:', array['Continúan tres meses en funciones', 'Cesan automáticamente', 'Pasan a depender del Subsecretario', 'Siguen en el cargo hasta que el sucesor los cese']::text[], 1, 'Según el artículo 16.3, «Los Directores de los Gabinetes cesarán automáticamente cuando cese el titular del cargo del que dependen». Si el Gobierno está en funciones, siguen hasta que se forma el nuevo.', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
