insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-014', (select id from leyes where slug = 'ley-50-1997'), '12.2 bis', 'En el nombramiento de Vicepresidencias y Ministerios, cada sexo debe suponer en su conjunto como mínimo:', array['El cuarenta por ciento', 'El cincuenta por ciento', 'El treinta por ciento', 'El treinta y tres por ciento']::text[], 0, 'El artículo 12.2 bis exige la presencia equilibrada «de forma que cada uno de los sexos suponga como mínimo el cuarenta por ciento en su conjunto».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-015', (select id from leyes where slug = 'ley-50-1997'), '12.2', 'Según la Ley del Gobierno, la separación de los Ministros sin cartera:', array['Obliga a nombrar otro Ministro sin cartera', 'Requiere acuerdo del Consejo de Ministros', 'Lleva aparejada la extinción de dichos órganos', 'Debe comunicarse al Congreso de los Diputados']::text[], 2, 'El artículo 12.2 dispone que «La separación de los Ministros sin cartera llevará aparejada la extinción de dichos órganos».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-016', (select id from leyes where slug = 'ley-50-1997'), '13.2', 'La suplencia de los Ministros para el despacho ordinario de los asuntos de su competencia se determina:', array['Por acuerdo del Consejo de Ministros', 'Por Orden del propio Ministro', 'Por Real Decreto acordado en Consejo de Ministros', 'Por Real Decreto del Presidente del Gobierno']::text[], 3, 'El artículo 13.2 dice que esta suplencia «será determinada por Real Decreto del Presidente del Gobierno, debiendo recaer, en todo caso, en otro miembro del Gobierno».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-017', (select id from leyes where slug = 'ley-50-1997'), '18.4', '¿Qué de lo siguiente NO figura en el acta de las sesiones del Consejo de Ministros?', array['Las opiniones expresadas por cada Ministro', 'La relación de asistentes', 'Los informes presentados', 'El tiempo y lugar de su celebración']::text[], 0, 'Según el artículo 18.4, en el acta figurarán «exclusivamente, las circunstancias relativas al tiempo y lugar de su celebración, la relación de asistentes, los acuerdos adoptados y los informes presentados».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-018', (select id from leyes where slug = 'ley-50-1997'), '20.3.a', 'Según la Ley del Gobierno, ¿cuál de estas competencias NO es delegable en ningún caso?', array['Las funciones administrativas del Consejo de Ministros en las Comisiones Delegadas', 'Las competencias propias de un Ministro en favor de sus Secretarios de Estado', 'Las atribuidas directamente por la Constitución', 'Las competencias propias del Presidente en favor de los Vicepresidentes']::text[], 2, 'El artículo 20.3 dice que «No son en ningún caso delegables» las competencias, entre otras, «atribuidas directamente por la Constitución». Las demás opciones son delegaciones previstas en los apartados 1 y 2.', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-019', (select id from leyes where slug = 'ley-50-1997'), '21.5', '¿Cuál de estas facultades NO puede ejercer el Gobierno en funciones?', array['El despacho ordinario de los asuntos públicos', 'Presentar proyectos de ley al Congreso de los Diputados', 'Facilitar el traspaso de poderes al nuevo Gobierno', 'Adoptar medidas en casos de urgencia debidamente acreditados']::text[], 1, 'El artículo 21.5 dispone que «El Gobierno en funciones no podrá ejercer las siguientes facultades» y cita, junto al proyecto de Presupuestos, «Presentar proyectos de ley al Congreso de los Diputados o, en su caso, al Senado».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-020', (select id from leyes where slug = 'ley-50-1997'), '21.6', '¿Qué ocurre con las delegaciones legislativas otorgadas por las Cortes cuando el Gobierno está en funciones tras unas elecciones generales?', array['Se extinguen de forma automática', 'Las ejerce el Gobierno solo en casos urgentes', 'Se prorrogan hasta la investidura', 'Quedan en suspenso durante todo ese tiempo']::text[], 3, 'El artículo 21.6 señala que «Las delegaciones legislativas otorgadas por las Cortes Generales quedarán en suspenso durante todo el tiempo que el Gobierno esté en funciones como consecuencia de la celebración de elecciones generales».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gb-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-021', (select id from leyes where slug = 'ley-50-1997'), '23', 'Los reglamentos del Gobierno que impongan nuevas obligaciones a quienes ejercen una actividad económica o profesional entran en vigor:', array['El 2 de enero o el 1 de julio siguientes a su aprobación', 'A los veinte días de su publicación en el BOE', 'El 1 de enero o el 1 de julio siguientes a su publicación', 'Al día siguiente de su publicación en el BOE']::text[], 0, 'El artículo 23 indica que esas disposiciones «preverán el comienzo de su vigencia el 2 de enero o el 1 de julio siguientes a su aprobación».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
