insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-022', (select id from leyes where slug = 'ley-50-1997'), '29.2', 'Según la Ley del Gobierno, todos los actos y omisiones del Gobierno están sometidos al control político:', array['Del Congreso de los Diputados', 'Del Tribunal Constitucional', 'De las Cortes Generales', 'Del Consejo de Estado']::text[], 2, 'El artículo 29.2 dice que «Todos los actos y omisiones del Gobierno están sometidos al control político de las Cortes Generales».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
