insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-025', (select id from leyes where slug = 'constitucion'), '115.2', 'La propuesta de disolución de las Cámaras no puede presentarse cuando:', array['Esté en trámite una moción de censura', 'Esté en trámite una cuestión de confianza', 'El Gobierno lleve menos de un año', 'Esté en trámite la Ley de Presupuestos']::text[], 0, 'El artículo 115.2 dispone que «La propuesta de disolución no podrá presentarse cuando esté en trámite una moción de censura».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
