insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-002', (select id from leyes where slug = 'rd-208-1996'), '3.1', 'La información particular sobre el estado de los procedimientos en tramitación solo puede facilitarse a:', array['Los interesados en cada procedimiento o sus representantes legales', 'Cualquier ciudadano que la solicite', 'Los grupos sociales o instituciones interesados', 'Los empleados públicos de la unidad tramitadora']::text[], 0, 'Según el artículo 3.1, «Esta información sólo podrá ser facilitada a las personas que tengan la condición de interesados en cada procedimiento o a sus representantes legales».', 1, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
