insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-004', (select id from leyes where slug = 'rd-208-1996'), '3.3', 'Según el RD 208/1996, ¿quién aporta la información particular?', array['El Centro de Información Administrativa', 'Las oficinas de información y atención al ciudadano', 'Las unidades departamentales de información administrativa', 'Las unidades de gestión de la Administración General del Estado']::text[], 3, 'El artículo 3.3 establece: «Esta información será aportada por las unidades de gestión de la Administración General del Estado».', 2, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 18 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-005', (select id from leyes where slug = 'rd-208-1996'), '4.b', 'La función de orientación e información al ciudadano en ningún caso podrá entrañar:', array['Una interpretación normativa', 'Una simple determinación de conceptos', 'Información de opciones legales', 'Colaboración en la cumplimentación de impresos']::text[], 0, 'El artículo 4.b) indica que «en ningún caso podrá entrañar una interpretación normativa […] ni consideración jurídica o económica, sino una simple determinación de conceptos, información de opciones legales o colaboración en la cumplimentación de impresos o solicitudes».', 2, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
