insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-012', (select id from leyes where slug = 'rd-208-1996'), '8.a', 'Las oficinas centrales de información y atención al ciudadano radicarán, salvo circunstancias singulares:', array['En las Delegaciones del Gobierno', 'En cada capital de provincia', 'En la sede de cada Departamento ministerial', 'En el Centro de Información Administrativa']::text[], 2, 'El artículo 8.a) señala que las oficinas centrales «radicarán en la sede de cada Departamento ministerial, salvo que circunstancias singulares aconsejen otro emplazamiento».', 2, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
