insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-013', (select id from leyes where slug = 'rd-208-1996'), '10', '¿Mediante qué instrumento pueden varias Administraciones crear oficinas integradas de información?', array['Real decreto', 'Orden ministerial', 'Acuerdo del Consejo de Ministros', 'Convenio de colaboración']::text[], 3, 'El artículo 10 prevé que «Mediante convenio de colaboración, suscrito por distintas Administraciones públicas» pueda acordarse «la creación de oficinas integradas de información con participación de varias Administraciones públicas».', 1, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
