insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-014', (select id from leyes where slug = 'rd-208-1996'), '6.2.b', 'El sistema de información al ciudadano que sostiene el Centro de Información Administrativa es eminentemente:', array['Presencial', 'Telefónico', 'Postal', 'Telemático']::text[], 1, 'El artículo 6.2.b) le encarga «Sostener un sistema de información administrativa al ciudadano, eminentemente telefónico».', 3, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
