insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-015', (select id from leyes where slug = 'rd-208-1996'), '1', 'Según el RD 208/1996, la información encomendada a las unidades y oficinas de información podrá ser:', array['Ordinaria o extraordinaria', 'Presencial o a distancia', 'Pública o reservada', 'General o particular']::text[], 3, 'El artículo 1 establece que esa información «podrá ser general o particular».', 1, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
