insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-016', (select id from leyes where slug = 'rd-951-2005'), '3.1', '¿Cuál de los siguientes es uno de los programas del marco general para la mejora de la calidad?', array['Programa de simplificación administrativa', 'Programa de atención presencial', 'Programa de transparencia activa', 'Programa de reconocimiento']::text[], 3, 'Entre los programas que enumera el artículo 3.1 figura el «e) Programa de reconocimiento».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
