insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-017', (select id from leyes where slug = 'rd-951-2005'), '4', 'Además de a la AGE y sus organismos autónomos, el RD 951/2005 se aplica a:', array['Las Administraciones de las comunidades autónomas', 'Las entidades que integran la Administración local', 'Las Entidades Gestoras y Servicios Comunes de la Seguridad Social', 'Las universidades públicas']::text[], 2, 'El artículo 4 dispone que se aplica «a la Administración General del Estado, a sus organismos autónomos y a las Entidades Gestoras y Servicios Comunes de la Seguridad Social».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
