insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-018', (select id from leyes where slug = 'rd-951-2005'), '8.1', 'Las cartas de servicios informan a los ciudadanos sobre los servicios encomendados, sus derechos y:', array['Los compromisos de calidad en su prestación', 'El régimen sancionador aplicable', 'Los recursos administrativos procedentes', 'Las tasas exigibles por cada servicio']::text[], 0, 'El artículo 8.1 dice que informan «sobre los servicios que tienen encomendados, sobre los derechos que les asisten en relación con aquellos y sobre los compromisos de calidad en su prestación».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
