insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-019', (select id from leyes where slug = 'rd-951-2005'), '10.4', 'Las cartas de servicios se actualizarán, en cualquier caso, al menos cada:', array['Año', 'Dos años', 'Tres años', 'Cinco años']::text[], 2, 'El artículo 10.4 establece: «Las cartas se actualizarán periódicamente en función de las circunstancias y, en cualquier caso, al menos cada tres años».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
