insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-020', (select id from leyes where slug = 'rd-951-2005'), '11.1', 'Las cartas de servicios y sus actualizaciones se aprueban mediante resolución:', array['Del Ministro del departamento', 'Del titular del órgano que la elabora', 'De la Inspección General de Servicios', 'Del Subsecretario del departamento']::text[], 3, 'Según el artículo 11.1, «serán aprobadas mediante resolución del Subsecretario del departamento al que pertenezca el órgano o esté vinculado o adscrito el organismo proponente».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
