insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-022', (select id from leyes where slug = 'rd-951-2005'), '9.c', 'Las reclamaciones por incumplimiento de los compromisos de una carta de servicios:', array['Dan lugar siempre a una compensación económica', 'En ningún caso dan lugar a responsabilidad patrimonial', 'Tienen la consideración de recurso de alzada', 'Las reconoce la Inspección General de Servicios']::text[], 1, 'El artículo 9.c) dice que su reconocimiento «corresponderá al titular del órgano u organismo al que se refiera la carta, y que en ningún caso darán lugar a responsabilidad patrimonial por parte de la Administración».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
