insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-024', (select id from leyes where slug = 'rd-951-2005'), '15.2', 'Las quejas y sugerencias presentadas por correo electrónico o a través de Internet:', array['Deben ratificarse después de forma presencial', 'No se admiten en ningún caso', 'Deben estar suscritas con la firma electrónica del interesado', 'Pueden presentarse de forma anónima']::text[], 2, 'El artículo 15.2 establece: «Las quejas y sugerencias presentadas por correo electrónico o a través de Internet deberán estar suscritas con la firma electrónica del interesado».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
