insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-026', (select id from leyes where slug = 'rd-951-2005'), '16.2', 'Si hay que pedir aclaraciones al autor de una queja, ¿de qué plazo dispone para formularlas?', array['10 días hábiles', '5 días hábiles', '15 días hábiles', '20 días hábiles']::text[], 0, 'Según el artículo 16.2, el plazo se podrá suspender si debe requerirse al interesado para que, «en un plazo de 10 días hábiles, formule las aclaraciones necesarias».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
