insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-028', (select id from leyes where slug = 'rd-951-2005'), '19', 'Las quejas formuladas conforme al RD 951/2005:', array['Interrumpen los plazos de los recursos', 'No tienen la calificación de recurso administrativo', 'Tienen la consideración de recurso de alzada', 'Suspenden la ejecución del acto']::text[], 1, 'El artículo 19 establece que las quejas «no tendrán, en ningún caso, la calificación de recurso administrativo ni su presentación interrumpirá los plazos establecidos en la normativa vigente».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
