insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-029', (select id from leyes where slug = 'rd-951-2005'), '17.3', '¿Cuándo remite la unidad de quejas y sugerencias su informe global anual a la Inspección General de Servicios?', array['En el mes de enero de cada año', 'En el primer trimestre de cada año', 'Dentro del primer semestre de cada año', 'En el mes de diciembre de cada año']::text[], 0, 'El artículo 17.3 indica que la unidad remitirá a la Inspección General de Servicios, «en el mes de enero de cada año, un informe global de las quejas y sugerencias recibidas en el año anterior».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
