insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-030', (select id from leyes where slug = 'rd-951-2005'), '20.1', 'La evaluación de la calidad de las organizaciones se articula en dos niveles:', array['Evaluación interna y auditoría', 'Autoevaluación y evaluación externa', 'Evaluación previa y evaluación final', 'Evaluación departamental e interministerial']::text[], 1, 'El artículo 20.1 dispone: «La evaluación se articulará en dos niveles: autoevaluación y evaluación externa».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
