insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-001', null, 'Requisitos mínimos del sistema para ejecutar Windows 11', '¿Cuánta memoria RAM exige como mínimo Windows 11?', array['2 GB', '4 GB', '8 GB', '16 GB']::text[], 1, 'Entre los requisitos mínimos, el de RAM es «4 GB». La página añade que «si el equipo tiene menos de 4 GB de memoria, a veces hay opciones para actualizar».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
