insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-002', null, 'Requisitos mínimos del sistema para ejecutar Windows 11', '¿Qué capacidad mínima de almacenamiento necesita un equipo para ejecutar Windows 11?', array['16 GB', '32 GB', '64 GB', '128 GB']::text[], 2, 'El requisito de almacenamiento es «64 GB o dispositivo de almacenamiento más grande».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
