insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-003', null, 'Requisitos mínimos del sistema para ejecutar Windows 11', '¿Qué procesador (CPU) pide como mínimo Windows 11?', array['1 GHz o más rápido, con 2 o más núcleos', '2 GHz o más rápido, con 4 o más núcleos', '1 GHz o más rápido, con un solo núcleo', '3 GHz o más rápido, con 2 o más núcleos']::text[], 0, 'El procesador debe ser de «1 GHz o más rápido con 2 o más núcleos y que aparece en nuestra lista de CPU aprobadas».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
