insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-004', null, 'Requisitos mínimos del sistema para ejecutar Windows 11', 'En los requisitos de firmware de Windows 11, ¿qué es UEFI?', array['Un módulo que cifra la memoria RAM', 'Un controlador de la tarjeta gráfica', 'Un tipo de unidad de almacenamiento', 'Una versión moderna del BIOS del equipo']::text[], 3, 'El firmware del sistema debe ser «UEFI (para Unified Extensible Firmware Interface, una versión moderna del BIOS del equipo) y compatible con el arranque seguro».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
