insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-005', null, 'Requisitos mínimos del sistema para ejecutar Windows 11', '¿Qué versión del Módulo de plataforma segura (TPM) exige Windows 11?', array['Versión 1.2', 'Versión 2.0', 'Versión 1.0', 'Versión 3.0']::text[], 1, 'El requisito de TPM es el «Módulo de plataforma segura (TPM) versión 2.0».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
