insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-006', null, 'Requisitos mínimos del sistema para ejecutar Windows 11', '¿Qué pantalla figura como requisito mínimo de Windows 11?', array['Alta definición (1080p), de más de 13" en diagonal', 'Alta definición (720p), de más de 7" en diagonal', 'Alta definición (720p), de más de 9" en diagonal', 'Alta definición (1080p), de más de 9" en diagonal']::text[], 2, 'Se pide una «pantalla de alta definición (720p) superior a 9" diagonalmente, 8 bits por canal de color».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
