insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-007', null, 'Resumen', '¿Para qué sirve el Sensor de almacenamiento de Windows?', array['Para comprimir las unidades y ganar capacidad', 'Para copiar las carpetas del usuario en OneDrive', 'Para cifrar el contenido de la unidad del sistema', 'Para liberar espacio quitando lo que no necesitas']::text[], 3, 'El Sensor de almacenamiento «puede liberar automáticamente espacio en el disco al deshacerse de los elementos que no necesitas, como archivos temporales y elementos en la Papelera de reciclaje».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
