insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-008', null, 'Resumen', '¿En qué unidades funciona el Sensor de almacenamiento?', array['Solo en la unidad del sistema, normalmente C:', 'En todas las unidades internas del equipo', 'Solo en las unidades externas USB', 'Solo en las carpetas sincronizadas con OneDrive']::text[], 0, 'El Sensor de almacenamiento «solo funciona en la unidad del sistema, que contiene el sistema operativo Windows, y generalmente se conoce como C:».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
