insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-010', null, 'Administrar el contenido en la nube disponible localmente', 'Desde Windows 11, versión 22H2, ¿cuándo pasa por defecto el Sensor de almacenamiento un archivo de OneDrive a solo en línea?', array['Si no se abre durante más de 7 días', 'Si no se abre durante más de 30 días', 'Si no se abre durante más de 14 días', 'Si no se abre durante más de 60 días']::text[], 1, 'A partir de esa versión, «el valor predeterminado para los archivos en la nube de OneDrive es crear archivos solo en línea si no se abren durante más de 30 días». Esta configuración «no eliminará permanentemente los archivos».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inb-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-011', null, 'Preguntas más frecuentes (P+F)', '¿Puede ejecutarse el Sensor de almacenamiento si no has iniciado sesión?', array['Sí, en cualquier momento, aunque nadie haya iniciado sesión', 'Sí, pero solo con el equipo conectado a la corriente', 'No: necesita sesión iniciada y estar en línea más de 10 minutos', 'No: solo se ejecuta justo después de reiniciar el equipo']::text[], 2, 'La respuesta de la página es: «No. El Sensor de almacenamiento no se puede ejecutar a menos que haya iniciado sesión y esté en línea durante más de 10 minutos».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
