insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-012', null, 'Paso 2: Hacer una copia de seguridad de las carpetas', '¿Cuánto almacenamiento en la nube de OneDrive incluye una cuenta Microsoft gratuita?', array['5 GB', '1 GB', '15 GB', '50 GB']::text[], 0, 'Según la página, «su cuenta Microsoft gratuita incluye 5 GB de almacenamiento en la nube de OneDrive», y se puede comprar más si se necesita.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
