insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-014', null, 'Modificar la configuración de la copia de seguridad', '¿En qué apartado de Configuración se cambia la copia de seguridad de Windows?', array['Sistema > Almacenamiento', 'Cuentas > Copias de seguridad de Windows', 'Privacidad y seguridad > Seguridad de Windows', 'Windows Update > Opciones avanzadas']::text[], 1, 'Para cambiar la configuración de la copia de seguridad, se abre «Configuración > cuentas > de Copias de seguridad de Windows».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
