insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-016', null, 'Resumen', '¿Cuál de estas características incluye la aplicación Seguridad de Windows?', array['Antivirus de Microsoft Defender', 'Sensor de almacenamiento', 'Copias de seguridad de Windows', 'Asistente de Windows Update']::text[], 0, 'La aplicación Seguridad de Windows «incluye características como Antivirus de Microsoft Defender, Firewall de Windows y Control Inteligente de Aplicaciones».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
