insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-020', null, 'Redes privadas y públicas', 'Según Microsoft, ¿qué tipo de red es el Wi-Fi de una cafetería?', array['Una red pública', 'Una red privada', 'Una red de dominio', 'Una red de confianza']::text[], 0, 'La página dice que «el Wi-Fi en su cafetería local es una red pública», mientras que la red doméstica sería un ejemplo de red privada.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
