insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-021', null, 'Configurar Firewall de Windows con Seguridad de Windows', '¿Qué hace la casilla «Bloquea todas las conexiones entrantes, incluidas las de la lista de aplicaciones permitidas»?', array['Desactiva el Firewall de Windows en las redes públicas', 'Bloquea solo las aplicaciones que no son de Microsoft Store', 'Restaura el firewall a los valores predeterminados', 'Hace que el firewall ignore la lista de permitidas y bloquee todo']::text[], 3, 'Esa casilla indica «al Firewall de Windows que ignore la lista de aplicaciones permitidas y bloquee todo». «Activar esta opción aumenta la seguridad, pero puede que algunas aplicaciones dejen de funcionar».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inb-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-022', null, 'Protéjase del fraude en línea', '¿Qué es el phishing o suplantación de identidad?', array['Un malware que cifra tus archivos y pide un rescate', 'Un ataque que busca que reveles datos personales en sitios falsos', 'Un programa que muestra anuncios no deseados en el navegador', 'Un fallo del firewall que deja pasar conexiones entrantes']::text[], 1, '«El phishing es un ataque que intenta robar su dinero o su identidad, haciendo que divulgue información personal [...] en sitios web que fingen ser sitios legítimos».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
