insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-023', null, 'Obtenga información sobre cómo detectar un mensaje de phishing', '¿Cuál de estas es una señal de un correo electrónico de phishing?', array['Que te llame por tu nombre y apellidos', 'Que venga del dominio oficial de la empresa', 'Que empiece con «Estimado señor o señora»', 'Que no incluya vínculos ni datos adjuntos']::text[], 2, 'Sobre los saludos genéricos, la página explica: «Si el correo electrónico empieza con un mensaje genérico, como "Estimado señor o señora", es un signo de que puede que no sea realmente su banco o sitio de compras».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inb-023', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-024', null, 'Obtenga información sobre cómo detectar un mensaje de phishing', 'Ante un vínculo sospechoso en un correo, ¿qué aconseja Microsoft para ver su dirección real?', array['Pasar el ratón por encima, sin hacer clic', 'Hacer clic y revisar la página que se abre', 'Reenviar el correo a un compañero', 'Copiar el vínculo y abrirlo en InPrivate']::text[], 0, 'La página aconseja: «no abra los vínculos o datos adjuntos que vea. En su lugar, pase el ratón por encima, pero no haga clic en el vínculo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
