insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-025', null, 'Qué hacer si cree que ya ha sufrido un ataque de phishing', 'Si crees que has sufrido un ataque de phishing, ¿qué debes hacer con tus contraseñas?', array['Poner la misma contraseña nueva en todas las cuentas', 'Esperar a que el banco confirme el fraude', 'Responder al mensaje para anular la contraseña', 'Cambiarla de inmediato en las cuentas afectadas']::text[], 3, '«Cambie inmediatamente la contraseña en todas las cuentas afectadas». Además, se debe «crear una contraseña distinta para cada cuenta».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
