insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-004', null, 'Métodos abreviados de teclado (Windows)', 'En Microsoft Edge para Windows, ¿qué hace la combinación Ctrl + W?', array['Cerrar la ventana actual', 'Duplicar la pestaña actual', 'Silenciar la pestaña actual', 'Cerrar la pestaña actual']::text[], 3, 'Ctrl + W sirve para «Cerrar la pestaña actual». Para cerrar la ventana actual se usa Ctrl + Mayús + W; Ctrl + Mayús + K duplica la pestaña.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
