insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-005', null, 'Métodos abreviados de teclado (Windows)', 'En Microsoft Edge, ¿qué combinación vuelve a abrir la última pestaña cerrada?', array['Ctrl + T', 'Ctrl + Mayús + T', 'Ctrl + Mayús + K', 'Ctrl + Mayús + W']::text[], 1, 'Ctrl + Mayús + T permite «Volver a abrir la última pestaña cerrada y cambiar a ella». Ctrl + T sirve para «Abrir una pestaña nueva y cambiar a ella».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
