insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-006', null, 'Métodos abreviados de teclado (Windows)', 'En Microsoft Edge, ¿qué tecla o combinación vuelve a cargar la pestaña actual omitiendo el contenido en caché?', array['F5', 'Mayús + F6', 'Mayús + F5', 'Ctrl + F6']::text[], 2, 'Mayús + F5 sirve para «Volver a cargar la pestaña actual y omitir el contenido en caché». F5 solo vuelve a cargar la pestaña y Mayús + F6 «Cambia el foco al panel anterior».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
