insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-007', null, '¿Cómo navego en modo InPrivate en Microsoft Edge?', '¿Cuándo elimina Microsoft Edge el historial, las cookies y los datos del sitio de una sesión InPrivate?', array['Al cerrar todas las ventanas InPrivate', 'Al cerrar cada pestaña InPrivate', 'Al apagar o reiniciar el equipo', 'Al cerrar la sesión de Windows']::text[], 0, 'Microsoft Edge eliminará el historial de exploración, las cookies y los datos del sitio, entre otros, «al cerrar todas las ventanas de InPrivate».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
