insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-008', null, '¿Qué hace Microsoft Edge con tus datos mientras te encuentras en InPrivate?', 'Durante la exploración InPrivate de Microsoft Edge, ¿qué se conserva para la próxima vez que uses el navegador?', array['Las cookies y datos del sitio', 'Las contraseñas y formularios nuevos', 'Los favoritos y los archivos descargados', 'El historial de exploración']::text[], 2, 'La exploración InPrivate «Guarda tus favoritos y los archivos descargados, para que puedas acceder a ellos la próxima vez que uses Microsoft Edge».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
