insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-009', null, '¿Cómo navego en modo InPrivate en Microsoft Edge?', 'Según Microsoft, mientras navegas InPrivate en Edge, ¿quién podría tener acceso a tu actividad de exploración?', array['Otras personas que usen el mismo dispositivo', 'Los usuarios que consulten el historial de Edge', 'Cualquier otro perfil de Edge del equipo', 'Tu proveedor de servicios de Internet']::text[], 3, '«Otras personas que usen este dispositivo no verán tu actividad de exploración, pero es posible que el proveedor de servicios de Internet o tu centro de trabajo o escuela puedan tener acceso a estos datos».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
