insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-010', null, '¿Qué hace Microsoft Edge con tus datos mientras te encuentras en InPrivate?', 'Si desde una ventana InPrivate abres edge://settings o edge://history, ¿qué hace Microsoft Edge?', array['Las abre en una ventana de exploración normal', 'Las bloquea y muestra un aviso', 'Las abre sin guardar los cambios', 'Cierra la ventana InPrivate actual']::text[], 0, 'Estas páginas «no se pueden ver en una ventana InPrivate. Si abres estas páginas al explorar, InPrivate las abrirá en una ventana de exploración normal».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
