insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-011', null, '¿Cuándo no está disponible la Exploración de InPrivate?', '¿Qué pueden usar las organizaciones, como centros educativos o lugares de trabajo, para impedir la exploración InPrivate?', array['La prevención de seguimiento', 'La directiva de grupo', 'SmartScreen de Microsoft Defender', 'El bloqueo de cookies de terceros']::text[], 1, '«Las organizaciones, como centros educativos o lugares de trabajo, pueden usar la directiva de grupo para impedir que los usuarios exploren InPrivate».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
