insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-012', null, '¿Cómo navego en modo InPrivate en Microsoft Edge?', 'Dentro de Microsoft Edge, ¿desde qué menú se puede abrir una nueva ventana InPrivate?', array['Barra de favoritos', 'Historial de exploración', 'Configuración y más', 'Panel de descargas']::text[], 2, 'Una de las formas de abrir una ventana InPrivate es: «En Microsoft Edge, selecciona Configuración y más > Nueva ventana InPrivate».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
