insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-013', null, 'Datos de navegación que puedes eliminar en Microsoft Edge', 'En Microsoft Edge, ¿qué ocurre al borrar el historial de descargas?', array['Se borran la lista y los archivos descargados', 'Se vacía la carpeta Descargas del equipo', 'Se eliminan las copias guardadas en caché', 'Solo se elimina la lista de archivos descargados']::text[], 3, 'El historial de descargas es la «Lista de los archivos que hayas descargado de la Web. Esto solo elimina la lista, no los archivos que hayas descargado».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
