insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-015', null, 'Borrar los datos de navegación almacenados en tu dispositivo', 'En la configuración de Microsoft Edge, ¿en qué apartado está la opción Borrar datos de navegación?', array['Perfiles', 'Privacidad, búsqueda y servicios', 'Apariencia', 'Sistema y rendimiento']::text[], 1, 'Para borrar los datos de navegación: «Selecciona Configuración y más > Configuración > Privacidad, búsqueda y servicios». Después se selecciona Borrar datos de navegación.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
