insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-016', null, 'Borrar los datos de navegación almacenados en tu dispositivo', 'Si la sincronización está activada y borras los datos de navegación en Microsoft Edge, ¿qué ocurre con los elementos sincronizados?', array['Solo se borran en el dispositivo actual', 'Solo se borran de la nube de Microsoft', 'Se borran de todos los dispositivos sincronizados', 'Se desactiva la sincronización del perfil']::text[], 2, 'La página advierte: «Los elementos que se sincronizan se borrarán de todos los dispositivos sincronizados». Para borrar solo en el dispositivo actual hay que desactivar la sincronización.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
