insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-017', null, 'Borrar los datos de exploración almacenados en la nube (si has activado la sincronización o la personalización)', '¿Desde dónde se administran y eliminan los datos de exploración de Edge guardados en la nube de Microsoft?', array['Desde el panel de privacidad', 'Desde Permisos del sitio', 'Desde Perfiles > Sincronizar', 'Desde la página de historial']::text[], 0, 'Para los datos de la nube hay que consultar «el panel de privacidad». Además, «Los datos que elimines del panel de privacidad no se eliminarán de tu dispositivo».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
