insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-018', null, 'Administrar cookies en Microsoft Edge: ver, permitir, bloquear, eliminar y usar', '¿Cómo se llaman las pequeñas piezas de datos que los sitios web almacenan en tu dispositivo, por ejemplo, para recordar el inicio de sesión?', array['Archivos en memoria caché', 'Permisos del sitio', 'Datos de autorrelleno', 'Cookies']::text[], 3, '«Las cookies son pequeñas piezas de datos almacenadas en su dispositivo por parte de los sitios web que visita». Sirven, entre otros fines, para «recordar las credenciales de inicio de sesión».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
