insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-019', null, 'Bloquear cookies de terceros', 'Según Microsoft, ¿qué puede ocurrir si bloqueas las cookies de terceros en Edge?', array['Que se cierre la sesión en todos los sitios', 'Que algunas páginas no se muestren bien', 'Que se borre el historial de exploración', 'Que SmartScreen deje de funcionar']::text[], 1, 'Al bloquearlas, «es posible que algunas páginas no se muestren correctamente o que aparezca un mensaje que te informe de que es necesario permitir las cookies».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
