insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-022', null, '¿Puedo activar o desactivar SmartScreen?', 'En Configuración > Privacidad, búsqueda y servicios de Microsoft Edge, ¿en qué sección se activa o desactiva SmartScreen?', array['Cookies', 'Permisos del sitio', 'Borrar datos de exploración', 'Seguridad']::text[], 3, 'Tras abrir Privacidad, búsqueda y servicios: «Selecciona Seguridad y, a continuación, activa o desactiva el botón de alternancia SmartScreen de Microsoft Defender».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
