insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-037', (select id from leyes where slug = 'ley-40-2015'), '66.2', 'Los Directores generales son nombrados y separados:', array['Por Orden del Ministro', 'Por Real Decreto del Presidente del Gobierno', 'Por resolución del Subsecretario', 'Por Real Decreto del Consejo de Ministros']::text[], 3, 'El artículo 66.2 establece que «serán nombrados y separados por Real Decreto del Consejo de Ministros, a propuesta del titular del Departamento o del Presidente del Gobierno».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-037', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-038', (select id from leyes where slug = 'ley-40-2015'), '67.2', 'Los Subdirectores generales son nombrados y cesados por:', array['El Consejo de Ministros, a propuesta del titular del Departamento', 'El Director general del que dependan, previa convocatoria pública', 'El Ministro, Secretario de Estado o Subsecretario del que dependan', 'El Presidente del Gobierno, a propuesta del Ministro correspondiente']::text[], 2, 'El artículo 67.2 dice que son nombrados y cesados «por el Ministro, Secretario de Estado o Subsecretario del que dependan».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
