insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-018', (select id from leyes where slug = 'ley-40-2015'), '19.2.d', 'En los órganos colegiados de la Administración General del Estado, ¿a quién corresponde dirimir con su voto los empates?', array['Al Secretario', 'Al miembro de mayor antigüedad', 'Al Presidente', 'Al Vicepresidente']::text[], 2, 'El artículo 19.2 atribuye al Presidente, entre otras funciones, «Dirimir con su voto los empates, a efectos de adoptar acuerdos», salvo en los órganos del artículo 15.2.', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-019', (select id from leyes where slug = 'ley-40-2015'), '18.1', '¿Quién levanta el acta de cada sesión de un órgano colegiado?', array['El Presidente', 'El Secretario', 'El miembro de menor edad', 'El Vicepresidente']::text[], 1, 'El artículo 18.1 dice: «De cada sesión que celebre el órgano colegiado se levantará acta por el Secretario».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-020', (select id from leyes where slug = 'ley-40-2015'), '18.2', 'El acta de cada sesión de un órgano colegiado puede aprobarse:', array['En la misma reunión o en la inmediata siguiente', 'Solo en la reunión inmediata siguiente', 'En el plazo de un mes desde la sesión', 'Solo en la misma reunión']::text[], 0, 'El artículo 18.2 dice: «El acta de cada sesión podrá aprobarse en la misma reunión o en la inmediata siguiente».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
