insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-001', (select id from leyes where slug = 'lo-3-2018'), '12.6', 'Los titulares de la patria potestad pueden ejercitar en nombre y representación de los menores los derechos de acceso, rectificación u oposición si son menores de:', array['Catorce años', 'Dieciséis años', 'Doce años', 'Dieciocho años']::text[], 0, 'El artículo 12.6 dispone que «los titulares de la patria potestad podrán ejercitar en nombre y representación de los menores de catorce años los derechos de acceso, rectificación, cancelación, oposición […]».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pdd-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 12 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-002', (select id from leyes where slug = 'lo-3-2018'), '12.4', 'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos del afectado recae sobre:', array['El encargado del tratamiento', 'El responsable del tratamiento', 'El delegado de protección de datos', 'El propio afectado']::text[], 1, 'El artículo 12.4 establece que la prueba del cumplimiento del deber de responder a la solicitud «recaerá sobre el responsable».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pdd-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 12 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-003', (select id from leyes where slug = 'lo-3-2018'), '12.3', 'El encargado puede tramitar, por cuenta del responsable, las solicitudes de ejercicio de derechos de los afectados:', array['Solo si lo autoriza la Agencia Española de Protección de Datos', 'Siempre que lo solicite el propio afectado', 'Si así se establece en el contrato o acto jurídico que les vincule', 'Únicamente cuando el responsable no haya designado delegado']::text[], 2, 'El artículo 12.3 dice que el encargado podrá tramitar las solicitudes «si así se estableciere en el contrato o acto jurídico que les vincule».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pdd-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 12 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-004', (select id from leyes where slug = 'lo-3-2018'), '13.2', 'El derecho de acceso se entiende otorgado si el responsable facilita al afectado un sistema de acceso a sus datos que sea:', array['Presencial, gratuito y confidencial', 'Electrónico, gratuito y verificable', 'Remoto, cifrado y temporal', 'Remoto, directo y seguro']::text[], 3, 'Según el artículo 13.2, el derecho de acceso se entenderá otorgado si el responsable facilitara «un sistema de acceso remoto, directo y seguro a los datos personales que garantice, de modo permanente, el acceso a su totalidad».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pdd-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 12 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-005', (select id from leyes where slug = 'lo-3-2018'), '13.4', 'Si el afectado elige para el acceso un medio distinto al ofrecido que supone un coste desproporcionado, su solicitud se considera:', array['Excesiva', 'Repetitiva', 'Improcedente', 'Abusiva']::text[], 0, 'El artículo 13.4 indica que en ese caso «la solicitud será considerada excesiva, por lo que dicho afectado asumirá el exceso de costes que su elección comporte».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
