insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-006', (select id from leyes where slug = 'lo-3-2018'), '14', 'Al ejercer el derecho de rectificación, el afectado debe indicar en su solicitud:', array['El motivo por el que se opone al tratamiento', 'A qué datos se refiere y la corrección que haya de realizarse', 'El responsable al que desea transmitir sus datos', 'El plazo en que debe atenderse su petición']::text[], 1, 'El artículo 14 establece que el afectado «deberá indicar en su solicitud a qué datos se refiere y la corrección que haya de realizarse».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
