insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-013', (select id from leyes where slug = 'lo-3-2018'), '44.2', 'La Agencia Española de Protección de Datos tiene la condición de representante común de las autoridades de protección de datos españolas en:', array['El Comité Europeo de Protección de Datos', 'El Consejo de Europa', 'La Comisión Europea', 'El Supervisor Europeo de Protección de Datos']::text[], 0, 'El artículo 44.2 dispone que la Agencia «tendrá la condición de representante común de las autoridades de protección de datos del Reino de España en el Comité Europeo de Protección de Datos».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
