insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-018', (select id from leyes where slug = 'lo-3-2018'), '49.5', 'Las decisiones tomadas por el Consejo Consultivo de la Agencia Española de Protección de Datos:', array['Son vinculantes para la Presidencia', 'No tienen en ningún caso carácter vinculante', 'Solo vinculan en materia sancionadora', 'Requieren ratificación del Gobierno']::text[], 1, 'El artículo 49.5 dispone: «Las decisiones tomadas por el Consejo Consultivo no tendrán en ningún caso carácter vinculante».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
