insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-021', (select id from leyes where slug = 'lo-3-2018'), '67.2', 'Las actuaciones previas de investigación de la AEPD no pueden durar más de:', array['Dieciocho meses', 'Doce meses', 'Seis meses', 'Veinticuatro meses']::text[], 0, 'El artículo 67.2 dispone que las actuaciones previas de investigación «no podrán tener una duración superior a dieciocho meses».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
