insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-023', (select id from leyes where slug = 'lo-3-2018'), '78.1.b', 'Las sanciones por importe comprendido entre 40.001 y 300.000 euros impuestas en aplicación de la LO 3/2018 prescriben:', array['Al año', 'A los tres años', 'A los dos años', 'A los cinco años']::text[], 2, 'El artículo 78.1.b) dispone: «Las sanciones por importe comprendido entre 40.001 y 300.000 euros prescriben a los dos años».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
