insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-024', (select id from leyes where slug = 'lo-3-2018'), '94.3', 'Si una persona pide suprimir de una red social datos facilitados durante su minoría de edad, el prestador debe suprimirlos:', array['En el plazo de un mes', 'Solo si los facilitó un tercero', 'Previa autorización de sus representantes legales', 'Sin dilación, por su simple solicitud']::text[], 3, 'El artículo 94.3 dispone que, respecto de datos facilitados durante su minoría de edad, «el prestador deberá proceder sin dilación a su supresión por su simple solicitud».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
