insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-012', (select id from leyes where slug = 'lo-3-2018'), '74', 'Según la LO 3/2018, las infracciones consideradas leves prescriben:', array['A los seis meses', 'A los dos años', 'Al año', 'A los tres meses']::text[], 2, 'El artículo 74 dice: «Se consideran leves y prescribirán al año» las restantes infracciones de carácter meramente formal.', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
