insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-013', (select id from leyes where slug = 'lo-3-2018'), '73', 'Según la LO 3/2018, las infracciones consideradas graves prescriben:', array['Al año', 'A los dos años', 'A los tres años', 'A los seis meses']::text[], 1, 'El artículo 73 dice: que se consideran graves «y prescribirán a los dos años» las infracciones que supongan una vulneración sustancial de los artículos mencionados en el artículo 83.4 del Reglamento.', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
