insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-002', (select id from leyes where slug = 'ley-50-1981'), '1', 'Además de promover la acción de la justicia, el artículo 1 del EOMF encomienda al Ministerio Fiscal:', array['Unificar la doctrina de los Tribunales', 'Velar por la independencia de los Tribunales', 'Gobernar los órganos judiciales', 'Inspeccionar los Juzgados y Tribunales']::text[], 1, 'Según el artículo 1, el Ministerio Fiscal tiene por misión promover la acción de la justicia […] «así como velar por la independencia de los Tribunales, y procurar ante éstos la satisfacción del interés social».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
