insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-003', (select id from leyes where slug = 'ley-50-1981'), '7', 'Por el principio de imparcialidad, el Ministerio Fiscal actuará:', array['Con sujeción a las instrucciones del Gobierno', 'Bajo la dependencia de sus superiores', 'Con plena objetividad e independencia', 'Conforme a criterios de oportunidad']::text[], 2, 'El artículo 7 dice: «Por el principio de imparcialidad el Ministerio Fiscal actuará con plena objetividad e independencia en defensa de los intereses que le estén encomendados».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
