insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-004', (select id from leyes where slug = 'ley-50-1981'), '6', 'Por el principio de legalidad, el Ministerio Fiscal actuará con sujeción a:', array['Las órdenes del Ministro de Justicia', 'Los criterios de la Junta de Fiscales de Sala', 'La doctrina del Tribunal Supremo', 'La Constitución, las leyes y demás normas del ordenamiento']::text[], 3, 'El artículo 6 dice: «Por el principio de legalidad el Ministerio Fiscal actuará con sujeción a la Constitución, a las leyes y demás normas que integran el ordenamiento jurídico vigente […]».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
