insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-005', (select id from leyes where slug = 'ley-50-1981'), '12', '¿Cuál de los siguientes NO figura entre los órganos del Ministerio Fiscal del artículo 12 del EOMF?', array['La Fiscalía del Consejo de Estado', 'La Fiscalía Jurídico Militar', 'La Fiscalía del Tribunal de Cuentas', 'Las Fiscalías de Área']::text[], 0, 'El artículo 12 enumera, entre otros, «i) La Fiscalía del Tribunal de Cuentas», «j) La Fiscalía Jurídico Militar» y «m) Las Fiscalías de Área». No incluye ninguna Fiscalía del Consejo de Estado.', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
