insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-006', (select id from leyes where slug = 'ley-50-1981'), '14.1', 'Los miembros electivos del Consejo Fiscal se eligen por un período de:', array['Tres años', 'Cuatro años', 'Cinco años', 'Seis años']::text[], 1, 'El artículo 14.1 dice que los miembros electivos del Consejo Fiscal «se elegirán, por un período de cuatro años».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
