insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-007', (select id from leyes where slug = 'ley-50-1981'), '14.1', 'Además de sus miembros natos, ¿cuántos Fiscales pertenecientes a cualquiera de las categorías forman parte del Consejo Fiscal?', array['Siete', 'Doce', 'Nueve', 'Ocho']::text[], 2, 'El artículo 14.1 dice que el Consejo Fiscal se constituirá con la persona titular de la Fiscalía General del Estado, el Teniente Fiscal del Tribunal Supremo, el Fiscal Jefe Inspector «y nueve Fiscales pertenecientes a cualquiera de las categorías».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
