insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-009', (select id from leyes where slug = 'ley-50-1981'), '14.3', 'En caso de empate en las votaciones del Consejo Fiscal:', array['Es dirimente el voto de su Presidente', 'Se repite la votación en la sesión siguiente', 'Decide la Junta de Fiscales de Sala', 'Se entiende rechazada la propuesta']::text[], 0, 'El artículo 14.3 dice que los acuerdos del Consejo Fiscal se adoptarán «por mayoría simple, siendo dirimente, en caso de empate, el voto de su Presidente».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
