insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-011', (select id from leyes where slug = 'ley-50-1981'), '14.2', 'No pueden ser elegidos vocales del Consejo Fiscal los Fiscales que prestan servicios en:', array['La Fiscalía de la Audiencia Nacional', 'La Fiscalía del Tribunal Supremo', 'La Secretaría Técnica de la Fiscalía General', 'Las Fiscalías Provinciales']::text[], 2, 'El artículo 14.2 dice: «No podrán ser elegidos vocales del Consejo Fiscal los Fiscales que presten sus servicios en la Inspección Fiscal, la Unidad de Apoyo y la Secretaría Técnica de la Fiscalía General del Estado».', 3, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
