insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-014', (select id from leyes where slug = 'ley-50-1981'), '29.3', 'Una vez nombrado, el Fiscal General del Estado toma posesión del cargo ante:', array['El Consejo de Ministros', 'El Pleno del Tribunal Supremo', 'El Pleno del Consejo General del Poder Judicial', 'La Comisión de Justicia del Congreso']::text[], 1, 'El artículo 29.3 dice que el Fiscal General del Estado prestará ante el Rey el juramento o promesa «y tomará posesión del cargo ante el Pleno del Tribunal Supremo».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
