insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-015', (select id from leyes where slug = 'ley-50-1981'), '29.2', 'Recibido el informe del Consejo General del Poder Judicial, el Gobierno comunica su propuesta de Fiscal General del Estado a:', array['El Senado', 'Las Cortes Generales en sesión conjunta', 'El Congreso de los Diputados', 'El Tribunal Supremo']::text[], 2, 'El artículo 29.2 dice que «el Gobierno comunicará su propuesta al Congreso de los Diputados, a fin de que pueda disponer la comparecencia de la persona elegida ante la Comisión correspondiente».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
