insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-016', (select id from leyes where slug = 'ley-50-1981'), '31.1', 'El mandato del Fiscal General del Estado tiene una duración de:', array['Cinco años', 'Tres años', 'Seis años', 'Cuatro años']::text[], 3, 'El artículo 31.1 dice: «El mandato del Fiscal General del Estado tendrá una duración de cuatro años».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
