insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-017', (select id from leyes where slug = 'ley-50-1981'), '31.2', 'El mandato del Fiscal General del Estado puede renovarse solo si el titular ha ostentado el cargo durante un periodo inferior a:', array['Dos años', 'Un año', 'Tres años', 'Seis meses']::text[], 0, 'El artículo 31.2 dice que el mandato «no podrá ser renovado, excepto en los supuestos en que el titular hubiera ostentado el cargo durante un periodo inferior a dos años».', 3, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
