insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-001', (select id from leyes where slug = 'constitucion'), '137', 'Según el artículo 137 de la Constitución, el Estado se organiza territorialmente en:', array['Municipios, provincias y las Comunidades Autónomas que se constituyan', 'Municipios, comarcas y las Comunidades Autónomas que se constituyan', 'Provincias, regiones y las Comunidades Autónomas que se constituyan', 'Municipios, provincias, comarcas y Comunidades Autónomas']::text[], 0, 'El artículo 137 dice: «El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
