insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-002', (select id from leyes where slug = 'constitucion'), '138.2', 'Las diferencias entre los Estatutos de las distintas Comunidades Autónomas no podrán implicar, en ningún caso:', array['Diferencias en las competencias asumidas', 'Desigualdades en la organización institucional', 'Privilegios económicos o sociales', 'Distintos regímenes de financiación']::text[], 2, 'El artículo 138.2 establece que esas diferencias «no podrán implicar, en ningún caso, privilegios económicos o sociales».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
