insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-003', (select id from leyes where slug = 'constitucion'), '140', 'Según la Constitución, los Alcaldes serán elegidos:', array['Solo por los vecinos, por sufragio universal', 'Por los Concejales o por los vecinos', 'Por el Pleno de la Diputación provincial', 'Solo por los Concejales, por mayoría absoluta']::text[], 1, 'El artículo 140 dispone: «Los Alcaldes serán elegidos por los Concejales o por los vecinos».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
