insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-004', (select id from leyes where slug = 'constitucion'), '141.1', 'Cualquier alteración de los límites provinciales habrá de ser aprobada por:', array['Las Comunidades Autónomas afectadas mediante ley', 'El Gobierno mediante real decreto', 'Las Diputaciones afectadas, con ratificación del Senado', 'Las Cortes Generales mediante ley orgánica']::text[], 3, 'El artículo 141.1 dice: «Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
