insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-005', (select id from leyes where slug = 'constitucion'), '141.4', 'En los archipiélagos, las islas tendrán además su administración propia en forma de:', array['Diputaciones insulares', 'Mancomunidades insulares', 'Cabildos o Consejos', 'Comarcas o Juntas']::text[], 2, 'El artículo 141.4 establece: «En los archipiélagos, las islas tendrán además su administración propia en forma de Cabildos o Consejos».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
