insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-007', (select id from leyes where slug = 'constitucion'), '143.2', 'Los requisitos de la iniciativa del proceso autonómico del artículo 143.2 deben cumplirse en el plazo de:', array['Tres meses desde el primer acuerdo de alguna Corporación local interesada', 'Un año desde el primer acuerdo de alguna Corporación local interesada', 'Dos meses desde el primer acuerdo de alguna Corporación local interesada', 'Seis meses desde el primer acuerdo de alguna Corporación local interesada']::text[], 3, 'El artículo 143.2 dice: «Estos requisitos deberán ser cumplidos en el plazo de seis meses desde el primer acuerdo adoptado al respecto por alguna de las Corporaciones locales interesadas».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
