insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-010', (select id from leyes where slug = 'constitucion'), '144', 'Las Cortes Generales pueden, mediante ley orgánica, autorizar las actuaciones del artículo 144 por motivos de:', array['Interés general', 'Solidaridad interterritorial', 'Urgente necesidad', 'Interés nacional']::text[], 3, 'El artículo 144 dice: «Las Cortes Generales, mediante ley orgánica, podrán, por motivos de interés nacional: […]».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
