insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-021', (select id from leyes where slug = 'constitucion'), '150.3', 'La necesidad de dictar leyes de armonización la aprecian las Cortes Generales por:', array['Mayoría simple de cada Cámara', 'Mayoría absoluta de cada Cámara', 'Mayoría de tres quintos de cada Cámara', 'Mayoría absoluta del Congreso']::text[], 1, 'El artículo 150.3 dice: «Corresponde a las Cortes Generales, por mayoría absoluta de cada Cámara, la apreciación de esta necesidad».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
