insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-022', (select id from leyes where slug = 'constitucion'), '150.2', 'El Estado podrá transferir o delegar en las Comunidades Autónomas facultades de titularidad estatal mediante:', array['Ley marco', 'Ley de armonización', 'Real decreto legislativo', 'Ley orgánica']::text[], 3, 'El artículo 150.2 dispone: «El Estado podrá transferir o delegar en las Comunidades Autónomas, mediante ley orgánica, facultades correspondientes a materia de titularidad estatal […]».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
