insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-025', (select id from leyes where slug = 'constitucion'), '152.1', 'En las Comunidades del artículo 152.1, el Presidente es elegido por la Asamblea, de entre sus miembros, y nombrado por:', array['El Rey', 'El Presidente del Gobierno', 'El Presidente del Congreso', 'El Consejo de Gobierno']::text[], 0, 'El artículo 152.1 prevé «un Presidente, elegido por la Asamblea, de entre sus miembros, y nombrado por el Rey».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
