insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-026', (select id from leyes where slug = 'constitucion'), '152.1', '¿Qué órgano culmina la organización judicial en el ámbito territorial de la Comunidad Autónoma?', array['La Audiencia Nacional', 'Un Tribunal Superior de Justicia', 'Una Audiencia Provincial', 'El Consejo de Justicia autonómico']::text[], 1, 'El artículo 152.1 dice: «Un Tribunal Superior de Justicia, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo, culminará la organización judicial en el ámbito territorial de la Comunidad Autónoma».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
