insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-027', (select id from leyes where slug = 'constitucion'), '153.b', 'El control del ejercicio de funciones delegadas a las Comunidades Autónomas según el artículo 150.2 lo ejerce:', array['El Tribunal Constitucional', 'La jurisdicción contencioso-administrativa', 'El Senado, previo informe del Gobierno', 'El Gobierno, previo dictamen del Consejo de Estado']::text[], 3, 'El artículo 153.b) atribuye ese control «Por el Gobierno, previo dictamen del Consejo de Estado, el del ejercicio de funciones delegadas a que se refiere el apartado 2 del artículo 150».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
