insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-003', null, 'Crear un mensaje de correo electrónico en la versión clásica de Outlook', 'En Outlook clásico, en la pestaña Insertar de un mensaje, ¿qué opción permite adjuntar mensajes de correo, tareas, contactos o elementos del calendario?', array['Imagen en línea', 'Firma de correo', 'Elemento de Outlook', 'Vínculo de texto']::text[], 2, 'En la pestaña Insertar se puede seleccionar «Elemento de Outlook» para adjuntar elementos de Outlook, «como mensajes de correo electrónico, tareas, contactos o elementos del calendario».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
