insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-004', null, 'Crear un mensaje de correo electrónico en la versión clásica de Outlook', 'En Outlook clásico, con varias cuentas de correo configuradas, ¿qué botón del mensaje nuevo permite cambiar la cuenta que lo enviará?', array['Para', 'Remitente', 'Cuenta', 'De']::text[], 3, 'Con varias cuentas configuradas, «aparece el botón De y se muestra la cuenta que enviará el mensaje». Para cambiarla, se hace clic en De y se elige otra cuenta.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
