insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-007', null, 'Ver destinatarios del cuadro CCO', 'En Outlook clásico, ¿quién puede ver los nombres de los destinatarios incluidos en el campo CCO de un mensaje?', array['Los destinatarios del campo Para', 'Todos los destinatarios del mensaje', 'Solo el remitente del mensaje', 'Los destinatarios del campo CC']::text[], 2, 'La página indica: «Solo el remitente de un mensaje puede ver los nombres de los destinatarios CCO», abriendo el mensaje en la carpeta Elementos enviados.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
