insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-009', null, 'Procedimientos recomendados para usar el cuadro CCO', 'Según Microsoft, ¿por qué un mensaje enviado con destinatarios en CCO puede acabar en la carpeta de correo no deseado?', array['Porque muchos filtros de correo no deseado marcan los mensajes que usan CCO', 'Porque los mensajes con CCO se envían sin indicar el remitente', 'Porque el campo CCO elimina el asunto del mensaje', 'Porque Outlook bloquea los mensajes con más de un destinatario CCO']::text[], 0, 'La página explica: «Usar el cuadro CCO es la técnica favorita de los remitentes de spam. Por lo tanto, muchos de los filtros de correo no deseado marcan los mensajes que usan el cuadro CCO como correo no deseado».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
