insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-010', null, 'Procedimientos recomendados para usar el cuadro CCO', 'Si incluye una lista de distribución en el campo CCO, ¿qué puede ocurrir a los destinatarios que ordenan su correo con reglas?', array['Que el mensaje se elimine sin llegar a la bandeja de entrada', 'Que el mensaje no se ordene según sus reglas', 'Que el mensaje se reenvíe de vuelta al remitente', 'Que el mensaje se duplique en todas sus carpetas']::text[], 1, 'Las reglas de esas personas dependen de que la lista esté en los cuadros Para o CC, así que «el mensaje no se ordenará según sus reglas».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
