insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-011', null, 'Administrar mensajes de correo electrónico mediante reglas en Outlook', 'En Outlook, ¿para qué sirven las reglas?', array['Para programar el envío de un mensaje a una hora concreta', 'Para responder automáticamente mientras está ausente', 'Para realizar automáticamente acciones en el correo que llega a la bandeja de entrada', 'Para añadir automáticamente una firma a los mensajes nuevos']::text[], 2, 'La página indica: «Use reglas para realizar automáticamente acciones específicas en el correo electrónico que llega a su bandeja de entrada», como cambiar la importancia, mover o eliminar mensajes.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
