insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-012', null, 'Crear una regla de bandeja de entrada para el nuevo Outlook para Windows', 'En el nuevo Outlook para Windows, ¿qué elementos necesita como mínimo cada regla?', array['Una condición, una acción y una excepción', 'Un remitente, una carpeta y una acción', 'Una condición y una excepción', 'Un nombre, una condición y una acción']::text[], 3, 'Según Microsoft, «Cada regla necesita al menos tres elementos: Un nombre, una condición y una acción». Las excepciones son opcionales.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
