insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-014', null, 'Crear una regla en un mensaje en Outlook clásico para Windows', 'En Outlook clásico, al crear una regla desde un mensaje, ¿qué casilla aplica la regla de inmediato a los mensajes que ya están en la carpeta actual?', array['Detener el procesamiento de más reglas', 'Ejecutar esta nueva regla ahora', 'Incluir subcarpetas', 'Mostrar en la ventana de alertas']::text[], 1, 'La página indica: «Para usar la regla de inmediato, active la casilla Ejecutar esta nueva regla ahora en los mensajes que ya están en la carpeta actual».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
