insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-015', null, 'Eliminar una regla en Outlook clásico para Windows', 'En Outlook clásico, ¿cómo se suspende temporalmente una regla sin eliminarla?', array['Cambiando el nombre de la regla', 'Moviendo la regla al final de la lista', 'Desactivando la casilla junto a la regla', 'Exportando la regla a un archivo']::text[], 2, 'Según Microsoft, «Para suspender temporalmente una regla, desactiva la casilla de verificación junto a la regla». Así se mantiene y se puede activar más tarde.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
