insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-016', null, 'Ejecutar reglas manualmente en Outlook clásico para Windows', 'En Outlook clásico, en el cuadro Ejecutar reglas ahora, ¿qué permite elegir la lista Aplicar reglas a?', array['Bandeja de entrada o Elementos enviados', 'Mensajes con o sin datos adjuntos', 'Mensajes de hoy, de la semana o del mes', 'Todos los mensajes, leídos o no leídos']::text[], 3, 'En la lista Aplicar reglas a, se puede aceptar «la configuración predeterminada de todos los mensajes o cámbiela a mensajes leídos o no leídos».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
