insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-017', null, 'Crear una regla de bandeja de entrada para el nuevo Outlook para Windows', 'En el nuevo Outlook para Windows, ¿qué casilla evita que se ejecute ninguna regla después de la que está creando?', array['Detener el procesamiento de más reglas', 'Ejecutar reglas ahora', 'Omitir las reglas siguientes', 'Desactivar reglas posteriores']::text[], 0, 'La página indica: «Si no quiere que se ejecute ninguna regla después de esta, seleccione la casilla Detener el procesamiento de más reglas».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
