insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-020', null, 'Solución de problemas: No tengo respuestas automáticas', 'En Outlook clásico, si al seleccionar Archivo no aparece Respuestas automáticas, ¿cuál puede ser la causa?', array['Que no tenga ninguna firma configurada', 'Que tenga desactivadas todas las reglas', 'Que el panel de lectura esté oculto', 'Que use una cuenta de Gmail, Yahoo, POP o IMAP']::text[], 3, 'La página explica que «es posible que esté usando una cuenta de Gmail, Yahoo u otra cuenta de POP o IMAP que no admite la característica Respuestas automáticas de Outlook». En ese caso puede usarse una regla.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
