insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-022', null, 'Crear su firma y elegir cuándo Outlook agrega una firma a sus mensajes en Outlook clásico para Windows', 'En Outlook clásico, crea una firma desde un mensaje nuevo y la elige para todos los mensajes nuevos. ¿Se añade a ese mensaje abierto?', array['Sí, se añade al pulsar Aceptar', 'No, debe agregarla manualmente a ese mensaje', 'Sí, pero solo si el mensaje está en HTML', 'No, solo se añade a las respuestas y reenvíos']::text[], 1, 'La página indica: «Outlook clásico no agrega la nueva firma al mensaje que abrió en el paso 1» y «Tendrá que agregar la firma manualmente a este mensaje».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
