insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-023', null, 'Crear su firma y elegir cuándo Outlook agrega una firma a sus mensajes en Outlook clásico para Windows', 'En Outlook clásico, en Elegir firma predeterminada, ¿qué lista desplegable hace que la firma aparezca en las respuestas y reenvíos?', array['Nuevos mensajes', 'Cuenta de correo electrónico', 'Respuestas/reenvíos', 'Seleccionar firma para editar']::text[], 2, 'Según Microsoft, «Puede seleccionar que su firma aparezca automáticamente en los mensajes de respuesta y reenvío. En la lista desplegable Respuestas/reenvíos», se selecciona una de las firmas.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
