insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-024', null, 'Crear su firma y elegir cuándo Outlook agrega una firma a sus mensajes en Outlook clásico para Windows', 'En Outlook clásico para Windows, ¿dónde se almacenan las firmas creadas en el dispositivo?', array['En el buzón del servidor de correo', 'En la carpeta Elementos enviados', 'En la plantilla Normal de Word', 'Localmente, en el dispositivo donde se crearon']::text[], 3, 'La página indica: «Las firmas en este dispositivo se almacenan localmente en el dispositivo donde se crearon y es posible que no estén disponibles al usar Outlook en otro dispositivo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
