insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-025', null, 'Adjuntar un archivo a un mensaje de correo electrónico en Outlook clásico', 'En Outlook clásico, ¿en qué grupo de la pestaña Mensaje está el botón Adjuntar archivo?', array['Incluir', 'Insertar', 'Etiquetas', 'Básicos']::text[], 0, 'La página indica: «En el borrador del mensaje, vaya a la pestaña Mensaje y seleccione Adjuntar archivo en el grupo Incluir».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
