insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-026', null, 'Adjuntar un archivo a un mensaje de correo electrónico en Outlook clásico', 'En Outlook clásico, al seleccionar Adjuntar archivo, ¿cuántos archivos muestra la opción Elementos recientes?', array['Los 3 más recientes', 'Los 12 más recientes', 'Los 6 más recientes', 'Los 10 más recientes']::text[], 1, 'En Elementos recientes, «Aquí se muestran los 12 archivos más recientes en los que haya trabajado», ya estén en el equipo, en OneDrive o en SharePoint.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
