insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-027', null, 'Adjuntar un archivo a un mensaje de correo electrónico en Outlook clásico', 'En Outlook clásico, ¿qué ventaja tiene enviar un vínculo a un archivo de OneDrive en lugar de una copia?', array['Que el archivo se convierte a PDF', 'Que el destinatario no puede reenviarlo', 'Que el tamaño del mensaje es reducido', 'Que el archivo se cifra automáticamente']::text[], 2, 'Según Microsoft, «Enviar un vínculo al archivo de OneDrive o SharePoint hace que el tamaño del mensaje de correo sea reducido».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
