insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-028', null, 'Adjuntar un archivo a un mensaje de correo electrónico en Outlook clásico', 'En Outlook clásico, adjunta un vínculo de OneDrive. ¿Qué permiso elige para que solo los destinatarios puedan leer el archivo, pero no modificarlo?', array['La organización puede ver', 'Los destinatarios pueden editar', 'La organización puede editar', 'Los destinatarios pueden ver']::text[], 3, 'La página describe: «Los destinatarios pueden ver , si quiere que solo los destinatarios del correo electrónico puedan leer el archivo, pero no modificarlo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
