insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pj-024', (select id from leyes where slug = 'constitucion'), '126', 'En sus funciones de averiguación del delito y descubrimiento del delincuente, la policía judicial depende:', array['Del Gobierno y de sus Delegados', 'De los Jueces, de los Tribunales y del Ministerio Fiscal', 'Del Consejo General del Poder Judicial', 'Exclusivamente del Ministerio Fiscal']::text[], 1, 'El artículo 126 dice: «La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
