insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pj-025', (select id from leyes where slug = 'constitucion'), '127.1', 'Mientras se hallen en activo, los Jueces, Magistrados y Fiscales no podrán:', array['Pertenecer a asociaciones profesionales', 'Ejercer el derecho de sufragio', 'Pertenecer a partidos políticos o sindicatos', 'Ejercer la acción popular']::text[], 2, 'El artículo 127.1 dice que, mientras se hallen en activo, no podrán «desempeñar otros cargos públicos, ni pertenecer a partidos políticos o sindicatos».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
