insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-001', (select id from leyes where slug = 'lo-6-1985'), '9.2', 'Los Tribunales del orden civil conocerán, además de las materias que les son propias, de:', array['Las que les encomiende expresamente el CGPJ', 'Todas aquellas que no estén atribuidas a otro orden jurisdiccional', 'Las reclamaciones en materia de Seguridad Social', 'Las cuestiones prejudiciales de los demás órdenes']::text[], 1, 'El artículo 9.2 dice que conocerán «de todas aquellas que no estén atribuidas a otro orden jurisdiccional».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
