insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-002', (select id from leyes where slug = 'lo-6-1985'), '9.6', 'Según la Ley Orgánica del Poder Judicial, la jurisdicción es:', array['Prorrogable por acuerdo de las partes', 'Renunciable por el demandante', 'Delegable en la Administración', 'Improrrogable']::text[], 3, 'El artículo 9.6 dice: «La jurisdicción es improrrogable».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
