insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-003', (select id from leyes where slug = 'lo-6-1985'), '9.5', '¿Qué orden jurisdiccional conoce de las reclamaciones en materia de Seguridad Social?', array['El orden social', 'El orden civil', 'El orden contencioso-administrativo', 'El orden penal']::text[], 0, 'El artículo 9.5 dice que los del orden jurisdiccional social conocerán de «las reclamaciones en materia de Seguridad Social».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
