insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-004', (select id from leyes where slug = 'lo-6-1985'), '9.4', 'Los recursos contra las Normas Forales fiscales de las Juntas Generales de Álava, Guipúzcoa y Vizcaya corresponden en exclusiva:', array['A la Sala de lo Contencioso-Administrativo del Tribunal Supremo', 'Al Tribunal Superior de Justicia del País Vasco', 'Al Tribunal Constitucional', 'A la Sala de lo Contencioso-Administrativo de la Audiencia Nacional']::text[], 2, 'El artículo 9.4 excluye del orden contencioso estos recursos, «que corresponderán, en exclusiva, al Tribunal Constitucional».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
