insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-006', (select id from leyes where slug = 'lo-6-1985'), '29.1', 'La planta de los tribunales se revisará, previo informe del CGPJ, al menos cada:', array['Tres años', 'Cinco años', 'Cuatro años', 'Diez años']::text[], 1, 'El artículo 29.1 dice que la planta «Será revisada con base en la evolución de las cargas de trabajo, población y otros parámetros que se consideren relevantes, al menos, cada cinco años».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
