insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-007', (select id from leyes where slug = 'lo-6-1985'), '30', 'A efectos judiciales, el Estado se organiza territorialmente en:', array['Municipios, Comarcas, Provincias y Comunidades Autónomas', 'Partidos, Provincias, Comunidades Autónomas y Estado', 'Municipios, Partidos, Provincias y Comunidades Autónomas', 'Municipios, Partidos, Provincias y Regiones']::text[], 2, 'El artículo 30 dice: «El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
