insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-008', (select id from leyes where slug = 'lo-6-1985'), '32.1', 'El partido judicial es la unidad territorial integrada por:', array['Uno o más municipios limítrofes de una misma provincia', 'Dos o más municipios de una misma comarca', 'Uno o más municipios, aunque sean de distintas provincias', 'Varios municipios limítrofes de una misma Comunidad Autónoma']::text[], 0, 'El artículo 32.1 dice: «El partido es la unidad territorial integrada por uno o más municipios limítrofes, pertenecientes a una misma provincia».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
