insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-009', (select id from leyes where slug = 'lo-6-1985'), '35.6', '¿Quién determina la capitalidad de los partidos judiciales?', array['Las Comunidades Autónomas, por ley, previo informe del CGPJ', 'El Gobierno, por real decreto, previo informe del CGPJ', 'El CGPJ, oídas las Comunidades Autónomas afectadas', 'Las Cortes Generales, mediante ley orgánica']::text[], 0, 'El artículo 35.6 dice: «Las Comunidades Autónomas, previo informe del Consejo General del Poder Judicial, determinarán, por ley, la capitalidad de los partidos judiciales».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
