insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-011', (select id from leyes where slug = 'lo-6-1985'), '57.1.2º', '¿Qué órgano instruye y enjuicia las causas contra Diputados y Senadores?', array['La Sala de lo Penal de la Audiencia Nacional', 'La Sala de lo Penal del Tribunal Supremo', 'La Sala de lo Civil y Penal del Tribunal Superior de Justicia', 'La Audiencia Provincial de Madrid']::text[], 1, 'El artículo 57.1 atribuye a la Sala de lo Penal del Tribunal Supremo el conocimiento «De la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, […] Diputados y Senadores».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
