insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-012', (select id from leyes where slug = 'lo-6-1985'), '58', 'Los recursos contencioso-administrativos contra actos y disposiciones del Consejo de Ministros los conoce en única instancia:', array['La Sala de lo Contencioso-Administrativo de la Audiencia Nacional', 'El Tribunal Superior de Justicia de Madrid', 'La Sección de lo Contencioso del Tribunal Central de Instancia', 'La Sala de lo Contencioso-Administrativo del Tribunal Supremo']::text[], 3, 'El artículo 58 dice que la Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá «En única instancia, de los recursos contencioso-administrativos contra actos y disposiciones del Consejo de Ministros».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
