insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-014', (select id from leyes where slug = 'lo-6-1985'), '63.2', 'El Presidente de la Audiencia Nacional tiene la consideración de:', array['Presidente de Sala del Tribunal Supremo', 'Magistrado del Tribunal Supremo', 'Vicepresidente del Tribunal Supremo', 'Vocal del Consejo General del Poder Judicial']::text[], 0, 'El artículo 63.2 dice: «El Presidente de la Audiencia Nacional, que tendrá la consideración de Presidente de Sala del Tribunal Supremo, es el Presidente nato de todas sus Salas».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
