insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-015', (select id from leyes where slug = 'lo-6-1985'), '600.4', 'Salvo en la sesión de elección del Presidente, para la válida constitución del Pleno del CGPJ se necesita como mínimo la presencia de:', array['Doce de sus miembros', 'Quince Vocales y el Presidente', 'La mayoría absoluta de los Vocales', 'Diez Vocales y el Presidente']::text[], 3, 'El artículo 600.4 dice: «En los demás casos, para la válida constitución del Pleno será siempre necesaria, como mínimo, la presencia de diez Vocales y el Presidente».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
