insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-019', (select id from leyes where slug = 'lo-6-1985'), '84.1', 'Según la LOPJ, habrá un Tribunal de Instancia en cada:', array['Partido judicial', 'Municipio', 'Provincia', 'Comunidad Autónoma']::text[], 0, 'El artículo 84.1 dice: «Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que tomará su nombre».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
