insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-020', (select id from leyes where slug = 'lo-6-1985'), '84.3.b', 'Para que una Sección del Tribunal de Instancia tenga Presidencia de Sección, debe contar, entre otros requisitos, con:', array['Cuatro o más plazas judiciales', 'Seis o más plazas judiciales', 'Ocho o más plazas judiciales', 'Doce o más plazas judiciales']::text[], 2, 'El artículo 84.3 exige, entre otras circunstancias, «Que en la Sección de que se trate existan ocho o más plazas judiciales».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
