insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-021', (select id from leyes where slug = 'lo-6-1985'), '99', '¿Dónde habrá un juez o una jueza de paz?', array['En cada partido judicial', 'En cada municipio que no sea capital de provincia', 'En cada capital de partido judicial', 'En cada municipio donde no exista Tribunal de Instancia']::text[], 3, 'El artículo 99 dice: «En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
