insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-028', (select id from leyes where slug = 'lo-6-1985'), '601.2', 'La Comisión Permanente del CGPJ está compuesta por:', array['El Presidente y cinco Vocales', 'El Presidente y nueve Vocales', 'El Presidente y cuatro Vocales', 'El Presidente y siete Vocales']::text[], 3, 'El artículo 601.2 dice que estará compuesta por el Presidente, «que la presidirá, y otros siete Vocales: cuatro de los nombrados por el turno judicial y tres de los designados por el turno de juristas de reconocida competencia».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
