insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-029', (select id from leyes where slug = 'lo-6-1985'), '602.2', 'Los acuerdos de la Comisión Permanente del CGPJ son recurribles:', array['En alzada ante el Pleno', 'En reposición ante la propia Comisión', 'En alzada ante el Presidente del CGPJ', 'Solo ante la Sala Tercera del Tribunal Supremo']::text[], 0, 'El artículo 602.2 dice: «Los acuerdos de la Comisión Permanente son recurribles en alzada ante el Pleno».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
