insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-004', (select id from leyes where slug = 'ley-47-2003'), '34.1.b', 'Al ejercicio presupuestario se imputan las obligaciones económicas reconocidas, por gastos realizados dentro del ejercicio, hasta:', array['El fin del mes de noviembre', 'El 31 de enero del año siguiente', 'El 31 de marzo del año siguiente', 'El fin del mes de diciembre']::text[], 3, 'El artículo 34.1.b) imputa al ejercicio «las obligaciones económicas reconocidas hasta el fin del mes de diciembre, siempre que correspondan a adquisiciones, obras, servicios, prestaciones o, en general, gastos realizados dentro del ejercicio».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
