insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-006', (select id from leyes where slug = 'ley-47-2003'), '36.2', 'En la elaboración de los Presupuestos, las propuestas de presupuesto de gastos se acompañarán, para cada programa, de:', array['Su memoria de objetivos anuales fijados', 'Un informe del Consejo de Estado', 'El estado consolidado de ingresos', 'Un informe de impacto de género']::text[], 0, 'El artículo 36.2, norma tercera, dispone que «Las propuestas de presupuesto de gastos se acompañarán, para cada programa, de su correspondiente memoria de objetivos anuales fijados».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
