insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-007', (select id from leyes where slug = 'ley-47-2003'), '37.1', 'El proyecto de Ley de Presupuestos Generales del Estado será remitido a las Cortes Generales antes del:', array['1 de septiembre del año anterior al que se refiera', '15 de octubre del año anterior al que se refiera', '1 de noviembre del año anterior al que se refiera', '1 de octubre del año anterior al que se refiera']::text[], 3, 'El artículo 37.1 establece que el proyecto «será remitido a las Cortes Generales antes del día 1 de octubre del año anterior al que se refiera».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
