insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-008', (select id from leyes where slug = 'ley-47-2003'), '37.2.g', 'Junto a la liquidación de los presupuestos del año anterior, al proyecto de Ley de Presupuestos se acompaña:', array['La Cuenta General del Estado del ejercicio corriente', 'Un avance de la liquidación del ejercicio corriente', 'El escenario de ingresos de los tres ejercicios siguientes', 'Un avance de la liquidación de los dos ejercicios anteriores']::text[], 1, 'Entre la documentación complementaria, el artículo 37.2.g) incluye «La liquidación de los presupuestos del año anterior y un avance de la liquidación del ejercicio corriente».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgp-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 15 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-009', (select id from leyes where slug = 'ley-47-2003'), '38.2', 'La prórroga de los Presupuestos Generales del Estado no afectará a los créditos para gastos correspondientes a:', array['Gastos de personal de la Administración General del Estado', 'Programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan', 'Intereses y amortización de la Deuda Pública', 'Pensiones de Clases Pasivas del Estado']::text[], 1, 'El artículo 38.2 dispone que «La prórroga no afectará a los créditos para gastos correspondientes a programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan o para obligaciones que se extingan en el mismo».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgp-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 15 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-010', (select id from leyes where slug = 'ley-47-2003'), '38.3', 'En caso de prórroga, la estructura orgánica del presupuesto prorrogado:', array['Se mantendrá sin cambios hasta la publicación de los nuevos presupuestos', 'Se adaptará a la nueva organización, con el aumento de cuantía que sea preciso', 'Se adaptará, sin alteración de la cuantía total, a la organización administrativa en vigor', 'Solo podrá adaptarse mediante ley aprobada por las Cortes Generales']::text[], 2, 'El artículo 38.3 establece que «La estructura orgánica del presupuesto prorrogado se adaptará, sin alteración de la cuantía total, a la organización administrativa en vigor en el ejercicio en que el presupuesto deba ejecutarse».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
