insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-021', (select id from leyes where slug = 'ley-47-2003'), '54.1', 'Excepcionalmente tienen la condición de ampliables, entre otros, los créditos destinados al pago de:', array['Subvenciones nominativas', 'Pensiones de Clases Pasivas del Estado', 'Inversiones reales de los ministerios', 'Gastos corrientes en bienes y servicios']::text[], 1, 'El artículo 54.1 dispone que «Excepcionalmente tendrán la condición de ampliables los créditos destinados al pago de pensiones de Clases Pasivas del Estado».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
