insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-022', (select id from leyes where slug = 'ley-47-2003'), '55.1', 'Procede tramitar un crédito extraordinario o suplementario cuando el gasto no puede demorarse al ejercicio siguiente y el crédito:', array['Existe y es suficiente, pero está en otra sección', 'Es insuficiente, pero tiene carácter ampliable', 'Es suficiente, aunque el gasto sea urgente', 'No existe o es insuficiente y no ampliable']::text[], 3, 'El artículo 55.1 exige que el gasto no pueda demorarse y que «no exista crédito adecuado o sea insuficiente y no ampliable el consignado».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
