insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-023', (select id from leyes where slug = 'ley-47-2003'), '55.3', 'El Consejo de Ministros autoriza los créditos extraordinarios y suplementos para obligaciones del ejercicio corriente cuando se financien con cargo:', array['A la baja en otros créditos', 'A la emisión de Deuda Pública', 'Al Fondo de Contingencia', 'Al remanente de tesorería del Estado']::text[], 2, 'El artículo 55.3 atribuye al Consejo de Ministros autorizar estos créditos para obligaciones del ejercicio corriente «cuando se financien con cargo al Fondo de Contingencia»; si se financian con baja en otros créditos, el artículo 55.2.b) exige proyecto de ley.', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
