insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-025', (select id from leyes where slug = 'ley-47-2003'), '60.1', 'Los anticipos de Tesorería tienen como límite máximo en cada ejercicio:', array['El dos por ciento de los créditos autorizados al Estado', 'El cinco por ciento de los créditos autorizados al Estado', 'El medio por ciento de los créditos autorizados al Estado', 'El uno por ciento de los créditos autorizados al Estado']::text[], 3, 'El artículo 60.1 permite conceder anticipos de Tesorería «con el límite máximo en cada ejercicio del uno por ciento de los créditos autorizados al Estado por la Ley de Presupuestos Generales del Estado».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
