insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-027', (select id from leyes where slug = 'ley-47-2003'), '73.2', '¿Qué fase inicia el procedimiento de ejecución del gasto sin implicar relaciones con terceros ajenos a la Hacienda Pública?', array['El compromiso de gasto', 'La aprobación del gasto', 'El reconocimiento de la obligación', 'La ordenación del pago']::text[], 1, 'El artículo 73.2 dispone: «La aprobación inicia el procedimiento de ejecución del gasto, sin que implique relaciones con terceros ajenos a la Hacienda Pública estatal o a la Seguridad Social».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
