insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-028', (select id from leyes where slug = 'ley-47-2003'), '73.4', 'El acto mediante el que se declara la existencia de un crédito exigible contra la Hacienda Pública estatal es:', array['El compromiso de gasto', 'La aprobación del gasto', 'El reconocimiento de la obligación', 'El pago material']::text[], 2, 'Según el artículo 73.4, «El reconocimiento de la obligación es el acto mediante el que se declara la existencia de un crédito exigible contra la Hacienda Pública estatal».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
