insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-001', (select id from leyes where slug = 'ley-7-1985'), '3.1', 'Según la Ley 7/1985, son Entidades Locales territoriales:', array['El Municipio, la Provincia y la Isla en los archipiélagos balear y canario', 'El Municipio, la Provincia y la Comarca', 'El Municipio, la Provincia y el Área Metropolitana', 'El Municipio, la Comarca y la Mancomunidad de Municipios']::text[], 0, 'El artículo 3.1 enumera como Entidades Locales territoriales el Municipio, la Provincia y «La Isla en los archipiélagos balear y canario».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
