insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-002', (select id from leyes where slug = 'ley-7-1985'), '3.2', '¿Cuál de estas entidades goza de la condición de Entidad Local sin ser entidad local territorial?', array['La Isla en el archipiélago canario', 'La Provincia', 'El Municipio', 'Las Áreas Metropolitanas']::text[], 3, 'El artículo 3.2 dice: «Gozan, asimismo, de la condición de Entidades Locales: […] b) Las Áreas Metropolitanas.»', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
