insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-003', (select id from leyes where slug = 'ley-7-1985'), '11.1', 'Según el artículo 11 de la Ley 7/1985, el Municipio es:', array['La entidad local intermedia entre la Provincia y la Comunidad', 'La entidad local básica de la organización territorial del Estado', 'La agrupación de núcleos de población con autonomía financiera', 'El órgano de gobierno y administración del término municipal']::text[], 1, 'El artículo 11.1 dice: «El Municipio es la entidad local básica de la organización territorial del Estado.»', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
