insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-004', (select id from leyes where slug = 'ley-7-1985'), '13.2', 'La creación de nuevos municipios solo puede hacerse sobre núcleos de población territorialmente diferenciados de al menos:', array['5.000 habitantes', '2.000 habitantes', '4.000 habitantes', '1.000 habitantes']::text[], 2, 'El artículo 13.2 exige «núcleos de población territorialmente diferenciados, de al menos 4.000 habitantes».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
