insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-005', (select id from leyes where slug = 'ley-7-1985'), '15', 'Quien viva en varios municipios deberá inscribirse en el Padrón:', array['De todos los municipios en los que resida', 'Del municipio en el que tenga su domicilio fiscal', 'Del municipio que elija libremente', 'Únicamente del que habite durante más tiempo al año']::text[], 3, 'El artículo 15 dice: «Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año.»', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
