insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-006', (select id from leyes where slug = 'ley-7-1985'), '15', 'La condición de vecino se adquiere:', array['En el mismo momento de la inscripción en el Padrón', 'Tras un año de residencia en el municipio', 'Cuando el Pleno acepte la solicitud de alta', 'A los seis meses de la inscripción en el Padrón']::text[], 0, 'El artículo 15 dice: «La condición de vecino se adquiere en el mismo momento de su inscripción en el Padrón.»', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
