insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-007', (select id from leyes where slug = 'ley-7-1985'), '16.1', 'La inscripción en el Padrón de extranjeros no comunitarios sin autorización de residencia de larga duración debe renovarse:', array['Cada año', 'Cada dos años', 'Cada cinco años', 'Cada tres años']::text[], 1, 'El artículo 16.1 dice que la inscripción «deberá ser objeto de renovación periódica cada dos años cuando se trate de la inscripción de extranjeros sin autorización de residencia de larga duración […]».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
