insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-008', (select id from leyes where slug = 'ley-7-1985'), '16.1', 'Las certificaciones de los datos del Padrón municipal tienen carácter de:', array['Documento privado con valor probatorio limitado', 'Documento público solo a efectos electorales', 'Documento público y fehaciente para todos los efectos administrativos', 'Mera prueba indiciaria del domicilio habitual']::text[], 2, 'El artículo 16.1 dice: «Las certificaciones que de dichos datos se expidan tendrán carácter de documento público y fehaciente para todos los efectos administrativos.»', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
