insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-010', (select id from leyes where slug = 'ley-7-1985'), '17.1', 'La formación, mantenimiento, revisión y custodia del Padrón municipal corresponde:', array['Al Ayuntamiento', 'Al Instituto Nacional de Estadística', 'A la Diputación Provincial', 'A la Comunidad Autónoma']::text[], 0, 'El artículo 17.1 dice: «La formación, mantenimiento, revisión y custodia del Padrón municipal corresponde al Ayuntamiento, de acuerdo con lo que establezca la legislación del Estado.»', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
