insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-011', (select id from leyes where slug = 'ley-7-1985'), '17.3', 'Las discrepancias en materia de empadronamiento entre Ayuntamientos las resuelve:', array['El Consejo de Empadronamiento, en Pleno', 'La persona que ejerza la Presidencia del Instituto Nacional de Estadística', 'La Diputación Provincial correspondiente', 'La Sección Provincial del Consejo de Empadronamiento']::text[], 1, 'El artículo 17.3 dice: «Corresponderá a la persona que ejerza la Presidencia del Instituto Nacional de Estadística la resolución de las discrepancias que, en materia de empadronamiento, surjan entre los Ayuntamientos […]».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
