insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-012', (select id from leyes where slug = 'ley-7-1985'), '18.1.e', 'Los vecinos tienen derecho a ser informados sobre los expedientes y la documentación municipal:', array['Previa petición razonada', 'Sin necesidad de petición previa', 'Solo si acreditan un interés legítimo', 'Previo pago de la tasa correspondiente']::text[], 0, 'El artículo 18.1.e) reconoce el derecho a «Ser informado, previa petición razonada, y dirigir solicitudes a la Administración municipal […]».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
