insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-013', (select id from leyes where slug = 'ley-7-1985'), '18.2', 'Según la Ley 7/1985, la inscripción de los extranjeros en el padrón municipal:', array['Acredita su residencia legal en España', 'No constituye prueba de su residencia legal en España', 'Les atribuye la condición de electores municipales', 'Sustituye a la autorización de residencia']::text[], 1, 'El artículo 18.2 dice: «La inscripción de los extranjeros en el padrón municipal no constituirá prueba de su residencia legal en España […]».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
