insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-014', (select id from leyes where slug = 'ley-7-1985'), '20.1.a', '¿Qué órganos existen en todos los ayuntamientos?', array['El Alcalde, el Pleno y la Junta de Gobierno Local', 'El Alcalde, el Pleno y la Comisión de Sugerencias', 'El Alcalde, los Tenientes de Alcalde y el Pleno', 'El Pleno, la Junta de Gobierno Local y los Concejales delegados']::text[], 2, 'El artículo 20.1.a) dice: «El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos.»', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
