insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-015', (select id from leyes where slug = 'ley-7-1985'), '20.1.b', 'La Junta de Gobierno Local existe en todo caso en los municipios con población superior a:', array['20.000 habitantes', '50.000 habitantes', '2.000 habitantes', '5.000 habitantes']::text[], 3, 'El artículo 20.1.b) dice: «La Junta de Gobierno Local existe en todos los municipios con población superior a 5.000 habitantes […]».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
