insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-016', (select id from leyes where slug = 'ley-7-1985'), '21.1.i', '¿A quién corresponde ejercer la jefatura de la Policía Municipal?', array['Al Pleno', 'Al Alcalde', 'A la Junta de Gobierno Local', 'Al primer Teniente de Alcalde']::text[], 1, 'Entre las atribuciones del Alcalde, el artículo 21.1.i) incluye «Ejercer la jefatura de la Policía Municipal».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
