insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-020', (select id from leyes where slug = 'ley-7-1985'), '23.3', 'Los Tenientes de Alcalde son designados libremente por el Alcalde de entre:', array['Los Concejales del grupo político con más votos', 'Los miembros de la Junta de Gobierno Local o, si no existe, los Concejales', 'Los vecinos inscritos en el Padrón municipal', 'Los miembros de la Comisión Especial de Cuentas']::text[], 1, 'El artículo 23.3 dice que son «libremente designados y removidos por éste de entre los miembros de la Junta de Gobierno Local y, donde ésta no exista, de entre los Concejales».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
