insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-021', (select id from leyes where slug = 'ley-7-1985'), '25.2', '¿Cuál de estas materias es competencia propia del Municipio según el artículo 25.2?', array['Inspección y sanción de establecimientos comerciales', 'Liquidación de tributos propios de la Comunidad Autónoma', 'Cementerios y actividades funerarias', 'Protección del medio natural']::text[], 2, 'El artículo 25.2.k) incluye entre las competencias propias «Cementerios y actividades funerarias».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
