insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-023', (select id from leyes where slug = 'ley-7-1985'), '26.1.b', 'La biblioteca pública es un servicio obligatorio en los Municipios con población superior a:', array['5.000 habitantes', '1.000 habitantes', '20.000 habitantes', '50.000 habitantes']::text[], 0, 'El artículo 26.1.b) dice: «En los Municipios con población superior a 5.000 habitantes, además: parque público, biblioteca pública y tratamiento de residuos.»', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
