insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-024', (select id from leyes where slug = 'ley-7-1985'), '26.1.d', 'El transporte colectivo urbano de viajeros es obligatorio en los Municipios con población superior a:', array['20.000 habitantes', '50.000 habitantes', '75.000 habitantes', '100.000 habitantes']::text[], 1, 'El artículo 26.1.d) dice: «En los Municipios con población superior a 50.000 habitantes, además: transporte colectivo urbano de viajeros y medio ambiente urbano.»', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
