insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-025', (select id from leyes where slug = 'ley-7-1985'), '27.1', 'La duración de la delegación de competencias del Estado o de las Comunidades Autónomas en los Municipios no podrá ser inferior a:', array['Dos años', 'Cuatro años', 'Cinco años', 'Diez años']::text[], 2, 'El artículo 27.1 dice que la delegación debe determinar su duración, «que no podrá ser inferior a cinco años».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
