insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-026', (select id from leyes where slug = 'ley-7-1985'), '32.1', '¿Qué órganos existen en todas las Diputaciones?', array['El Presidente, el Pleno y la Comisión Especial de Cuentas', 'El Presidente, el Pleno y la Comisión de Sugerencias', 'El Presidente, la Junta de Gobierno y el Consejo Provincial', 'El Presidente, los Vicepresidentes, la Junta de Gobierno y el Pleno']::text[], 3, 'El artículo 32.1 dice: «El Presidente, los Vicepresidentes, la Junta de Gobierno y el Pleno existen en todas las Diputaciones.»', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
