insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-027', (select id from leyes where slug = 'ley-7-1985'), '36.1.b', 'La Diputación garantiza la prestación de los servicios de secretaría e intervención en los municipios de menos de:', array['1.000 habitantes', '5.000 habitantes', '2.000 habitantes', '20.000 habitantes']::text[], 0, 'El artículo 36.1.b) dice: «En todo caso garantizará en los municipios de menos de 1.000 habitantes la prestación de los servicios de secretaría e intervención.»', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
