insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-028', (select id from leyes where slug = 'ley-7-1985'), '36.2.a', '¿Con qué periodicidad aprueba la Diputación el plan provincial de cooperación a las obras y servicios de competencia municipal?', array['Cada dos años', 'Anualmente', 'Cada cuatro años, al inicio del mandato', 'Cada cinco años']::text[], 1, 'El artículo 36.2.a) dice que la Diputación «Aprueba anualmente un plan provincial de cooperación a las obras y servicios de competencia municipal».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
