insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-029', (select id from leyes where slug = 'ley-7-1985'), '121.1.a', 'El régimen de los municipios de gran población se aplica, sin más requisitos, a los municipios cuya población supere:', array['250.000 habitantes', '175.000 habitantes', '75.000 habitantes', '500.000 habitantes']::text[], 0, 'El artículo 121.1.a) lo aplica «A los municipios cuya población supere los 250.000 habitantes.»', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
