insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-001', (select id from leyes where slug = 'ley-39-2015'), '16.1', 'Según la Ley 39/2015, cada Administración dispondrá de un:', array['Registro Central de Entrada y Salida', 'Registro Electrónico General', 'Archivo Electrónico de Documentos', 'Registro Único de Expedientes']::text[], 1, 'El artículo 16.1 dispone: «Cada Administración dispondrá de un Registro Electrónico General, en el que se hará el correspondiente asiento de todo documento que sea presentado o que se reciba en cualquier órgano administrativo […]».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
