insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-002', (select id from leyes where slug = 'ley-39-2015'), '16.1', 'Las disposiciones de creación de los registros electrónicos se publicarán en:', array['El diario oficial correspondiente', 'El Boletín Oficial del Estado, en todo caso', 'El Tablón Edictal Único', 'Solo la sede electrónica de acceso']::text[], 0, 'Según el artículo 16.1, «Las disposiciones de creación de los registros electrónicos se publicarán en el diario oficial correspondiente y su texto íntegro deberá estar disponible para consulta en la sede electrónica de acceso al registro».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
