insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-003', (select id from leyes where slug = 'ley-39-2015'), '16.1', 'Las disposiciones de creación de registros electrónicos especificarán, en todo caso:', array['El horario de las oficinas de asistencia y la dirección de cada una', 'Los funcionarios habilitados para expedir copias auténticas', 'Los trámites que pueden iniciarse y su plazo máximo de resolución', 'El órgano responsable de su gestión, la fecha y hora oficial y los días inhábiles']::text[], 3, 'El artículo 16.1 establece: «En todo caso, las disposiciones de creación de registros electrónicos especificarán el órgano o unidad responsable de su gestión, así como la fecha y hora oficial y los días declarados como inhábiles».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
