insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-008', (select id from leyes where slug = 'ley-39-2015'), '16.4.c', 'Los documentos dirigidos a las Administraciones Públicas podrán presentarse, entre otros lugares, en:', array['Las notarías, en la forma que reglamentariamente se establezca', 'Las representaciones diplomáticas u oficinas consulares de España en el extranjero', 'Las oficinas de las entidades bancarias colaboradoras', 'Los registros de la propiedad y mercantiles']::text[], 1, 'Entre los lugares de presentación, el artículo 16.4 incluye: «En las representaciones diplomáticas u oficinas consulares de España en el extranjero».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'reg-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 19 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-009', (select id from leyes where slug = 'ley-39-2015'), '16.5', 'Los documentos presentados de manera presencial deberán ser digitalizados por:', array['El órgano destinatario, al recibirlos en papel', 'El propio interesado, antes de presentarlos', 'La oficina de asistencia en materia de registros donde se presentaron', 'El archivo electrónico único de cada Administración']::text[], 2, 'El artículo 16.5 dispone que deberán ser digitalizados «por la oficina de asistencia en materia de registros en la que hayan sido presentados para su incorporación al expediente administrativo electrónico».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'reg-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 19 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-010', (select id from leyes where slug = 'ley-39-2015'), '16.5', 'Digitalizados los documentos presentados en persona, como regla general, los originales:', array['Se devuelven al interesado', 'Se destruyen de forma inmediata', 'Se remiten al archivo del órgano destinatario', 'Se custodian en la oficina durante cuatro años']::text[], 0, 'El artículo 16.5 indica que se digitalizan para su incorporación al expediente, «devolviéndose los originales al interesado, sin perjuicio de aquellos supuestos en que la norma determine la custodia por la Administración de los documentos presentados […]».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
