insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-014', (select id from leyes where slug = 'ley-39-2015'), '26.1', 'Según la Ley 39/2015, son documentos públicos administrativos:', array['Los válidamente emitidos por los órganos de las Administraciones Públicas', 'Los presentados por los interesados en cualquier registro público', 'Los que constan en un archivo público, sea cual sea su origen', 'Los autorizados por notario o por funcionario habilitado']::text[], 0, 'El artículo 26.1 dispone: «Se entiende por documentos públicos administrativos los válidamente emitidos por los órganos de las Administraciones Públicas».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'reg-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 19 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-015', (select id from leyes where slug = 'ley-39-2015'), '26.2', '¿Cuál de estos NO es un requisito de validez de los documentos electrónicos administrativos?', array['Incorporar una referencia temporal del momento de su emisión', 'Haber sido notificados al interesado por comparecencia en la sede', 'Incorporar los metadatos mínimos exigidos', 'Disponer de datos de identificación que permitan su individualización']::text[], 1, 'El artículo 26.2 exige, entre otros requisitos, «Incorporar una referencia temporal del momento en que han sido emitidos» e «Incorporar los metadatos mínimos exigidos». La notificación no figura entre ellos.', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
