insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-018', (select id from leyes where slug = 'ley-39-2015'), '27.1', 'En el registro de funcionarios habilitados para expedir copias auténticas constarán, al menos, los que presten servicios en:', array['Las unidades de archivo central de cada departamento', 'Las secretarías generales técnicas', 'Las oficinas de asistencia en materia de registros', 'Las unidades de información y atención al ciudadano']::text[], 2, 'Según el artículo 27.1, «En este registro o sistema equivalente constarán, al menos, los funcionarios que presten servicios en las oficinas de asistencia en materia de registros».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'reg-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 19 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-019', (select id from leyes where slug = 'ley-39-2015'), '27.2', 'Las copias auténticas tienen, respecto de los documentos originales:', array['Validez, pero solo eficacia probatoria', 'La misma validez y eficacia', 'Menor eficacia, salvo que se cotejen', 'Eficacia solo dentro del procedimiento']::text[], 1, 'El artículo 27.2 dispone: «Las copias auténticas tendrán la misma validez y eficacia que los documentos originales».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
