insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-020', (select id from leyes where slug = 'ley-39-2015'), '27.4', 'Solicitada la expedición de una copia auténtica de un documento público administrativo, deberá expedirse en el plazo de:', array['Diez días', 'Veinte días', 'Un mes', 'Quince días']::text[], 3, 'Según el artículo 27.4, debe expedirse «en el plazo de quince días a contar desde la recepción de la solicitud en el registro electrónico de la Administración u Organismo competente».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
