insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-003', (select id from leyes where slug = 'rd-203-2021'), '6.2', 'En el ámbito estatal, la dirección electrónica de un nuevo portal de internet debe incluir el nombre de dominio de segundo nivel:', array['.es', '.gob.es', '.gov.es', '.age.es']::text[], 1, 'El artículo 6.2 exige la identificación de su dirección electrónica, «que deberá incluir el nombre de dominio de segundo nivel [...] .gob.es».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
