insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-004', (select id from leyes where slug = 'rd-203-2021'), '7.4', 'La Dirección Electrónica Habilitada única está alojada en:', array['La Carpeta Ciudadana de cada interesado', 'La sede electrónica asociada de cada ministerio', 'El Registro Electrónico General del Estado', 'La sede electrónica del PAGe de la Administración General del Estado']::text[], 3, 'El artículo 7.4 señala que en la sede electrónica del PAGe de la Administración General del Estado «está alojada la Dirección Electrónica Habilitada única».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
