insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-005', (select id from leyes where slug = 'rd-203-2021'), '8.1.b', 'Además del interesado y sus representantes legales, puede acceder a su Carpeta Ciudadana quien ostente:', array['Un poder para un trámite concreto otorgado ante notario', 'Un poder especial inscrito en el registro particular de un organismo', 'Un poder general otorgado por el interesado e inscrito en el Registro Electrónico de Apoderamientos', 'Una autorización verbal dada en una oficina de registro']::text[], 2, 'Según el artículo 8.1.b), puede acceder «quien ostente un poder general previsto en el artículo 6.4.a) de la Ley 39/2015, de 1 de octubre, otorgado por el interesado e inscrito en el Registro Electrónico de Apoderamientos».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rme-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 20 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-006', (select id from leyes where slug = 'rd-203-2021'), '10.2', 'El acto de creación de la sede electrónica de una entidad local se publica en:', array['El boletín oficial de la provincia a la que pertenezca la entidad', 'El Boletín Oficial del Estado', 'El boletín oficial de la comunidad autónoma', 'El tablón de edictos de la propia entidad']::text[], 0, 'El artículo 10.2 indica que «en el caso de las entidades locales, el boletín oficial será el de la provincia al que pertenezca la entidad».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
