insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-012', (select id from leyes where slug = 'rd-203-2021'), '27.3', 'Los certificados cualificados de sello electrónico para identificar a una persona jurídica deben contener, como mínimo:', array['Su denominación, NIF y domicilio social', 'Su NIF y el nombre de su administrador', 'Su denominación y su Número de Identificación Fiscal', 'Su denominación y su número de inscripción registral']::text[], 2, 'El artículo 27.3 exige que estos certificados contengan, «como mínimo, su denominación y su Número de Identificación Fiscal».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
