insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-013', (select id from leyes where slug = 'rd-203-2021'), '30.1', 'El formulario de consentimiento expreso para la firma por funcionario habilitado está disponible en:', array['La oficina de asistencia en materia de registros más próxima', 'La Carpeta Ciudadana del propio interesado', 'La sede electrónica del órgano que tramita', 'El Punto de Acceso General Electrónico de la respectiva Administración']::text[], 3, 'El artículo 30.1 indica que el funcionario entregará copia del documento de consentimiento expreso, «cuyo formulario estará disponible en el Punto de Acceso General Electrónico de la respectiva Administración».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
