insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-014', (select id from leyes where slug = 'rd-203-2021'), '32.4', 'Si se actúa en nombre de una persona jurídica con certificado cualificado de representante, el poder de representación abarca:', array['Solo las actuaciones ante la Administración General del Estado', 'Cualquier actuación ante cualquier Administración Pública', 'Solo los trámites especificados en el propio certificado', 'Solo las actuaciones ante la Administración que lo autorizó']::text[], 1, 'El artículo 32.4 dispone que se entiende «que el poder de representación abarca cualquier actuación ante cualquier Administración Pública».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
