insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-016', (select id from leyes where slug = 'rd-203-2021'), '43.2', 'Obligado electrónico, procedimiento de oficio y sin datos de contacto para el aviso: ¿cómo se hace la primera notificación?', array['En papel, advirtiendo que las siguientes serán electrónicas', 'Por comparecencia en la sede electrónica del emisor', 'A través de la Dirección Electrónica Habilitada única', 'Mediante anuncio en el Boletín Oficial del Estado']::text[], 0, 'El artículo 43.2 establece que «la primera notificación que efectúe la Administración, organismo o entidad se realizará en papel» advirtiendo al interesado de que las sucesivas se practicarán en forma electrónica.', 3, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
