insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-017', (select id from leyes where slug = 'rd-203-2021'), '37.3.b', 'Además de los documentos normalizados, los registros electrónicos admitirán cualquier solicitud, escrito o comunicación dirigido a:', array['Cualquier Administración Pública', 'La Administración titular del registro', 'La Administración General del Estado', 'Los órganos del mismo departamento']::text[], 0, 'El artículo 37.3.b) dispone que los registros admitirán «cualquier solicitud, escrito o comunicación distinta de los mencionados en el párrafo anterior dirigido a cualquier Administración Pública».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
