insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-020', (select id from leyes where slug = 'rd-203-2021'), '39.4', 'Si el tamaño de los documentos registrados excede la capacidad del SIR, su remisión podrá sustituirse por:', array['Su envío en papel por correo certificado al órgano destinatario', 'Su puesta a disposición, depositados antes en un repositorio de intercambio de ficheros', 'Su entrega presencial por el interesado en el órgano destinatario', 'Su remisión fraccionada por correo electrónico al órgano destinatario']::text[], 1, 'El artículo 39.4 dispone que su remisión «podrá sustituirse por la puesta a disposición de los documentos, previamente depositados en un repositorio de intercambio de ficheros».', 3, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
