insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-021', (select id from leyes where slug = 'rd-203-2021'), '40.1', 'Las oficinas de asistencia en materia de registros tienen naturaleza de:', array['Unidad administrativa', 'Organismo autónomo', 'Órgano administrativo', 'Servicio común']::text[], 2, 'El artículo 40.1 afirma que estas oficinas «tienen naturaleza de órgano administrativo de acuerdo con lo dispuesto en el artículo 5 de la Ley 40/2015».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
