insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-022', (select id from leyes where slug = 'rd-203-2021'), '40.3.i', '¿Cuál de estas es una función de las oficinas de asistencia en materia de registros?', array['Iniciar la tramitación del apoderamiento presencial apud acta', 'Realizar el bastanteo de los poderes notariales', 'Resolver las reclamaciones sobre el registro', 'Autorizar los sistemas de clave concertada']::text[], 0, 'El artículo 40.3.i) atribuye a estas oficinas «la iniciación de la tramitación del apoderamiento presencial apud acta en los términos previstos en el artículo 6 de la Ley 39/2015».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
