insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-023', (select id from leyes where slug = 'rd-203-2021'), '46.2', 'Si el órgano debe facilitar al interesado un ejemplar de un documento administrativo electrónico, puede sustituirlo por:', array['Una copia en papel compulsada por el funcionario', 'La entrega de los datos necesarios para su acceso por medios electrónicos', 'Un extracto publicado en la sede electrónica', 'Una certificación del secretario del órgano']::text[], 1, 'El artículo 46.2 permite que dicho documento se sustituya «por la entrega de los datos necesarios para su acceso por medios electrónicos adecuados».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
