insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-025', (select id from leyes where slug = 'rd-203-2021'), '49', 'Cuando el interesado presenta en papel una copia de un documento, su digitalización genera una copia electrónica que tiene:', array['El valor de copia auténtica del original', 'El valor de documento original electrónico', 'Un valor meramente informativo', 'El mismo valor que la copia presentada en papel']::text[], 3, 'El artículo 49 dice que la digitalización «generará una copia electrónica que tendrá el mismo valor que la copia presentada en papel».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
