insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-001', (select id from leyes where slug = 'ley-19-2013'), '3.b', 'Están sujetas a publicidad activa las entidades privadas que perciban en un año ayudas o subvenciones públicas por una cuantía superior a:', array['50.000 euros', '100.000 euros', '150.000 euros', '60.000 euros']::text[], 1, 'El artículo 3.b) incluye a «las entidades privadas que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
