insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-002', (select id from leyes where slug = 'ley-19-2013'), '3.b', 'Una entidad privada queda sujeta a publicidad activa si las ayudas públicas suponen, al menos, este porcentaje de sus ingresos anuales (mínimo 5.000 euros):', array['El 25 %', 'El 50 %', 'El 30 %', 'El 40 %']::text[], 3, 'Según el artículo 3.b), también cuando «al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros».', 3, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
