insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-004', (select id from leyes where slug = 'ley-19-2013'), '2.2', 'A efectos del título I de la Ley 19/2013, se entiende por Administraciones Públicas los organismos y entidades incluidos en:', array['Las letras a) a c) del artículo 2.1', 'Las letras a) a f) del artículo 2.1', 'Las letras a) a d) del artículo 2.1', 'Todas las letras del artículo 2.1']::text[], 2, 'El artículo 2.2 dispone que «se entiende por Administraciones Públicas los organismos y entidades incluidos en las letras a) a d) del apartado anterior».', 3, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
