insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-005', (select id from leyes where slug = 'ley-19-2013'), '36.2.f', '¿Cuál de los siguientes forma parte de la Comisión de Transparencia y Buen Gobierno?', array['Un representante del Consejo de Estado', 'Un representante del Consejo General del Poder Judicial', 'Un representante de la Agencia Española de Protección de Datos', 'Un representante del Tribunal Constitucional']::text[], 2, 'Según el artículo 36.2, la Comisión está compuesta, entre otros, por «f) Un representante de la Agencia Española de Protección de Datos».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
