insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-006', (select id from leyes where slug = 'ley-19-2013'), '8.1.a', 'Según la Ley 19/2013, la publicación de la información relativa a los contratos menores podrá realizarse:', array['Trimestralmente', 'Semestralmente', 'Mensualmente', 'Anualmente']::text[], 0, 'El artículo 8.1.a) establece que «la publicación de la información relativa a los contratos menores podrá realizarse trimestralmente».', 3, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
