insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-007', (select id from leyes where slug = 'ley-19-2013'), '9.3', 'El incumplimiento reiterado de las obligaciones de publicidad activa tendrá, a efectos disciplinarios, la consideración de:', array['Infracción leve', 'Infracción muy grave', 'Falta de diligencia sin sanción', 'Infracción grave']::text[], 3, 'El artículo 9.3 dispone que ese incumplimiento reiterado «tendrá la consideración de infracción grave» a efectos del régimen disciplinario.', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-007', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-008', (select id from leyes where slug = 'ley-19-2013'), '9.1', '¿Quién controla el cumplimiento de las obligaciones de publicidad activa por la Administración General del Estado?', array['El Defensor del Pueblo', 'El Consejo de Transparencia y Buen Gobierno', 'El Tribunal de Cuentas', 'La Agencia Española de Protección de Datos']::text[], 1, 'El artículo 9.1 señala que ese cumplimiento «será objeto de control por parte del Consejo de Transparencia y Buen Gobierno».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-009', (select id from leyes where slug = 'ley-19-2013'), '12', '¿Quién tiene derecho a acceder a la información pública según la Ley 19/2013?', array['Todas las personas', 'Solo los ciudadanos españoles', 'Solo quienes acrediten interés legítimo', 'Solo los ciudadanos de la Unión Europea']::text[], 0, 'El artículo 12 dispone: «Todas las personas tienen derecho a acceder a la información pública».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-010', (select id from leyes where slug = 'ley-19-2013'), '13', 'Para ser información pública, los contenidos o documentos en poder de los sujetos obligados deben haber sido:', array['Elaborados por ellos y publicados en un diario oficial', 'Aprobados de forma definitiva por el órgano competente', 'Elaborados o adquiridos en el ejercicio de sus funciones', 'Registrados en soporte electrónico']::text[], 2, 'El artículo 13 define la información pública como los contenidos o documentos, «cualquiera que sea su formato o soporte», que obren en poder de los sujetos «y que hayan sido elaborados o adquiridos en el ejercicio de sus funciones».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-011', (select id from leyes where slug = 'ley-19-2013'), '14.1.l', '¿Cuál de los siguientes es un límite al derecho de acceso previsto en el artículo 14 de la Ley 19/2013?', array['La imagen institucional del órgano', 'La protección del medio ambiente', 'La carga de trabajo de la unidad', 'La organización interna del servicio']::text[], 1, 'Entre los límites del artículo 14.1, el acceso podrá limitarse cuando suponga un perjuicio para «l) La protección del medio ambiente».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-012', (select id from leyes where slug = 'ley-19-2013'), '15.1', 'Si la información contiene datos que revelen la ideología o la religión del afectado, el acceso solo podrá autorizarse, en general, con:', array['Su consentimiento tácito', 'Informe favorable del Consejo de Transparencia', 'Una ponderación razonada del interés público', 'Su consentimiento expreso y por escrito']::text[], 3, 'El artículo 15.1 exige en esos casos que «se contase con el consentimiento expreso y por escrito del afectado», salvo que los hubiese hecho manifiestamente públicos antes.', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-013', (select id from leyes where slug = 'ley-19-2013'), '16', 'Cuando se concede acceso parcial por aplicar un límite, ¿qué debe hacerse?', array['Pedir autorización previa al Consejo de Transparencia', 'Suspender el plazo para resolver hasta un mes más', 'Comunicarlo al Defensor del Pueblo', 'Indicar al solicitante que parte de la información ha sido omitida']::text[], 3, 'Según el artículo 16, se concederá el acceso parcial y en ese caso «deberá indicarse al solicitante que parte de la información ha sido omitida».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-014', (select id from leyes where slug = 'ley-19-2013'), '17.3', 'Sobre la motivación de la solicitud de acceso a la información pública:', array['Es obligatoria si se piden datos personales', 'El solicitante no está obligado a motivarla', 'Su ausencia es causa de inadmisión', 'Debe acreditar un interés directo']::text[], 1, 'El artículo 17.3 dispone que «el solicitante no está obligado a motivar su solicitud de acceso a la información» y que su ausencia «no será por si sola causa de rechazo de la solicitud».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-015', (select id from leyes where slug = 'ley-19-2013'), '17.2.c', 'La solicitud de acceso debe presentarse por un medio que permita tener constancia, entre otros datos, de:', array['Los motivos de la solicitud', 'La firma electrónica cualificada del solicitante', 'Una dirección de contacto, preferentemente electrónica', 'El interés legítimo del solicitante']::text[], 2, 'El artículo 17.2 exige constancia, entre otros datos, de «c) Una dirección de contacto, preferentemente electrónica, a efectos de comunicaciones».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
