insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-020', (select id from leyes where slug = 'ley-19-2013'), '20.1', '¿Cuál es el plazo máximo para notificar la resolución sobre una solicitud de acceso a la información pública?', array['Tres meses desde la presentación', 'Quince días desde la recepción', 'Dos meses desde la presentación', 'Un mes desde la recepción por el órgano competente']::text[], 3, 'El artículo 20.1 fija «el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
