insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-025', (select id from leyes where slug = 'ley-19-2013'), '24.2', '¿En qué plazo se interpone la reclamación ante el Consejo de Transparencia y Buen Gobierno?', array['Diez días', 'Un mes', 'Dos meses', 'Tres meses']::text[], 1, 'El artículo 24.2 dispone que la reclamación «se interpondrá en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'tra-025', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-026', (select id from leyes where slug = 'ley-19-2013'), '24.4', 'Si el Consejo de Transparencia no resuelve una reclamación en plazo, ¿qué ocurre?', array['Se entiende estimada a los tres meses', 'Se entiende desestimada al mes', 'Se entiende desestimada a los tres meses', 'Se entiende estimada a los dos meses']::text[], 2, 'Según el artículo 24.4, «el plazo máximo para resolver y notificar la resolución será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
