insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-027', (select id from leyes where slug = 'ley-19-2013'), '23.2', 'Contra las resoluciones de acceso dictadas por el Congreso de los Diputados o el Tribunal de Cuentas, ¿qué cabe?', array['Solo recurso contencioso-administrativo', 'Reclamación ante el Consejo de Transparencia', 'Recurso de alzada ante su Presidente', 'Recurso potestativo de reposición']::text[], 0, 'El artículo 23.2 dispone que «contra las resoluciones dictadas por los órganos previstos en el artículo 2.1.f) sólo cabrá la interposición de recurso contencioso-administrativo».', 3, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
