insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-028', (select id from leyes where slug = 'ley-19-2013'), '30.4', 'Los sancionados por una infracción muy grave del título II no podrán ser nombrados alto cargo durante un periodo de entre:', array['Tres y cinco años', 'Dos y cinco años', 'Diez y quince años', 'Cinco y diez años']::text[], 3, 'El artículo 30.4 dispone que no podrán ser nombrados alto cargo o asimilado «durante un periodo de entre cinco y diez años».', 3, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
