insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-029', (select id from leyes where slug = 'ley-19-2013'), '32.1', 'En el título de buen gobierno, ¿en qué plazo prescriben las infracciones graves?', array['Un año', 'Dos años', 'Tres años', 'Cinco años']::text[], 2, 'El artículo 32.1 fija la prescripción en «cinco años para las infracciones muy graves, tres años para las graves y un año para las leves».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
