insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-030', (select id from leyes where slug = 'ley-19-2013'), '37.1', 'El Presidente del Consejo de Transparencia y Buen Gobierno es nombrado por un período de:', array['Cinco años, no renovable', 'Cuatro años, renovable una vez', 'Seis años, no renovable', 'Cinco años, renovable una vez']::text[], 0, 'Según el artículo 37.1, el Presidente «será nombrado por un período no renovable de cinco años mediante Real Decreto».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
