insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-026', (select id from leyes where slug = 'trebep'), '52', '¿Cuál de los siguientes NO figura entre los principios del artículo 52 del TREBEP que inspiran el Código de Conducta?', array['Neutralidad', 'Ejemplaridad', 'Jerarquía', 'Austeridad']::text[], 2, 'El artículo 52 enumera, entre otros, «objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez». La jerarquía no figura entre ellos.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-026', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 14 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-027', (select id from leyes where slug = 'trebep'), '56.1.c', '¿Qué edad mínima se exige para participar en los procesos selectivos de acceso al empleo público?', array['Dieciocho años', 'Dieciséis años', 'Diecisiete años', 'Veintiún años']::text[], 1, 'El artículo 56.1.c) exige «Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-028', (select id from leyes where slug = 'trebep'), '57.2', 'Los descendientes de españoles y de nacionales de otros Estados de la UE pueden acceder al empleo público como funcionarios, cualquiera que sea su nacionalidad, si:', array['Son menores de veintiún años o mayores de dicha edad dependientes', 'Son menores de dieciocho años', 'Son menores de veinticinco años', 'Residen legalmente en España desde hace cinco años']::text[], 0, 'El artículo 57.2 extiende el acceso a los descendientes siempre que «sean menores de veintiún años o mayores de dicha edad dependientes».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-028', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-029', (select id from leyes where slug = 'trebep'), '57.4', 'Los extranjeros con residencia legal en España pueden acceder a las Administraciones Públicas:', array['Como funcionarios de carrera, en igualdad de condiciones', 'Solo como personal eventual', 'En ningún caso', 'Como personal laboral, en igualdad de condiciones que los españoles']::text[], 3, 'El artículo 57.4 dice que los extranjeros con residencia legal en España «podrán acceder a las Administraciones Públicas, como personal laboral, en igualdad de condiciones que los españoles».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
