insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-005', (select id from leyes where slug = 'trebep'), '59.1', 'Dentro de la reserva para personas con discapacidad, ¿qué parte de las plazas ofertadas se destina, al menos, a quienes acrediten discapacidad intelectual?', array['El uno por ciento', 'El dos por ciento', 'El tres por ciento', 'El cinco por ciento']::text[], 1, 'Según el artículo 59.1, la reserva se hará de modo que «al menos, el dos por ciento de las plazas ofertadas lo sea para ser cubiertas por personas que acrediten discapacidad intelectual».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
