insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-006', (select id from leyes where slug = 'trebep'), '60.3', 'La pertenencia a los órganos de selección será siempre:', array['En representación de las organizaciones sindicales', 'Por cuenta de la Administración convocante', 'En representación del cuerpo o escala convocado', 'A título individual']::text[], 3, 'El artículo 60.3 dispone que «La pertenencia a los órganos de selección será siempre a título individual, no pudiendo ostentarse ésta en representación o por cuenta de nadie».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
