insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-008', (select id from leyes where slug = 'trebep'), '61.3', 'En los procesos selectivos que incluyan valoración de méritos, la puntuación de esos méritos:', array['No podrá superar la mitad de la puntuación total', 'Determinará el orden de prelación de los aspirantes', 'Será proporcionada y no determinará por sí misma el resultado', 'Solo podrá servir para deshacer empates']::text[], 2, 'Según el artículo 61.3, la valoración de méritos tendrá «una puntuación proporcionada que no determinará, en ningún caso, por sí misma el resultado del proceso selectivo».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
