insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-011', (select id from leyes where slug = 'trebep'), '66', 'La pena firme de inhabilitación especial produce la pérdida de la condición de funcionario:', array['Respecto de todos los empleos o cargos que tuviere', 'Respecto de los empleos o cargos especificados en la sentencia', 'Solo durante el tiempo de cumplimiento de la pena', 'Únicamente si se impone como pena principal']::text[], 1, 'Según el artículo 66, la inhabilitación especial firme «produce la pérdida de la condición de funcionario respecto de aquellos empleos o cargos especificados en la sentencia».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
