insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-019', (select id from leyes where slug = 'trebep'), '18.2', 'Para la promoción interna, el funcionario debe tener una antigüedad mínima en el Subgrupo inferior de:', array['Dos años de servicio activo', 'Un año de servicio activo', 'Tres años de servicio activo', 'Cinco años de servicio activo']::text[], 0, 'El artículo 18.2 exige «tener una antigüedad de, al menos, dos años de servicio activo en el inferior Subgrupo».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
