insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-020', (select id from leyes where slug = 'trebep'), '16.3.a', 'La progresión de grado, categoría o escalón sin necesidad de cambiar de puesto de trabajo es:', array['La carrera vertical', 'La carrera horizontal', 'La promoción interna horizontal', 'La promoción interna vertical']::text[], 1, 'El artículo 16.3.a) define la «Carrera horizontal, que consiste en la progresión de grado, categoría, escalón u otros conceptos análogos, sin necesidad de cambiar de puesto de trabajo».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
