insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-021', (select id from leyes where slug = 'trebep'), '20.1', 'Según el TREBEP, el procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados es:', array['La carrera horizontal', 'La evaluación del desempeño', 'El concurso de méritos', 'La relación de puestos de trabajo']::text[], 1, 'El artículo 20.1 dispone: «La evaluación del desempeño es el procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
