insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-022', (select id from leyes where slug = 'trebep'), '79.1', '¿Cuál es el procedimiento normal de provisión de puestos de trabajo del personal funcionario de carrera?', array['El concurso', 'La libre designación', 'La comisión de servicios', 'La redistribución de efectivos']::text[], 0, 'Según el artículo 79.1, «El concurso, como procedimiento normal de provisión de puestos de trabajo, consistirá en la valoración de los méritos y capacidades».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
