insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-023', (select id from leyes where slug = 'trebep'), '80.4', 'Los titulares de puestos provistos por libre designación con convocatoria pública:', array['Solo pueden ser cesados por sanción disciplinaria', 'No pueden ser cesados en los dos primeros años', 'Solo pueden ser cesados previa evaluación del desempeño', 'Pueden ser cesados discrecionalmente']::text[], 3, 'El artículo 80.4 dispone que estos titulares «podrán ser cesados discrecionalmente».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
