insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-024', (select id from leyes where slug = 'trebep'), '87.1.b', 'Pasa a servicios especiales el funcionario autorizado a realizar una misión en organismos internacionales por un periodo determinado superior a:', array['Tres meses', 'Un año', 'Seis meses', 'Dos años']::text[], 2, 'El artículo 87.1.b) incluye a quienes «sean autorizados para realizar una misión por periodo determinado superior a seis meses en organismos internacionales».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
