insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-025', (select id from leyes where slug = 'trebep'), '89.4', 'En la excedencia por cuidado de familiares, el puesto de trabajo desempeñado se reserva, al menos, durante:', array['Un año', 'Tres años', 'Dieciocho meses', 'Dos años']::text[], 3, 'El artículo 89.4 dispone: «El puesto de trabajo desempeñado se reservará, al menos, durante dos años».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
