insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-026', (select id from leyes where slug = 'trebep'), '89.5', 'En la excedencia por razón de violencia de género, la funcionaria percibe las retribuciones íntegras durante:', array['Los seis primeros meses', 'Los dos primeros meses', 'El primer mes', 'Los tres primeros meses']::text[], 1, 'El artículo 89.5 establece: «Durante los dos primeros meses de esta excedencia la funcionaria tendrá derecho a percibir las retribuciones íntegras».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
