insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-027', (select id from leyes where slug = 'trebep'), '94.3', 'Si de la instrucción de un procedimiento disciplinario resultan indicios fundados de criminalidad:', array['Se archiva el procedimiento sin más trámite', 'Se continúa y se remite la resolución al juzgado', 'Se suspende su tramitación y se comunica al Ministerio Fiscal', 'Se impone de inmediato la suspensión firme de funciones']::text[], 2, 'El artículo 94.3 dispone que en ese caso «se suspenderá su tramitación poniéndolo en conocimiento del Ministerio Fiscal».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
