insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-028', (select id from leyes where slug = 'trebep'), '96.1.e', 'La sanción disciplinaria que consiste en la penalización a efectos de carrera, promoción o movilidad voluntaria es:', array['El demérito', 'El apercibimiento', 'El traslado forzoso', 'La suspensión firme de funciones']::text[], 0, 'El artículo 96.1.e) recoge el «Demérito, que consistirá en la penalización a efectos de carrera, promoción o movilidad voluntaria».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
