insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-029', (select id from leyes where slug = 'trebep'), '97.1', 'Las sanciones impuestas por faltas leves prescriben:', array['Al año', 'A los seis meses', 'A los dos años', 'A los tres meses']::text[], 0, 'El artículo 97.1 dispone que prescriben «las impuestas por faltas leves al año».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
