insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-030', (select id from leyes where slug = 'trebep'), '98.3', 'Salvo paralización imputable al interesado, la suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:', array['Tres meses', 'Un año', 'Seis meses', 'Dieciocho meses']::text[], 2, 'Según el artículo 98.3, «La suspensión provisional como medida cautelar en la tramitación de un expediente disciplinario no podrá exceder de 6 meses».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
