insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-001', (select id from leyes where slug = 'tue'), '2', '¿Cuál de estos figura entre los valores en que se fundamenta la Unión según el TUE?', array['El Estado de Derecho', 'La economía social de mercado', 'La estabilidad de los precios', 'La libre competencia']::text[], 0, 'El artículo 2 TUE dice: «La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos […]».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
