insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-003', (select id from leyes where slug = 'tue'), '13.1', '¿Cuál de estos NO es una institución de la Unión según el artículo 13 TUE?', array['El Tribunal de Cuentas', 'El Banco Central Europeo', 'El Comité de las Regiones', 'El Consejo Europeo']::text[], 2, 'El artículo 13.1 TUE enumera las instituciones, entre ellas «El Banco Central Europeo, El Tribunal de Cuentas». Según el 13.4, el Parlamento, el Consejo y la Comisión «estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
