insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-004', (select id from leyes where slug = 'tue'), '14.2', 'El número de miembros del Parlamento Europeo no excederá de:', array['Setecientos cincuenta, incluido el Presidente', 'Setecientos, más el Presidente', 'Setecientos cincuenta y uno, más el Presidente', 'Setecientos cincuenta, más el Presidente']::text[], 3, 'El artículo 14.2 TUE dice: «Su número no excederá de setecientos cincuenta, más el Presidente».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
