insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-005', (select id from leyes where slug = 'tue'), '14.2', '¿Cuál es el número mínimo de diputados al Parlamento Europeo por Estado miembro?', array['Cuatro', 'Cinco', 'Seis', 'Ocho']::text[], 2, 'El artículo 14.2 TUE establece que la representación será «decrecientemente proporcional, con un mínimo de seis diputados por Estado miembro».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
