insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-006', (select id from leyes where slug = 'tue'), '14.2', '¿Cuántos escaños, como máximo, pueden asignarse a un Estado miembro en el Parlamento Europeo?', array['Noventa y seis', 'Noventa y nueve', 'Ochenta y seis', 'Cien']::text[], 0, 'El artículo 14.2 TUE dice: «No se asignará a ningún Estado miembro más de noventa y seis escaños».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
