insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-007', (select id from leyes where slug = 'tue'), '14.3', 'Los diputados al Parlamento Europeo son elegidos para un mandato de:', array['Cuatro años', 'Seis años', 'Dos años y medio', 'Cinco años']::text[], 3, 'El artículo 14.3 TUE dice que los diputados serán elegidos por sufragio universal directo, libre y secreto, «para un mandato de cinco años».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
