insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-008', (select id from leyes where slug = 'tue'), '15.1', 'Según el TUE, el Consejo Europeo:', array['Ejercerá la función legislativa con el Parlamento', 'No ejercerá función legislativa alguna', 'Ejercerá la función presupuestaria con el Consejo', 'Elegirá al Presidente de la Comisión']::text[], 1, 'El artículo 15.1 TUE dice que el Consejo Europeo definirá las orientaciones y prioridades políticas generales y que «No ejercerá función legislativa alguna».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
