insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-009', (select id from leyes where slug = 'tue'), '15.2', '¿Quiénes componen el Consejo Europeo?', array['Los Jefes de Estado o de Gobierno, su Presidente y el Alto Representante', 'Los Jefes de Estado o de Gobierno, su Presidente y el Presidente de la Comisión', 'Los Jefes de Estado o de Gobierno y el Presidente del Parlamento Europeo', 'Un representante de rango ministerial de cada Estado y su Presidente']::text[], 1, 'El artículo 15.2 TUE dice: «El Consejo Europeo estará compuesto por los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión». El Alto Representante solo «Participará en sus trabajos».', 3, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
