insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-010', (select id from leyes where slug = 'tue'), '15.3', '¿Con qué frecuencia se reúne el Consejo Europeo, según el TUE?', array['Una vez por semestre', 'Una vez al mes', 'Tres veces al año', 'Dos veces por semestre']::text[], 3, 'El artículo 15.3 TUE dice: «El Consejo Europeo se reunirá dos veces por semestre por convocatoria de su Presidente».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
