insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-011', (select id from leyes where slug = 'tue'), '15.5', 'El Presidente del Consejo Europeo es elegido para un mandato de:', array['Dos años y medio, renovable una sola vez', 'Cinco años, renovable una sola vez', 'Seis meses, no renovable', 'Dos años y medio, no renovable']::text[], 0, 'El artículo 15.5 TUE dice que el Consejo Europeo elegirá a su Presidente por mayoría cualificada «para un mandato de dos años y medio, que podrá renovarse una sola vez».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
