insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-014', (select id from leyes where slug = 'tue'), '16.4', 'Según el artículo 16.4 TUE, una minoría de bloqueo en el Consejo estará compuesta por al menos:', array['Cuatro miembros del Consejo', 'Tres miembros del Consejo', 'Cinco miembros del Consejo', 'Quince miembros del Consejo']::text[], 0, 'El artículo 16.4 TUE dice: «Una minoría de bloqueo estará compuesta por al menos cuatro miembros del Consejo, a falta de lo cual la mayoría cualificada se considerará alcanzada».', 3, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
