insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-015', (select id from leyes where slug = 'tue'), '16.2', '¿Cómo está compuesto el Consejo?', array['Por los Jefes de Estado o de Gobierno de los Estados miembros', 'Por un representante de rango ministerial de cada Estado miembro', 'Por un representante de cada Estado nombrado por su Parlamento', 'Por los Representantes Permanentes de los Estados miembros']::text[], 1, 'El artículo 16.2 TUE dice: «El Consejo estará compuesto por un representante de cada Estado miembro, de rango ministerial […]».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
