insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-016', (select id from leyes where slug = 'tue'), '16.9', '¿Qué formación del Consejo no se preside mediante el sistema de rotación igual entre Estados?', array['La de Asuntos Generales', 'La de Asuntos Económicos y Financieros', 'La de Asuntos Exteriores', 'La de Justicia y Asuntos de Interior']::text[], 2, 'El artículo 16.9 TUE dice: «La presidencia de las formaciones del Consejo, con excepción de la de Asuntos Exteriores, será desempeñada por los representantes de los Estados miembros en el Consejo mediante un sistema de rotación igual […]».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
