insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-017', (select id from leyes where slug = 'tue'), '16.7', '¿Qué órgano se encarga de preparar los trabajos del Consejo?', array['El Consejo de Asuntos Exteriores', 'La Secretaría General de la Comisión', 'El Comité de Representantes Permanentes', 'El Comité Económico y Social']::text[], 2, 'El artículo 16.7 TUE dice: «Un Comité de Representantes Permanentes de los Gobiernos de los Estados miembros se encargará de preparar los trabajos del Consejo».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
