insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-018', (select id from leyes where slug = 'tue'), '17.3', '¿Cuál es la duración del mandato de la Comisión?', array['Cuatro años', 'Seis años', 'Dos años y medio', 'Cinco años']::text[], 3, 'El artículo 17.3 TUE dice: «El mandato de la Comisión será de cinco años».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
