insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-019', (select id from leyes where slug = 'tue'), '17.5', 'Desde el 1 de noviembre de 2014, salvo decisión unánime del Consejo Europeo, la Comisión tiene un número de miembros igual a:', array['Los dos tercios del número de Estados miembros', 'Un nacional de cada Estado miembro', 'La mitad del número de Estados miembros', 'Los tres quintos del número de Estados miembros']::text[], 0, 'El artículo 17.5 TUE dice que la Comisión estará compuesta «por un número de miembros correspondiente a los dos tercios del número de Estados miembros» salvo que el Consejo Europeo decida por unanimidad modificar dicho número.', 3, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
