insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-020', (select id from leyes where slug = 'tue'), '17.7', 'Si el candidato a Presidente de la Comisión no obtiene la mayoría necesaria en el Parlamento, el Consejo Europeo propondrá otro en el plazo de:', array['Quince días', 'Un mes', 'Dos meses', 'Seis semanas']::text[], 1, 'El artículo 17.7 TUE dice: «Si el candidato no obtiene la mayoría necesaria, el Consejo Europeo propondrá en el plazo de un mes, por mayoría cualificada, un nuevo candidato […]».', 3, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
