insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-021', (select id from leyes where slug = 'tue'), '19.2', 'Los jueces del Tribunal de Justicia son nombrados para un período de:', array['Cinco años', 'Seis años', 'Nueve años', 'Cuatro años']::text[], 1, 'El artículo 19.2 TUE dice que serán «nombrados de común acuerdo por los Gobiernos de los Estados miembros para un período de seis años».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
