insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-022', (select id from leyes where slug = 'tue'), '19.1', 'Según el TUE, el Tribunal de Justicia de la Unión Europea comprende:', array['El Tribunal de Justicia, el Tribunal de Cuentas y el Tribunal General', 'El Tribunal de Justicia y los tribunales nacionales', 'El Tribunal de Justicia, el Tribunal General y los tribunales especializados', 'El Tribunal General, los abogados generales y el Defensor del Pueblo']::text[], 2, 'El artículo 19.1 TUE dice: «El Tribunal de Justicia de la Unión Europea comprenderá el Tribunal de Justicia, el Tribunal General y los tribunales especializados».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
