insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-024', (select id from leyes where slug = 'tfue'), '234', '¿Cuándo puede pronunciarse el Parlamento Europeo sobre una moción de censura contra la Comisión?', array['Transcurridos tres días como mínimo desde su presentación', 'Transcurridas cuarenta y ocho horas desde su presentación', 'Transcurridos cinco días como mínimo desde su presentación', 'En la misma sesión en que se presente']::text[], 0, 'El artículo 234 TFUE dice que el Parlamento «sólo podrá pronunciarse sobre dicha moción transcurridos tres días como mínimo desde la fecha de su presentación y en votación pública».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
