insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-025', (select id from leyes where slug = 'tfue'), '229', 'El Parlamento Europeo se reúne sin necesidad de previa convocatoria:', array['El primer martes de marzo', 'El segundo martes de septiembre', 'El primer lunes de enero', 'El segundo martes de marzo']::text[], 3, 'El artículo 229 TFUE dice que el Parlamento «Se reunirá sin necesidad de previa convocatoria el segundo martes de marzo».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
