insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-026', (select id from leyes where slug = 'tfue'), '226', 'El Parlamento Europeo puede constituir una comisión temporal de investigación a petición de:', array['La tercera parte de sus miembros', 'La cuarta parte de sus miembros', 'La mayoría de sus miembros', 'La quinta parte de sus miembros']::text[], 1, 'El artículo 226 TFUE dice: «a petición de la cuarta parte de los miembros que lo componen, el Parlamento Europeo podrá constituir una comisión temporal de investigación […]».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
