insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-029', (select id from leyes where slug = 'tfue'), '288', 'Según el TFUE, ¿qué actos de la Unión no son vinculantes?', array['Las recomendaciones y los dictámenes', 'Las decisiones y los dictámenes', 'Las directivas y las recomendaciones', 'Los reglamentos y las decisiones']::text[], 0, 'El artículo 288 TFUE dice: «Las recomendaciones y los dictámenes no serán vinculantes».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
