insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-012', null, 'Modificar un estilo actualizándolo para que coincida con el formato del documento', 'Ha cambiado el formato de un texto con estilo Título 1. Para que el estilo adopte ese formato, haga clic con el botón derecho en el estilo y elija:', array['Modificar el estilo Título 1', 'Crear un estilo a partir de Título 1', 'Aplicar el estilo Normal a Título 1', 'Actualizar Título 1 para que coincida con la selección']::text[], 3, 'En el grupo Estilos se hace clic con el botón derecho en el estilo y se elige «Actualizar [nombre de estilo] para que coincida con la selección».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
