insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-013', null, 'Modificar un estilo actualizándolo para que coincida con el formato del documento', 'Si modifica un estilo de la galería, ¿qué ocurre con el texto que ya tiene ese estilo?', array['Cambia automáticamente al nuevo formato', 'Conserva el formato anterior', 'Solo cambia el párrafo seleccionado', 'Pasa a tener el estilo Normal']::text[], 0, 'La página advierte: «Todo el texto con el estilo que haya cambiado cambiará automáticamente para coincidir con el nuevo estilo definido».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
