insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-014', null, 'Crear un estilo basado en el formato del documento', 'Al crear un estilo desde la minibarra de herramientas (Estilos > Crear un estilo), ¿qué cuadro de diálogo se abre?', array['Modificar estilo', 'Crear nuevo estilo a partir del formato', 'Panel de tareas Aplicar estilos', 'Panel de tareas Mostrar formato']::text[], 1, 'Tras elegir Crear un estilo, «En el cuadro de diálogo Crear nuevo estilo a partir del formato , asigne un nombre al estilo y haga clic en Aceptar».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
