insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-015', null, 'Crear un estilo basado en el formato del documento', 'Para que un estilo nuevo aparezca en los documentos nuevos, ¿qué opción se marca en el cuadro Modificar?', array['Documentos nuevos basados en esta plantilla', 'Agregar a la galería de estilos', 'Actualizar automáticamente', 'Solo en este documento']::text[], 0, 'Hay que hacer clic en Modificar y seleccionar «Documentos nuevos basados en esta plantilla en la parte inferior del cuadro de diálogo».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
