insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-017', null, 'Activar y desactivar el control de cambios', 'Con el Control de cambios activado, ¿cómo se marcan las eliminaciones?', array['Con un tachado', 'Con un subrayado', 'Con un resaltado amarillo', 'Con letra cursiva']::text[], 0, 'Según la página, «Las eliminaciones se marcan con un tachado y las adiciones se marcan con un subrayado».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
