insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-019', null, 'Elija la forma en que se muestra el control de cambios', 'Para ver las marcas de revisión en globos, el documento debe estar en la vista:', array['Borrador o Esquema', 'Modo Lectura o Borrador', 'Esquema o Modo Lectura', 'Diseño de impresión o Diseño web']::text[], 3, 'La nota dice: «Si desea ver las marcas de revisión en globos, debe estar en la vista Diseño de impresión o Diseño web».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
