insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-022', null, 'Usar la combinación de correspondencia de correo electrónico masivo, cartas, etiquetas y sobres', 'En la combinación de correspondencia, ¿cómo se llaman los marcadores de posición que indican dónde va la información del origen de datos?', array['Bloques de Autotexto', 'Marcadores', 'Campos de formulario', 'Campos de combinación']::text[], 3, 'La página explica que «Los marcadores de posición (denominados campos de combinación) indican a Word en qué parte del documento incluir información del origen de datos».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
