insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-026', null, 'Imprimir páginas determinadas', 'Para imprimir la página 3 y de la 4 a la 6, en Impresión personalizada se escribe en el cuadro Páginas:', array['3, 4-6', '3; 4/6', '3 + 4:6', '3 y 4 a 6']::text[], 0, 'Se elige Impresión personalizada y se escriben «los números de página y los intervalos separados por comas (por ejemplo 3, 4-6)».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
