insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-027', null, 'Imprimir los comentarios del documento', 'Para imprimir un documento con sus comentarios, ¿qué se selecciona en Configuración?', array['Imprimir página actual', 'Imprimir documento con revisiones', 'Impresión personalizada', 'Imprimir todas las páginas']::text[], 1, 'La página indica: «En Configuración , seleccione Imprimir documento con revisiones». Después se selecciona Imprimir.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
