insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-028', null, 'Obtener una vista previa del documento', 'En Word para Windows, ¿desde dónde se obtiene una vista previa del documento antes de imprimirlo?', array['Vista > Modo Lectura', 'Disposición > Márgenes', 'Archivo > Imprimir', 'Revisar > Mostrar marcado']::text[], 2, 'La vista previa se obtiene en Archivo > Imprimir: «Para obtener una vista previa de cada página, seleccione las flechas hacia delante y hacia atrás en la parte inferior de la página».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
