insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-029', null, 'Guardar un documento', '¿Dónde debe estar guardado un documento para que Word guarde todos los cambios automáticamente?', array['En el escritorio del equipo', 'En la carpeta Documentos local', 'En una unidad USB externa', 'En OneDrive o SharePoint']::text[], 3, 'La página indica: «Al guardar en OneDrive o SharePoint, todos los cambios se guardan automáticamente».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
