insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('wrd-030', null, 'Guardar un documento', '¿Dónde se puede activar o desactivar el Autoguardado en Word?', array['En el menú contextual de la barra de estado', 'En la pestaña Revisar, grupo Seguimiento', 'En la barra de herramientas de acceso rápido', 'En la pestaña Vista, grupo Ventana']::text[], 2, 'Según la página, «Puede activar o desactivar Autoguardado en la barra de herramientas de acceso rápido, ya sea encima o debajo de la cinta de opciones».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
